def _rotulo_metodo_rota(fonte_rota):
    """[METODO-TELA - 57ª geração / item #8] Rótulo legível do MÉTODO da distância, derivado de
    'Fonte da Rota' já calculada (custo ZERO, sem chamada nova). Google prioritário → OSRM fallback;
    quando nenhum motor viário respondeu, a distância exibida é a linha reta geodésica (GeographicLib).
    Padroniza o texto mostrado na TELA do Validador Rápido e da Alocação (spec do item #8)."""
    _fr = str(fonte_rota or "").upper()
    if "GOOGLE" in _fr:
        return "Distância viária (Google Maps)"
    if "OSRM" in _fr:
        return "Distância viária (OSRM - fallback)"
    if "GEOD" in _fr:
        return "Linha reta (GeographicLib)"
    if _fr and _fr not in ("DESCONHECIDA", "N/A", "NAO INFORMADA"):
        return f"Distância viária ({fonte_rota})"
    return "N/A"


def _classificar_modo_acesso(fonte_rota, balsa, lat_o, lon_o, lat_d, lon_d):
    """[INTEL-TERRITORIAL - 111ª geração] Classifica o MODO/ACESSO da rota a partir dos sinais que a
    aplicação já tem (custo ZERO, sem dados externos):
      • 'Rodoviário'                 → um motor viário (Google/OSRM) traçou a rota.
      • 'Rodoviário + Balsa'         → rota viária que cruza travessia por balsa.
      • '🛶 Possível fluvial/isolado' → geocodificação OK (coords válidas), mas NENHUM motor viário retornou
                                        rota → pode ser município sem acesso rodoviário (ex.: 43/62 no AM).
      • 'Estimado (geodésico)'       → fallback geodésico sem coordenadas válidas suficientes.
    PURA e determinística (testável)."""
    _fr = str(fonte_rota or "").upper()
    _eh_geo = "GEOD" in _fr
    _tem_balsa = str(balsa or "").strip().lower() in ("sim", "yes", "true", "1")

    def _num(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return 0.0
    _geo_ok = bool((_num(lat_o) or _num(lon_o)) and (_num(lat_d) or _num(lon_d)))
    if not _eh_geo:
        return "Rodoviário + Balsa" if _tem_balsa else "Rodoviário"
    return "🛶 Possível fluvial/isolado" if _geo_ok else "Estimado (geodésico)"


def _link_osrm_publico(lat_o, lon_o, lat_d, lon_d):
    """[VIS - 115ª geração] Link STANDALONE do visualizador público do OSRM (map.project-osrm.org) com a
    rota entre origem e destino — o equivalente OSRM ao link de direções do Google Maps, para uso em
    PLANILHAS exportadas (Lote/Hubs). Ao contrário do link_osrm_viewer (relativo ao app, só embarcado),
    este é uma URL absoluta que abre a rota do OSRM de qualquer lugar. Retorna "" se coordenadas inválidas."""
    def _n(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return None
    _lo, _lno, _ld, _lnd = _n(lat_o), _n(lon_o), _n(lat_d), _n(lon_d)
    if None in (_lo, _lno, _ld, _lnd):
        return ""
    if (_lo == 0 and _lno == 0) or (_ld == 0 and _lnd == 0):
        return ""
    return (f"https://map.project-osrm.org/?loc={_lo:.6f}%2C{_lno:.6f}"
            f"&loc={_ld:.6f}%2C{_lnd:.6f}&hl=pt-BR&alt=0&srv=0")


# [AQUAVIARIA - 116ª geração] MATRIZ AQUAVIÁRIA PRÉ-CALCULADA (opcional/gated). Não há API pública nem faz
# sentido embarcar um roteador (pgRouting/OSRM exigem servidor externo — quebram o modelo single-file).
# O caminho proporcional e AUDITÁVEL é consumir uma MATRIZ pré-calculada no QGIS a partir dos shapes
# oficiais (ANTAQ/BIT): tabela rotas_aqua(orig, dest, km) por par de Códigos IBGE. Desligada por padrão.
AQUAVIARIA_ATIVA = False


def _distancia_aquaviaria(cod_o, cod_d, provider=None):
    """[AQUAVIARIA - 116ª geração] Distância AQUAVIÁRIA (km) entre dois municípios por par de Códigos IBGE,
    a partir de uma MATRIZ pré-calculada. Retorna km (float) ou None. SIMÉTRICA. `provider` injetável
    (o,d)->km|None; default = SQLite bundleado. PURA em relação ao provider; só age com AQUAVIARIA_ATIVA."""
    if provider is None and not AQUAVIARIA_ATIVA:
        return None
    if provider is None:
        provider = _aquaviaria_provider_sqlite if "_aquaviaria_provider_sqlite" in globals() else None
    if provider is None:
        return None
    _o, _d = str(cod_o or "").strip(), str(cod_d or "").strip()
    if not _o or not _d:
        return None
    try:
        _km = provider(_o, _d)
        if _km is None:
            _km = provider(_d, _o)  # simetria direção-independente
        return round(float(_km), 2) if _km is not None else None
    except Exception:
        return None


@st.cache_resource(show_spinner=False)
def _aquaviaria_conectar():
    """[AQUAVIARIA - 116ª geração] Abre (somente leitura) o SQLite da matriz aquaviária bundleada, se
    existir (via AQUAVIARIA_DB_PATH em secrets/env, ou ao lado do app). Retorna a conexão ou None."""
    import os as _os, sqlite3 as _sq
    _cands = []
    try:
        if "AQUAVIARIA_DB_PATH" in st.secrets:
            _cands.append(str(st.secrets["AQUAVIARIA_DB_PATH"]))
    except Exception:
        pass
    _env = _os.environ.get("AQUAVIARIA_DB_PATH", "")
    if _env:
        _cands.append(_env)
    try:
        _here = _os.path.dirname(_os.path.abspath(__file__))
    except Exception:
        _here = "."
    _cands += ["aquaviaria.sqlite", _os.path.join(_here, "aquaviaria.sqlite")]
    for _p in _cands:
        if _p and _os.path.exists(_p):
            try:
                return _sq.connect(f"file:{_p}?mode=ro", uri=True, check_same_thread=False)
            except Exception:
                continue
    return None


def _aquaviaria_provider_sqlite(orig, dest, conn=None):
    """[AQUAVIARIA - 116ª geração] Provider concreto: consulta a tabela 'rotas_aqua'(orig, dest, km) por
    par → km ou None. `conn` injetável para teste; defensivo a banco/tabela ausente."""
    _c = conn if conn is not None else (_aquaviaria_conectar() if "_aquaviaria_conectar" in globals() else None)
    if _c is None:
        return None
    try:
        _row = _c.execute("SELECT km FROM rotas_aqua WHERE orig=? AND dest=?",
                          (int(orig), int(dest))).fetchone()
        return _row[0] if _row else None
    except Exception:
        return None


