def _municipio_acesso_fluvial(cod_ibge, conjunto=None):
    """[INTEL-TERRITORIAL - 111ª geração] O município (Código IBGE) consta na lista oficial de acesso
    fluvial/isolado? Retorna bool. `conjunto` injetável para teste; default = _MUNICIPIOS_ACESSO_FLUVIAL
    (só consultado com FLUVIAL_LISTA_ATIVA). PURA em relação ao conjunto (testável)."""
    if conjunto is None:
        if not FLUVIAL_LISTA_ATIVA:
            return False
        conjunto = _MUNICIPIOS_ACESSO_FLUVIAL
    _c = str(cod_ibge or "").strip()
    return bool(_c) and _c in (conjunto or frozenset())


def _analise_hidrica_por_uf(df):
    """[INTEL-TERRITORIAL - 113ª geração] Agrega, por UF de origem, indicadores hídricos da planilha
    processada: total de rotas, rotas com balsa/ferry e rotas de acesso fluvial/isolado. Retorna um
    DataFrame ordenado por 'Com Balsa' (desc). PURO (não usa Streamlit); vazio se faltam colunas/dados."""
    import pandas as _pd
    if df is None or len(df) == 0:
        return _pd.DataFrame()
    _uf_col = "UF Origem" if "UF Origem" in df.columns else ("UF" if "UF" in df.columns else None)
    if _uf_col is None:
        return _pd.DataFrame()
    _d = df.copy()
    _d["_uf"] = _d[_uf_col].fillna("").astype(str).str.strip().replace("", "N/A")
    if "Balsas" in _d.columns:
        _d["_balsa"] = _d["Balsas"].fillna("").astype(str).str.strip().str.lower().isin(["sim", "yes", "true", "1"])
    else:
        _d["_balsa"] = False
    if "Modo/Acesso" in _d.columns:
        _d["_fluvial"] = _d["Modo/Acesso"].fillna("").astype(str).str.contains("fluvial", case=False, na=False)
    else:
        _d["_fluvial"] = False
    _g = _d.groupby("_uf").agg(Rotas=("_uf", "size"), **{"Com Balsa": ("_balsa", "sum"),
                                                          "Acesso Fluvial/Isolado": ("_fluvial", "sum")}).reset_index()
    _g = _g.rename(columns={"_uf": "UF"})
    _g["% com Balsa"] = (_g["Com Balsa"] / _g["Rotas"] * 100).round(1)
    _g = _g.sort_values(["Com Balsa", "Rotas"], ascending=False).reset_index(drop=True)
    return _g


def _montar_corpo_pesquisa(respostas, nota):
    """[PESQUISA - 73ª geração] Formata as respostas da Pesquisa de Satisfação num assunto + corpo de
    e-mail legível. PURO e determinístico (sem data/estado) — testável. respostas: dict {rótulo: valor}
    (ordem preservada). Retorna (assunto, corpo)."""
    assunto = f"[Pesquisa de Satisfação] Nota {nota}/10 — Motor de Roteirização Inteligente"
    _linhas = ["Nova avaliação da aplicação:", ""]
    for _rot, _val in (respostas or {}).items():
        _v = _val if (_val is not None and str(_val).strip() != "") else "—"
        _linhas.append(f"- {_rot}: {_v}")
    return assunto, "\n".join(_linhas)


def _mailto_pesquisa(email_destino, assunto, corpo):
    """[PESQUISA - 73ª geração] Monta um link mailto: para o e-mail do produtor, com assunto e corpo
    já preenchidos. PURO. Funciona SEM backend (abre o cliente de e-mail do usuário) — a forma mais
    robusta e sem dependências de entregar a avaliação. O endereço fica literal (padrão mailto); apenas
    subject e body são URL-encoded."""
    from urllib.parse import quote
    return f"mailto:{str(email_destino or '').strip()}?subject={quote(assunto)}&body={quote(corpo)}"


def _parse_tempo_min(tempo_str):
    """[CONC-AUDIT - 77ª geração] Converte um tempo formatado ('45 min', '1 h 20 min', '2 h') em
    MINUTOS (float), ou None se não parsear. PURO — base para a velocidade média implícita."""
    import re as _re
    if not tempo_str:
        return None
    _s = str(tempo_str).lower()
    _h = _re.search(r'(\d+)\s*h', _s)
    _m = _re.search(r'(\d+)\s*min', _s)
    if not _h and not _m:
        _n = _re.search(r'(\d+)', _s)
        return float(_n.group(1)) if _n else None
    _total = (int(_h.group(1)) if _h else 0) * 60 + (int(_m.group(1)) if _m else 0)
    return float(_total) if _total > 0 else None


def _velocidade_media_kmh(dist_km, tempo_str):
    """[CONC-AUDIT - 77ª geração] Velocidade média implícita (km/h) = distância / tempo. PURO.
    Retorna 0.0 se o tempo não parsear ou for zero."""
    _min = _parse_tempo_min(tempo_str)
    try:
        _d = float(dist_km)
    except (TypeError, ValueError):
        return 0.0
    if not _min or _min <= 0 or _d <= 0:
        return 0.0
    return round(_d * 60.0 / _min, 1)


METRICAS_DISTANCIA = {
    "total_calculos": 0,
    "sucesso_geographiclib": 0,
    "sucesso_geopy": 0,
    "fallback_haversine": 0,
    "correcoes_automaticas": 0,
    "falhas_criticas": 0,
    "cache_unpoisoned": 0,
    "barreira_territorial": 0,
    "desambiguacoes_estritas": 0,
    "_inicio_metricas": time.time()  # [M24] timestamp para cálculo de taxa por período
}

_LOCK_METRICAS = threading.Lock()

# [CIRCUIT-BREAKER - 184ª geração] Estado global thread-safe do disjuntor do Google. O roteamento é paralelo
# (múltiplas threads chamando o scraper), então o estado do breaker é compartilhado e protegido por lock. Ver
# _circuit_breaker_google (máquina de estados pura) e _google_pode_chamar/_google_registrar_resultado (acesso
# thread-safe usados pelo scraper). Quando o Google está saudável, o breaker fica 'fechado' e é transparente.
_LOCK_GOOGLE_CB = threading.Lock()
_GOOGLE_CB_ESTADO = {"status": "fechado", "falhas_seguidas": 0, "aberto_ate": 0.0}


def _google_pode_chamar(agora=None):
    """Consulta thread-safe se o disjuntor permite chamar o Google agora. Aplica transições por tempo (ex.:
    aberto→meio_aberto após o cooldown). Retorna bool."""
    import time as _t
    _now = agora if agora is not None else _t.time()
    try:
        with _LOCK_GOOGLE_CB:
            global _GOOGLE_CB_ESTADO
            # avalia transição por tempo sem registrar resultado de chamada (sucesso=None)
            _GOOGLE_CB_ESTADO, _pode = _circuit_breaker_google(_GOOGLE_CB_ESTADO, None, _now)
            return bool(_pode)
    except Exception:
        return True  # em dúvida, permite (nunca bloqueia o Google por erro do próprio breaker)


def _google_politica_adaptativa():
    """[CORE-ADAPTATIVO - 202ª geração] Decide AUTOMATICAMENTE (sem toggle) o quão "paciente" o Google deve
    ser NESTA chamada, com base na SAÚDE dele (disjuntor) — absorve o antigo "Modo Google agressivo" como
    comportamento NATIVO e transparente, sem regressão de velocidade:
      • Google SAUDÁVEL (disjuntor fechado = vem respondendo) → paciência ALTA (timeout 8s, 3 perfis, priming
        de sessão) → maximiza a participação do Google JUSTAMENTE quando ela está valendo a pena.
      • Google FALHANDO (disjuntor aberto/meio-aberto) → FAST-FAIL (timeout 4s, 1 tentativa, ignora o Google
        rápido e deixa o OSRM assumir) → ZERO lentidão quando o Google está bloqueado.
    O toggle manual 'google_agressivo' vira só um OVERRIDE opcional (força paciência mesmo com disjuntor
    aberto), para quem quiser — mas não é mais NECESSÁRIO: o núcleo já faz a coisa certa sozinho.
    Retorna dict {timeout, tentativas, primar, ignora_disjuntor, motivo}. Defensiva: em erro, devolve o
    perfil rápido (nunca trava)."""
    try:
        _forcar = False
        try:
            _forcar = _ler_flag_runtime('google_agressivo')  # override manual opcional
        except Exception:
            _forcar = False
        _saudavel = False
        try:
            _saudavel = _google_pode_chamar()  # disjuntor fechado = Google vem respondendo
        except Exception:
            _saudavel = True
        if _forcar:
            return {"timeout": 12, "tentativas": 3, "primar": True, "ignora_disjuntor": True,
                    "motivo": "override manual (force paciência)"}
        if _saudavel:
            # paciência automática — Google está respondendo, vale investir para ele participar/vencer
            return {"timeout": 8, "tentativas": 3, "primar": True, "ignora_disjuntor": False,
                    "motivo": "adaptativo: Google saudável → paciência"}
        # Google falhando → rápido, sem penalizar a velocidade do lote
        return {"timeout": 4, "tentativas": 1, "primar": False, "ignora_disjuntor": False,
                "motivo": "adaptativo: Google falhando → fast-fail"}
    except Exception:
        return {"timeout": 4, "tentativas": 1, "primar": False, "ignora_disjuntor": False,
                "motivo": "fallback seguro"}


def _google_registrar_resultado(sucesso, agora=None):
    """Registra thread-safe o resultado de uma chamada ao Google (True/False), atualizando o disjuntor."""
    import time as _t
    _now = agora if agora is not None else _t.time()
    try:
        with _LOCK_GOOGLE_CB:
            global _GOOGLE_CB_ESTADO
            _GOOGLE_CB_ESTADO, _ = _circuit_breaker_google(_GOOGLE_CB_ESTADO, bool(sucesso), _now)
    except Exception:
        pass


def _incrementar_metrica(campo: str, valor: int = 1):
    with _LOCK_METRICAS:
        METRICAS_DISTANCIA[campo] += valor

