            f'function esc(v){{v=(v==null?"":String(v));if(/[";\\n]/.test(v))v=\'"\'+v.replace(/"/g,\'""\')+\'"\';return v;}}'
            f'var linhas=[cols.map(function(c){{return esc(c[0]);}}).join(";")];'
