            f'var val=r[c[1]];if(c[1]==="km"&&val!=null)val=fmt(val,1);return esc(val);}}).join(";"));}}'
            f'var csv="\\ufeff"+linhas.join("\\r\\n");'  # BOM p/ Excel abrir com acentos corretos
            f'var blob=new Blob([csv],{{type:"text/csv;charset=utf-8;"}});'
