            f'if(k==="uf")setSel(elUF,v);else if(k==="f")setSel(elF,v);else if(k==="b")setSel(elB,v);'
            f'else if(k==="polo")setSel(elPolo,v);else if(k==="busca"&&elBusca)elBusca.value=v;'
