            ".bi-drill .bi-drill-close{float:right;cursor:pointer;color:var(--muted);font-size:22px;line-height:1;border:none;background:none}"
            ".bi-drill-grid{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}"
