CONFIANCA_BAIXA     = "BAIXA"
CONFIANCA_REVISAO   = "REVISAO_MANUAL"
CONFIANCA_MUNICIPAL = "MUNICIPAL"
CONFIANCA_ABSOLUTA  = "ABSOLUTA"

# ==============================================================================
# PERSISTÊNCIA EM DISCO E HIGIENIZAÇÃO DE AMBIENTE (GARBAGE COLLECTION)
