def _perfil_estudo(linhas, lado="app", parse_tempo=None):
    """[PERFIL - 166ª geração] PERFIL AUTÔNOMO de um estudo — como se ele existisse sozinho.

    ── O BURACO QUE ISTO FECHA ──
    Até a 165ª o concorrente só existia EM RELAÇÃO A NÓS ("onde ele venceu"). Ele nunca ganhava um perfil
    PRÓPRIO. E sem perfil, perguntas centrais ficavam sem resposta: **qual estudo evita mais balsas? qual
    tem a menor sinuosidade média? qual usa menos locais de prova?** Não dá para responder isso comparando
    linha a linha — só olhando cada estudo como um TODO.

    ── LIMITE HONESTO (e ele importa) ──
    Do NOSSO estudo eu sei tudo (balsa, sinuosidade, modo de acesso, tempo, coordenadas). Do CONCORRENTE eu
    só sei **o que a planilha dele trouxe**. Se ela não tem coluna de balsa, **eu NÃO POSSO inventar uma
    taxa de balsa para ele** — e não vou. Os campos indisponíveis vêm marcados como "não informado", nunca
    como zero. Zero e "não sei" são coisas DIFERENTES, e confundi-los seria mentir com números.

    lado: "app" (nosso estudo) ou "ref" (concorrente). PURO."""
    parse_tempo = parse_tempo or _parse_tempo_min
    _p = "Aplicacao" if lado == "app" else "Referencia"
    _dados = []
    for l in (linhas or []):
        try:
            _d = float(l.get(f"Distancia {_p}"))
        except (TypeError, ValueError):
            continue
        if _d <= 0:
            continue
        _dados.append({
            "dist": _d, "insc": float(l.get("Inscritos") or 0),
            "uf": str(l.get("UF") or "—"),
            "polo": str(l.get(f"Destino {_p}") or "—"),
            "tempo": parse_tempo(l.get(f"Tempo {_p}")) if l.get(f"Tempo {_p}") not in (None, "") else None,
            "balsa": (str(l.get("Balsa Aplicacao", "")).strip().lower() in ("sim", "yes", "true", "1")
                      if lado == "app" else None),
            "sinu": (float(l["Sinuosidade Aplicacao"])
                     if lado == "app" and l.get("Sinuosidade Aplicacao") not in (None, "") else None),
            "tipo": str(l.get("Tipo de Distancia", "")) if lado == "app" else "",
        })
    if not _dados:
        return {}

    import numpy as np
    _dd = np.array([x["dist"] for x in _dados], dtype=float)
    _ww = np.array([max(x["insc"], 1.0) for x in _dados], dtype=float)
    _cand = int(sum(x["insc"] for x in _dados))
    _polos = {x["polo"] for x in _dados if x["polo"] and x["polo"] != "—"}

    # mediana PONDERADA por candidato (não por linha — é gente que importa)
    _ordem = np.argsort(_dd)
    _acum = np.cumsum(_ww[_ordem])
    _med = float(_dd[_ordem][np.searchsorted(_acum, _acum[-1] / 2.0)]) if len(_dd) else 0.0

    _tempos = [x["tempo"] for x in _dados if x["tempo"] is not None]
    _balsas = [x["balsa"] for x in _dados if x["balsa"] is not None]
    _sinus = [x["sinu"] for x in _dados if x["sinu"] is not None]

    _faixas = {}
    for _lim, _rot in ((50, "≤50 km"), (100, "50-100 km"), (200, "100-200 km"),
                       (400, "200-400 km"), (10 ** 9, ">400 km")):
        _sel = [x for x in _dados if x["dist"] <= _lim]
        _faixas[_rot] = int(sum(x["insc"] for x in _sel))
    _ant = 0
    for _k in list(_faixas):
        _v = _faixas[_k]
        _faixas[_k] = _v - _ant
        _ant = _v

    _por_uf = {}
    for x in _dados:
        _a = _por_uf.setdefault(x["uf"], {"UF": x["uf"], "municipios": 0, "candidatos": 0, "_km": 0.0, "_w": 0.0})
        _a["municipios"] += 1
        _a["candidatos"] += int(x["insc"])
        _a["_km"] += x["dist"] * max(x["insc"], 1)
        _a["_w"] += max(x["insc"], 1)
    _ufs = []
    for _a in _por_uf.values():
        _a["dist_media_km"] = round(_a["_km"] / _a["_w"], 1) if _a["_w"] else 0.0
        _a.pop("_km", None)
        _a.pop("_w", None)
        _ufs.append(_a)
    _ufs.sort(key=lambda x: -x["candidatos"])

    return {
        "estudo": "Nossa aplicação" if lado == "app" else "Estudo concorrente",
        "municipios": len(_dados), "candidatos": _cand,
        "locais_de_prova": len(_polos),
        "dist_media_km": round(float(np.average(_dd, weights=_ww)), 1),
        "dist_mediana_km": round(_med, 1),
        "dist_minima_km": round(float(_dd.min()), 1),
        "dist_maxima_km": round(float(_dd.max()), 1),
        "dist_desvio_km": round(float(_dd.std(ddof=1)), 1) if len(_dd) > 1 else 0.0,
        "km_candidato_total": round(float((_dd * _ww).sum()), 1),
        "tempo_medio_min": round(sum(_tempos) / len(_tempos), 1) if _tempos else None,
        "tempo_minimo_min": round(min(_tempos), 1) if _tempos else None,
        "tempo_maximo_min": round(max(_tempos), 1) if _tempos else None,
        "pct_com_balsa": (round(100.0 * sum(_balsas) / len(_balsas), 1) if _balsas else None),
        "pct_so_rodoviario": (round(100.0 * (len(_balsas) - sum(_balsas)) / len(_balsas), 1)
                              if _balsas else None),
        "sinuosidade_media": (round(sum(_sinus) / len(_sinus), 2) if _sinus else None),
        "faixas_candidatos": _faixas,
        "por_uf": _ufs[:20],
        # o que NÃO foi informado — dito na cara, nunca como zero
        "campos_indisponiveis": [_c for _c, _v in (("uso de balsa", _balsas), ("sinuosidade", _sinus),
                                                   ("tempo", _tempos)) if not _v],
    }


def _diagnostico_imparcial(linhas):
    """[PERFIL - 166ª geração] O PARECER IMPARCIAL: responde as perguntas que decidem, com o mesmo rigor
    para os dois estudos. E responde a MAIS AFIADA delas:

        **"O concorrente é melhor de forma CONSISTENTE, ou só em casos específicos?"**

    Isso não é opinião — é medível. Se as vitórias dele estão CONCENTRADAS em poucos municípios (Pareto
    curto), a vantagem é PONTUAL: revise aqueles casos e o problema some. Se estão ESPALHADAS, a vantagem é
    SISTEMÁTICA: há algo no MÉTODO dele que é melhor, e ignorar isso é teimosia.

    E também: **existe padrão GEOGRÁFICO?** Se as vitórias dele se concentram numa região muito além do peso
    dela no estudo, não é acaso — é sinal de que naquela região o método dele funciona melhor (malha viária,
    balsa, relevo). PURO."""
    _ok = [l for l in (linhas or []) if l.get("Vencedor Distancia") in ("Aplicação", "Referência", "Empate")]
    if not _ok:
        return {}
    _app = _perfil_estudo(_ok, "app")
    _ref = _perfil_estudo(_ok, "ref")

    _v_app = [l for l in _ok if l.get("Vencedor Distancia") == "Aplicação"]
    _v_ref = [l for l in _ok if l.get("Vencedor Distancia") == "Referência"]
    _emp = [l for l in _ok if l.get("Vencedor Distancia") == "Empate"]

    # ---- consistência da vantagem do concorrente: Pareto das vitórias dele ----
    _consist = None
    if _v_ref:
        _g = sorted((abs(float(l.get("Economia km x Inscritos") or 0)) for l in _v_ref), reverse=True)
        _tot = sum(_g) or 1.0
        _acum, _n80 = 0.0, len(_g)
        for _i, _x in enumerate(_g, start=1):
            _acum += _x
            if _acum >= 0.8 * _tot:
                _n80 = _i
                break
        _pct_para_80 = 100.0 * _n80 / len(_g)
        # [PERFIL - 166ª geração] CRITÉRIO CORRIGIDO. O percentual sozinho falha com n pequeno: com 3
        # vitórias, 1 delas = 33% — e o teste classificava como "sistemática" um caso em que UM único
        # município explicava 99,95% do ganho. O sinal decisivo não é só a porcentagem: é **se UM caso
        # DOMINA**. Se a maior vitória sozinha vale metade ou mais do ganho dele, a vantagem é PONTUAL,
        # não importa quantas vitórias existam.
        _share_maior = (_g[0] / _tot) if _g else 0.0
        _e_pontual = (_share_maior >= 0.5) or (_pct_para_80 <= 30)
        _consist = {
            "n_vitorias": len(_v_ref), "n_para_80pct": _n80,
            "pct_das_vitorias_para_80": round(_pct_para_80, 1),
            "share_maior_vitoria_pct": round(100.0 * _share_maior, 1),
            "veredito": ("PONTUAL" if _e_pontual else "SISTEMÁTICA"),
            "leitura": (
                f"A vantagem do concorrente é **PONTUAL**: apenas **{_n80} das {len(_g)} vitórias dele** "
                f"({_pct_para_80:.0f}%) concentram 80% do ganho — e a MAIOR delas sozinha vale "
                f"**{100 * _share_maior:.0f}%** do total. **Revise esses poucos casos e o problema "
                "praticamente some** — não há nada de estrutural no método dele."
                if _e_pontual else
                f"A vantagem do concorrente é **SISTEMÁTICA**: o ganho dele está ESPALHADO por "
                f"{len(_g)} vitórias (são precisas {_n80} — {_pct_para_80:.0f}% delas — para chegar a 80%). "
                "Isso não é sorte pontual: **há algo no MÉTODO dele que funciona melhor**, e vale entender "
                "o quê antes de descartá-lo."),
        }

    # ---- padrão geográfico: as vitórias dele se concentram em alguma região? ----
    _geo = None
    if _v_ref:
        _reg_tot, _reg_ref = {}, {}
        for l in _ok:
            _r = _UF_PARA_REGIAO.get(str(l.get("UF") or "").upper(), "Indefinido")
            _reg_tot[_r] = _reg_tot.get(_r, 0) + 1
        for l in _v_ref:
            _r = _UF_PARA_REGIAO.get(str(l.get("UF") or "").upper(), "Indefinido")
            _reg_ref[_r] = _reg_ref.get(_r, 0) + 1
        _linhas_geo = []
        for _r, _n in sorted(_reg_tot.items(), key=lambda kv: -kv[1]):
            _vr = _reg_ref.get(_r, 0)
            _taxa = 100.0 * _vr / _n if _n else 0.0
            _linhas_geo.append({"Região": _r, "Municípios comparados": _n,
                                "Vitórias do concorrente": _vr,
                                "Taxa de vitória dele (%)": round(_taxa, 1)})
        _taxa_geral = 100.0 * len(_v_ref) / len(_ok)
        _destaque = max(_linhas_geo, key=lambda x: x["Taxa de vitória dele (%)"]) if _linhas_geo else None
        _tem_padrao = bool(_destaque and _destaque["Municípios comparados"] >= 5
                           and _destaque["Taxa de vitória dele (%)"] > _taxa_geral * 1.5)
        _geo = {
            "por_regiao": _linhas_geo, "taxa_geral_pct": round(_taxa_geral, 1),
            "tem_padrao": _tem_padrao,
            "leitura": (
                f"🌎 **Há um PADRÃO GEOGRÁFICO.** O concorrente vence em "
                f"**{_destaque['Taxa de vitória dele (%)']}% dos municípios do {_destaque['Região']}**, "
                f"contra {_taxa_geral:.0f}% no país. Isso não é acaso: naquela região o método dele lida "
                "melhor com alguma coisa — malha viária, balsa, relevo. **Vale investigar o quê.**"
                if _tem_padrao else
                "🌎 **Não há padrão geográfico claro:** as vitórias do concorrente se distribuem de forma "
                "parecida com o peso de cada região no estudo. A diferença entre os estudos não é regional.")
        }

    # ---- quem reduz mais o quê ----
    _resp = []
    if _app and _ref:
        _q1 = ("A NOSSA aplicação" if _app["km_candidato_total"] < _ref["km_candidato_total"]
               else "O ESTUDO CONCORRENTE")
        _dif = abs(_app["km_candidato_total"] - _ref["km_candidato_total"])
        _resp.append({"Pergunta": "Qual estudo reduz mais o DESLOCAMENTO total?",
                      "Resposta": f"{_q1} — diferença de {_dif:,.0f} km-candidato.".replace(",", "."),
                      "Base": "Soma de (distância × candidatos) nos municípios comparáveis."})
        if _app.get("tempo_medio_min") and _ref.get("tempo_medio_min"):
            _q2 = ("A NOSSA aplicação" if _app["tempo_medio_min"] < _ref["tempo_medio_min"]
                   else "O ESTUDO CONCORRENTE")
            _resp.append({"Pergunta": "Qual estudo reduz mais o TEMPO médio?",
                          "Resposta": f"{_q2} ({_app['tempo_medio_min']:.0f} min × "
                                      f"{_ref['tempo_medio_min']:.0f} min).",
                          "Base": "Média dos tempos informados por cada estudo."})
        else:
            _resp.append({"Pergunta": "Qual estudo reduz mais o TEMPO médio?",
                          "Resposta": "❓ **NÃO DÁ PARA RESPONDER** — a planilha do concorrente não trouxe "
                                      "tempo. Não vou inventar um número.",
                          "Base": "Coluna de tempo ausente na referência."})
        if _app.get("pct_com_balsa") is not None and _ref.get("pct_com_balsa") is not None:
            _q3 = ("A NOSSA aplicação" if _app["pct_com_balsa"] < _ref["pct_com_balsa"]
                   else "O ESTUDO CONCORRENTE")
            _resp.append({"Pergunta": "Qual estudo EVITA MAIS BALSAS?",
                          "Resposta": f"{_q3} ({_app['pct_com_balsa']}% × {_ref['pct_com_balsa']}% das rotas).",
                          "Base": "Percentual de rotas com travessia."})
        else:
            _resp.append({"Pergunta": "Qual estudo EVITA MAIS BALSAS?",
                          "Resposta": "❓ **NÃO DÁ PARA RESPONDER** — a planilha do concorrente não informa "
                                      "uso de balsa. **Zero e 'não sei' são coisas diferentes**, e eu não vou "
                                      "confundi-las.",
                          "Base": "Coluna de balsa ausente na referência."})
        if _app.get("sinuosidade_media") is not None and _ref.get("sinuosidade_media") is not None:
            _q4 = ("A NOSSA aplicação" if _app["sinuosidade_media"] < _ref["sinuosidade_media"]
                   else "O ESTUDO CONCORRENTE")
            _resp.append({"Pergunta": "Qual estudo tem a MENOR SINUOSIDADE média?",
                          "Resposta": f"{_q4} ({_app['sinuosidade_media']} × {_ref['sinuosidade_media']}).",
                          "Base": "Razão média entre rota viária e linha reta."})
        else:
            _resp.append({"Pergunta": "Qual estudo tem a MENOR SINUOSIDADE média?",
                          "Resposta": "❓ **NÃO DÁ PARA RESPONDER** — a referência não traz sinuosidade.",
                          "Base": "Coluna ausente na referência."})
        _q5 = ("A NOSSA aplicação" if _app["locais_de_prova"] <= _ref["locais_de_prova"]
               else "O ESTUDO CONCORRENTE")
        _resp.append({"Pergunta": "Qual estudo usa MENOS locais de prova (menor custo operacional)?",
                      "Resposta": f"{_q5} ({_app['locais_de_prova']} × {_ref['locais_de_prova']} polos).",
                      "Base": "Contagem de polos distintos utilizados."})

    return {
        "perfil_app": _app, "perfil_ref": _ref,
        "placar": {"aplicacao": len(_v_app), "concorrente": len(_v_ref), "empates": len(_emp),
                   "total": len(_ok),
                   "pct_aplicacao": round(100.0 * len(_v_app) / len(_ok), 1),
                   "pct_concorrente": round(100.0 * len(_v_ref) / len(_ok), 1),
                   "pct_empate": round(100.0 * len(_emp) / len(_ok), 1)},
        "consistencia": _consist, "geografia": _geo, "perguntas": _resp,
    }


def _analise_concorrente(linhas, top=15):
    """[CONCORRENTE - 165ª geração] ANÁLISE DO CONCORRENTE, EM SI MESMO.

    ── O VIÉS QUE ISTO CORRIGE (e era estrutural) ──
    Toda a minha análise era ASSIMÉTRICA: perguntava só "NÓS ganhamos?". As vitórias do concorrente
    apareciam apenas como DERROTAS nossas — nunca eram analisadas em si. Ninguém respondia:
    **"e nos casos em que ele ganhou, quantos alunos se beneficiariam se adotássemos a escolha dele?"**

    Isso não é só incompleto — é ENVIESADO A NOSSO FAVOR. Um comparador que só sabe contar as próprias
    vitórias não é uma ferramenta de decisão: é uma peça de marketing. E num estudo que fundamenta decisão
    pública, isso é grave.

    Aqui o concorrente é analisado com o MESMO rigor: onde venceu, quantos candidatos ele beneficiaria,
    quanto deslocamento pouparia, em quais estados, e QUAIS poucos municípios explicam a vantagem dele.
    PURO."""
    _venc = [l for l in (linhas or []) if l.get("Vencedor Distancia") == "Referência"]
    _tot_mun = sum(1 for l in (linhas or []) if l.get("Vencedor Distancia") in
                   ("Aplicação", "Referência", "Empate"))
    if not _venc:
        return {"n_municipios": 0, "candidatos_impactados": 0, "economia_km_candidato": 0.0,
                "pct_municipios": 0.0, "por_uf": [], "top_casos": [], "pareto_n80": 0}

    _cand = int(sum(float(l.get("Inscritos") or 0) for l in _venc))
    # o ganho DELE = o que nós PERDEMOS. Sinal invertido: aqui é a economia QUE ELE PROPORCIONA.
    _econ = round(sum(abs(float(l.get("Economia km x Inscritos") or 0)) for l in _venc), 1)

    _uf = {}
    for l in _venc:
        _u = str(l.get("UF") or "—")
        _a = _uf.setdefault(_u, {"UF": _u, "municipios": 0, "candidatos": 0, "economia_km_candidato": 0.0})
        _a["municipios"] += 1
        _a["candidatos"] += int(float(l.get("Inscritos") or 0))
        _a["economia_km_candidato"] += abs(float(l.get("Economia km x Inscritos") or 0))
    _por_uf = sorted(_uf.values(), key=lambda x: -x["economia_km_candidato"])
    for _a in _por_uf:
        _a["economia_km_candidato"] = round(_a["economia_km_candidato"], 1)
        _a["km_por_candidato"] = (round(_a["economia_km_candidato"] / _a["candidatos"], 2)
                                  if _a["candidatos"] else 0.0)

    _ord = sorted(_venc, key=lambda l: -abs(float(l.get("Economia km x Inscritos") or 0)))
    _top = [{"Município": l.get("Origem"), "UF": l.get("UF", ""),
             "Candidatos": int(float(l.get("Inscritos") or 0)),
             "Nosso polo": l.get("Destino Aplicacao"),
             "Polo do concorrente": l.get("Destino Referencia"),
             "Nossa distância (km)": l.get("Distancia Aplicacao"),
             "Distância dele (km)": l.get("Distancia Referencia"),
             "Km a mais que impomos": round(abs(float(l.get("Diferenca Abs (km)") or 0)), 1),
             "Impacto (km-candidato)": round(abs(float(l.get("Economia km x Inscritos") or 0)), 1),
             "Tipo de Distância": l.get("Tipo de Distancia", ""),
             "Por que ele venceu": (
                 f"O polo dele ({l.get('Destino Referencia')}) deixa o candidato "
                 f"{abs(float(l.get('Diferenca Abs (km)') or 0)):.0f} km mais perto que o nosso "
                 f"({l.get('Destino Aplicacao')})."
                 if l.get("Mesmo Destino") == "Não" else
                 f"Mesmo polo, mas a rota dele é {abs(float(l.get('Diferenca Abs (km)') or 0)):.0f} km "
                 "mais curta — pode ser malha viária diferente, ou método de medição diferente.")}
            for l in _ord[:top]]

    _acum, _n80 = 0.0, 0
    for _i, l in enumerate(_ord, start=1):
        _acum += abs(float(l.get("Economia km x Inscritos") or 0))
        if _acum >= 0.8 * _econ:
            _n80 = _i
            break

    return {"n_municipios": len(_venc), "candidatos_impactados": _cand,
            "economia_km_candidato": _econ,
            "km_por_candidato": round(_econ / _cand, 2) if _cand else 0.0,
            "pct_municipios": round(100.0 * len(_venc) / _tot_mun, 1) if _tot_mun else 0.0,
            "por_uf": _por_uf[:top], "top_casos": _top, "pareto_n80": _n80}


def _plano_hibrido(linhas):
    """[CONCORRENTE - 165ª geração] O PLANO HÍBRIDO — a pergunta que ninguém estava fazendo.

    Todo o comparador respondia "qual estudo é melhor NO CONJUNTO?". Mas essa é a pergunta ERRADA para quem
    vai DECIDIR. A pergunta certa é:

        **"E se eu pegar, de cada município, a MELHOR das duas escolhas?"**

    Ninguém é obrigado a adotar um estudo INTEIRO. O gestor pode tomar o nosso polo onde nós vencemos e o
    polo do concorrente onde ELE vence. O resultado é um plano que **domina os dois** — por construção.

    Isto transforma o comparador de um "quem ganhou?" (placar) num "o que eu FAÇO?" (decisão). E o número
    que sai é acionável: **quanto deslocamento a mais se poupa adotando o melhor dos dois, em vez de
    escolher um lado.** PURO."""
    _ok = [l for l in (linhas or []) if l.get("Diferenca Abs (km)") is not None]
    if not _ok:
        return {}
    _so_nosso = _so_dele = _hibrido = 0.0
    _de_nos = _de_dele = _empate = 0
    _cand_de_dele = 0
    for l in _ok:
        _i = float(l.get("Inscritos") or 0)
        _dn = float(l.get("Distancia Aplicacao") or 0)
        _dd = float(l.get("Distancia Referencia") or 0)
        if _dn <= 0 or _dd <= 0:
            continue
        _so_nosso += _dn * max(_i, 1)
        _so_dele += _dd * max(_i, 1)
        _hibrido += min(_dn, _dd) * max(_i, 1)
        _v = l.get("Vencedor Distancia")
        if _v == "Aplicação":
            _de_nos += 1
        elif _v == "Referência":
            _de_dele += 1
            _cand_de_dele += int(_i)
        else:
            _empate += 1
    _ganho_vs_nosso = round(_so_nosso - _hibrido, 1)
    _ganho_vs_dele = round(_so_dele - _hibrido, 1)
    return {
        "custo_so_nosso_km_candidato": round(_so_nosso, 1),
        "custo_so_dele_km_candidato": round(_so_dele, 1),
        "custo_hibrido_km_candidato": round(_hibrido, 1),
        "ganho_do_hibrido_sobre_nos": _ganho_vs_nosso,
        "ganho_do_hibrido_sobre_ele": _ganho_vs_dele,
        "municipios_do_nosso": _de_nos, "municipios_do_concorrente": _de_dele,
        "municipios_empate": _empate,
        "candidatos_que_migrariam": _cand_de_dele,
        "vale_a_pena": _ganho_vs_nosso > 0,
    }


def _rankings_comparacao(linhas, top=15):
    """[RANKING - 164ª geração] RANKINGS que faltavam: por ESTADO, por LOCAL DE PROVA e as maiores
    DIVERGÊNCIAS. O Pareto (149ª) já rankeava municípios pelo ganho; faltava responder:
      · qual ESTADO mais ganha (e qual mais perde)?
      · qual LOCAL DE PROVA recebe mais candidatos, e com que deslocamento médio?
      · onde as duas soluções mais DISCORDAM (para revisar primeiro)?
    Tudo ponderado por CANDIDATO. PURO."""
    _ok = [l for l in (linhas or []) if l.get("Diferenca Abs (km)") is not None]
    if not _ok:
        return {"estados": [], "polos": [], "divergencias": []}

    _uf = {}
    for l in _ok:
        _u = str(l.get("UF") or "—")
        _a = _uf.setdefault(_u, {"UF": _u, "municipios": 0, "candidatos": 0,
                                 "economia_km_candidato": 0.0, "venceu_app": 0, "venceu_ref": 0})
        _a["municipios"] += 1
        _a["candidatos"] += int(float(l.get("Inscritos") or 0))
        _a["economia_km_candidato"] += float(l.get("Economia km x Inscritos") or 0)
        if l.get("Vencedor Distancia") == "Aplicação":
            _a["venceu_app"] += 1
        elif l.get("Vencedor Distancia") == "Referência":
            _a["venceu_ref"] += 1
    _est = sorted(_uf.values(), key=lambda x: -x["economia_km_candidato"])
    for _a in _est:
        _a["economia_km_candidato"] = round(_a["economia_km_candidato"], 1)
        _a["km_por_candidato"] = round(_a["economia_km_candidato"] / _a["candidatos"], 2) if _a["candidatos"] else 0.0

    _pl = {}
    for l in _ok:
        _p = str(l.get("Destino Aplicacao") or "—")
        _a = _pl.setdefault(_p, {"Local de Prova": _p, "candidatos": 0, "municipios": 0, "_km": 0.0, "_w": 0.0})
        _i = float(l.get("Inscritos") or 0)
        _d = float(l.get("Distancia Aplicacao") or 0)
        _a["candidatos"] += int(_i)
        _a["municipios"] += 1
        if _d > 0:
            _a["_km"] += _d * max(_i, 1)
            _a["_w"] += max(_i, 1)
    _polos = []
    for _a in _pl.values():
        _a["dist_media_km"] = round(_a["_km"] / _a["_w"], 1) if _a["_w"] else 0.0
        _a.pop("_km", None)
        _a.pop("_w", None)
        _polos.append(_a)
    _polos.sort(key=lambda x: -x["candidatos"])

    _div = sorted([l for l in _ok if l.get("Mesmo Destino") == "Não"],
                  key=lambda l: -abs(float(l.get("Economia km x Inscritos") or 0)))
    _divs = [{"Município": l.get("Origem"), "UF": l.get("UF", ""),
              "Candidatos": int(float(l.get("Inscritos") or 0)),
              "Nosso polo": l.get("Destino Aplicacao"), "Polo da referência": l.get("Destino Referencia"),
              "Diferença (km)": l.get("Diferenca Abs (km)"),
              "Impacto (km-candidato)": round(float(l.get("Economia km x Inscritos") or 0), 1)}
             for l in _div[:top]]
    return {"estados": _est[:top], "polos": _polos[:top], "divergencias": _divs}


def _grafico_planos_comparacao(hb):
    """[BI-COMPARADOR - 257ª geração] Gráfico do PLANO HÍBRIDO — barras horizontais comparando o custo total
    de deslocamento (km-candidato) dos três planos: só o nosso, só o do concorrente, e o híbrido (o melhor
    de cada município). O híbrido é ≤ aos outros dois POR CONSTRUÇÃO; a barra verde (a mais curta) torna
    isso visível num relance e transforma três métricas soltas numa decisão óbvia — sem forçar o gestor a
    ler números. Barras HORIZONTAIS de propósito: cada rótulo fica na própria linha, então nunca colidem em
    largura nenhuma. Consome exatamente as chaves que _plano_hibrido() produz. PURO e defensivo: dict
    None/vazio/sem os três custos/valores não-numéricos/todos-zero → None (nada renderiza). Não recalcula
    nada — só desenha o que o painel já computou. Retorna um alt.Chart ou None."""
    if not isinstance(hb, dict):
        return None
    try:
        _n = float(hb.get("custo_so_nosso_km_candidato"))
        _d = float(hb.get("custo_so_dele_km_candidato"))
        _h = float(hb.get("custo_hibrido_km_candidato"))
    except (TypeError, ValueError):
        return None
    if _n <= 0 and _d <= 0 and _h <= 0:
        return None
    _dados = pd.DataFrame([
        {"plano": "Só o nosso estudo", "custo": _n, "cor": "#3B82F6"},
        {"plano": "Só o do concorrente", "custo": _d, "cor": "#F59E0B"},
        {"plano": "🏆 Híbrido (melhor de cada)", "custo": _h, "cor": "#10B981"},
    ])
    _dados["rotulo"] = _dados["custo"].map(lambda v: _fmt_num(v))
    _base = alt.Chart(_dados)
    _barras = _base.mark_bar(cornerRadiusEnd=4).encode(
        x=alt.X("custo:Q", title="Deslocamento total (km-candidato) — menor é melhor",
                axis=alt.Axis(grid=False)),
        y=alt.Y("plano:N", sort="-x", title=None),
        color=alt.Color("cor:N", scale=None, legend=None),
        tooltip=[alt.Tooltip("plano:N", title="Plano"),
                 alt.Tooltip("rotulo:N", title="km-candidato")],
    )
    _txt = _base.mark_text(align="left", dx=4, color="#374151", fontSize=12).encode(
        x=alt.X("custo:Q"), y=alt.Y("plano:N", sort="-x"), text="rotulo:N")
    return (_barras + _txt).properties(height=180, title="Custo de deslocamento por plano")


def _grafico_estados_divergente(estados, max_estados=18):
    """[BI-COMPARADOR - 257ª geração] Gráfico DIVERGENTE por estado — para cada UF, a economia ponderada
    (km × candidatos). Barra VERDE à direita = a NOSSA solução leva o candidato mais perto ali; barra
    VERMELHA à esquerda = a solução de REFERÊNCIA leva mais perto naquele estado. Responde num relance a
    pergunta inerentemente geográfica 'onde cada estudo vence?', que hoje só existia como TABELA de UF ×
    economia. Ordenado por magnitude e limitado aos max_estados de maior |economia| — com até 27 UFs, uma
    tabela vira parede de números e um gráfico com 27 barras vira emaranhado; o recorte por magnitude mostra
    o que é decisão-relevante. Consome exatamente os itens que _rankings_comparacao()['estados'] produz
    (campos UF e economia_km_candidato). PURO e defensivo: lista None/vazia/itens-lixo/sem sinal numérico →
    None. Retorna um alt.Chart ou None."""
    if not isinstance(estados, (list, tuple)) or not estados:
        return None
    _linhas = []
    for _e in estados:
        if not isinstance(_e, dict):
            continue
        try:
            _v = float(_e.get("economia_km_candidato"))
        except (TypeError, ValueError):
            continue
        _uf = str(_e.get("UF") or "—").upper()
        _linhas.append({"UF": _uf, "economia": _v})
    if not _linhas or all(abs(l["economia"]) < 1e-9 for l in _linhas):
        return None
    _linhas = sorted(_linhas, key=lambda x: -abs(x["economia"]))[:max_estados]
    _dados = pd.DataFrame(_linhas)
    _dados["lado"] = _dados["economia"].map(lambda v: "Nós poupamos" if v >= 0 else "Referência mais perto")
    _dados["rotulo"] = _dados["economia"].map(lambda v: _fmt_num(v))
    return alt.Chart(_dados).mark_bar(cornerRadiusEnd=4).encode(
        x=alt.X("economia:Q", title="Economia ponderada (km-candidato) — ◀ referência · nós ▶",
                axis=alt.Axis(grid=False)),
        y=alt.Y("UF:N", sort=alt.EncodingSortField(field="economia", order="descending"), title=None),
        color=alt.Color("lado:N",
                        scale=alt.Scale(domain=["Nós poupamos", "Referência mais perto"],
                                        range=["#10B981", "#EF4444"]),
                        legend=alt.Legend(title=None, orient="top")),
        tooltip=[alt.Tooltip("UF:N", title="Estado"),
                 alt.Tooltip("rotulo:N", title="km-candidato"),
                 alt.Tooltip("lado:N", title="Quem leva mais perto")],
    ).properties(height=max(180, 22 * len(_dados)), title="Onde cada estudo vence (por estado)")


def _grafico_distribuicao_distancias(df):
    """[BI-LOTE - 258ª geração] Histograma da distribuição das distâncias viárias do lote — mostra num relance
    a FORMA do deslocamento: onde está a massa das rotas (curtas? médias?) e se há cauda longa de casos
    extremos. Complementa o Resumo Executivo (que dá média/total) revelando o que a média esconde. Usa a
    coluna 'Distancia' já pronta no df processado. PURO e defensivo: df None/sem coluna/menos de 3 valores
    positivos válidos → None (nada renderiza). Retorna alt.Chart ou None."""
    try:
        if df is None or 'Distancia' not in df.columns:
            return None
        _d = pd.to_numeric(df['Distancia'], errors='coerce').dropna()
        _d = _d[_d > 0]
        if len(_d) < 3:
            return None
        _dados = pd.DataFrame({"km": _d.values})
        return alt.Chart(_dados).mark_bar(color="#3B82F6", cornerRadiusEnd=2).encode(
            x=alt.X("km:Q", bin=alt.Bin(maxbins=30), title="Distância viária (km)"),
            y=alt.Y("count():Q", title="Nº de rotas"),
            tooltip=[alt.Tooltip("count():Q", title="Rotas"),
                     alt.Tooltip("km:Q", bin=alt.Bin(maxbins=30), title="Faixa (km)")],
        ).properties(height=240, title="Como as distâncias se distribuem no lote")
    except Exception:
        return None


def _grafico_fontes_rota(df):
    """[BI-LOTE - 258ª geração] Barras horizontais de PROCEDÊNCIA de cada rota — de qual motor veio a distância
    (Google/OSRM/GraphHopper = MEDIDA, verde) versus estimativa geodésica (fallback, âmbar). Responde a
    pergunta de CONFIANÇA que pertence ao lado dos resultados: 'quanto deste lote é rota real medida e quanto
    é estimativa por ausência de rota?'. Usa a coluna 'Fonte da Rota' já pronta. Cor por classe (medida ×
    estimada) para a leitura de qualidade ser imediata. PURO e defensivo: df None/sem coluna/tudo vazio →
    None. Retorna alt.Chart ou None."""
    try:
        if df is None or 'Fonte da Rota' not in df.columns:
            return None
        _s = df['Fonte da Rota'].astype(str).str.strip()
        _s = _s[(_s != "") & (_s.str.lower() != "nan")]
        if len(_s) == 0:
            return None
        _cont = _s.value_counts().reset_index()
        _cont.columns = ["fonte", "rotas"]
        if _cont.empty:
            return None

        def _cor(f):
            _fl = f.lower()
            if "estima" in _fl or "geodés" in _fl or "geodes" in _fl or "reta" in _fl:
                return "#F59E0B"
            return "#10B981"
        _cont["cor"] = _cont["fonte"].map(_cor)
        _cont["rotulo"] = _cont["rotas"].map(lambda v: _fmt_num(v))
        _base = alt.Chart(_cont)
        _barras = _base.mark_bar(cornerRadiusEnd=4).encode(
            x=alt.X("rotas:Q", title="Nº de rotas", axis=alt.Axis(grid=False)),
            y=alt.Y("fonte:N", sort="-x", title=None),
            color=alt.Color("cor:N", scale=None, legend=None),
            tooltip=[alt.Tooltip("fonte:N", title="Motor"), alt.Tooltip("rotas:Q", title="Rotas")],
        )
        _txt = _base.mark_text(align="left", dx=4, color="#374151", fontSize=12).encode(
            x=alt.X("rotas:Q"), y=alt.Y("fonte:N", sort="-x"), text="rotulo:N")
        return (_barras + _txt).properties(height=max(140, 30 * len(_cont)),
                                           title="De onde veio cada rota (medida × estimada)")
    except Exception:
        return None


def _metodologia_indicadores():
    """[CMP-VALID - 149ª geração] METODOLOGIA EXPLÍCITA — anti-caixa-preta. Cada indicador declara COMO é
    calculado, de QUAIS colunas, e QUAIS registros participam. Requisito de auditoria governamental: um
    número que ninguém sabe explicar não pode fundamentar decisão pública. PURO."""
    return [
        {"Indicador": "Economia ponderada (km-candidato)",
         "Fórmula": "Σ [(distância_referência − distância_aplicação) × inscritos]",
         "Colunas usadas": "distância da referência; 'Distancia' da aplicação; inscritos",
         "Registros": "somente os CONCILIADOS com distância válida nas DUAS bases",
         "Interpretação": "É o indicador de impacto real: pondera o ganho pelo nº de candidatos. Positivo = a aplicação leva o candidato mais perto."},
        {"Indicador": "Empate técnico",
         "Fórmula": "|diferença| < 1 km",
         "Colunas usadas": "as duas distâncias",
         "Registros": "todos os comparáveis",
         "Interpretação": "Abaixo de 1 km a diferença está dentro do ruído de geocodificação. NÃO se declara vitória com base em ruído."},
        {"Indicador": "Método de Conciliação",
         "Fórmula": "hierarquia: Código IBGE → Município+UF → Município → Similaridade (rapidfuzz ≥ 90)",
         "Colunas usadas": "código IBGE, município, UF da referência",
         "Registros": "todos; o que não concilia vai para a auditoria COM O MOTIVO",
         "Interpretação": "'Similaridade' NÃO é vínculo oficial — confira essas linhas."},
        {"Indicador": "Convergência de destino",
         "Fórmula": "municípios com mesmo local de prova ÷ total de conciliados × 100",
         "Colunas usadas": "destino da referência; 'Municipio Destino' da aplicação",
         "Registros": "conciliados com destino nas duas bases",
         "Interpretação": "% em que as duas soluções concordam sobre ONDE aplicar a prova."},
        {"Indicador": "Mediana e Quartis da diferença",
         "Fórmula": "percentis 25/50/75 da (distância_ref − distância_app)",
         "Colunas usadas": "as duas distâncias",
         "Registros": "comparáveis",
         "Interpretação": "A MÉDIA engana quando poucos municípios têm ganho enorme. A mediana conta o caso TÍPICO."},
        {"Indicador": "Coeficiente de variação (CV)",
         "Fórmula": "desvio-padrão ÷ |média|",
         "Colunas usadas": "diferença de distância",
         "Registros": "comparáveis",
         "Interpretação": "CV baixo = ganho HOMOGÊNEO (melhora em quase todo lugar). CV alto = ganho CONCENTRADO (melhora muito em poucos). Conclusões OPOSTAS a partir da mesma média."},
        {"Indicador": "Pareto (n para 80%)",
         "Fórmula": "quantos municípios, ordenados por economia, somam 80% do ganho total",
         "Colunas usadas": "economia ponderada por município",
         "Registros": "municípios com ganho positivo",
         "Interpretação": "Se poucos municípios concentram o ganho, a melhoria é PONTUAL — foque neles. Se está espalhado, é ESTRUTURAL."},
    ]




_SENTINELAS_FALHA = {"erro", "erro crítico de processamento", "n/a", "na", "não identificado",
                     "nao identificado", "falha", "falha de geocodificação", "", "none", "nan"}


def _linha_app_valida(row):
    """[ANTI-FALHA - 161ª geração] O ESTUDO DA APLICAÇÃO produziu um resultado VÁLIDO para esta linha?

    ── O BUG QUE ISTO CORRIGE (e é o pior tipo que existe) ──
    Quando a rota falha (ex.: município do Marajó, sem estrada até uma ilha), a aplicação grava um FALLBACK:
        Distancia = 0.0 · Municipio Origem = "Erro" · Municipio Destino = "Erro" · Status da Rota = "Erro"
    O Comparador (que EU escrevi na 138ª) testava `_dr > 0` na REFERÊNCIA — mas **NUNCA testava `_da > 0`
    na APLICAÇÃO**. Consequência aritmética:
        diferença = 250 km (referência) − 0 km (falha) = **250 km de "economia"**
        ⇒ Vencedor: APLICAÇÃO. ⇒ Economia: 250 km × inscritos.
    **UMA FALHA DE ROTEAMENTO VIRAVA A MAIOR VITÓRIA POSSÍVEL.**

    Este bug não quebra nada. Ele **MENTE, EM SILÊNCIO, A FAVOR DE QUEM O ESCREVEU** — e o relatório
    executivo leva essa mentira à gestão. É a falha mais perigosa que um comparador pode ter: ela não
    produz um erro, produz uma CONCLUSÃO FALSA que parece boa.

    A app SEMPRE SOUBE quais linhas falharam (grava 'Status da Rota' = "Erro"). O Comparador é que ignorava
    o sinal. Aqui ele passa a ser respeitado. PURO. Retorna (valida: bool, motivo: str)."""
    def _txt(k):
        return str(row.get(k, "") or "").strip().lower()

    if _txt("Status da Rota").startswith("erro"):
        return False, "O estudo da aplicação registrou **ERRO** ao processar esta rota."
    for _c, _lbl in (("Municipio Origem", "município de origem"),
                     ("Municipio Destino", "local de aplicação")):
        if _txt(_c) in _SENTINELAS_FALHA:
            return False, (f"O estudo da aplicação **não identificou o {_lbl}** "
                           f"(gravou `{row.get(_c)}`).")
    try:
        _d = float(row.get("Distancia"))
    except (TypeError, ValueError):
        return False, "O estudo da aplicação não produziu uma **distância numérica** para esta rota."
    if _d <= 0:
        return False, ("O estudo da aplicação devolveu **distância ZERO** — nem a rota nem a geodésica "
                       "puderam ser calculadas (coordenadas ausentes). **Não é comparável**: comparar "
                       "contra zero faria a aplicação 'vencer' pela distância inteira.")
    return True, ""


def _tipo_de_distancia(row):
    """[GEO-GARANTIDO - 162ª geração] A distância desta linha é VIÁRIA ou GEODÉSICA?

    Municípios SEM ACESSO RODOVIÁRIO (ilhas do Marajó, calha do Solimões) não têm distância viária — ela
    NÃO EXISTE. A partir da 162ª eles recebem a GEODÉSICA DE KARNEY (exata, oficial), e não mais zero.
    Mas o usuário PRECISA SABER disso: comparar uma geodésica contra uma viária é comparar maçã com laranja.

    Este rótulo torna a diferença VISÍVEL na planilha e nos painéis — nunca escondida. PURO."""
    _f = str(row.get("Fonte Rota") or row.get("fonte_rota") or "").lower()
    _m = str(row.get("Modo/Acesso") or "").lower()
    if "karney" in _f or "geodés" in _f or "geodes" in _f or "sem acesso rodoviário" in _f:
        return "📐 Geodésica (sem acesso rodoviário)"
    if "fluvial" in _m or "hidro" in _m or "aquavi" in _m:
        return "🚢 Fluvial/Aquaviário"
    return "🛣️ Viária"


def _diagnostico_estudo_app(df_app):
    """[ANTI-FALHA - 161ª geração] AUDITORIA GLOBAL DO ESTUDO ANTES DE COMPARAR: quantas linhas do SEU
    PRÓPRIO estudo falharam? Se muitas, o comparativo inteiro fica comprometido — e o usuário precisa saber
    disso ANTES de ler qualquer percentual, não depois. PURO."""
    _ok, _falhas = 0, []
    for _r in (df_app.to_dict("records") if df_app is not None else []):
        _v, _m = _linha_app_valida(_r)
        if _v:
            _ok += 1
        else:
            _falhas.append({"municipio": _r.get("Municipio Origem") or _r.get("Origem"),
                            "uf": _r.get("UF Origem", ""),
                            "cod_ibge": _r.get("Cod IBGE Origem", ""),
                            "motivo": _m})
    _tot = _ok + len(_falhas)
    return {"total": _tot, "validas": _ok, "falhas": _falhas,
            "n_falhas": len(_falhas),
            "pct_falhas": round(100.0 * len(_falhas) / _tot, 1) if _tot else 0.0}




def _conciliar_multiplos(df_app, estudos):
    """[N-ESTUDOS - 184ª geração] CONCILIAÇÃO GENÉRICA DE N ESTUDOS.

    ── A GENERALIZAÇÃO CERTA (e ela não é óbvia) ──
    A tentação é fazer "N estudos, todos iguais". **Errado para este domínio.** A nossa aplicação **sempre
    existe** — ela é quem PRODUZ o estudo. Os outros são REFERÊNCIAS externas (o estudo de 2025, o cenário
    base, a simulação do fornecedor). Então a estrutura certa é:

        **1 estudo da APLICAÇÃO  +  N estudos de REFERÊNCIA**

    Isso preserva TUDO que já existe (todas as análises são app-cêntricas) e generaliza de graça: com N=1
    referência, é exatamente o comparador de hoje. **Uma generalização que quebra o caso antigo é uma
    regressão com nome bonito.**

    ── ESTRUTURA DE SAÍDA (uma linha por município, N colunas por estudo) ──
        {"Origem": ..., "UF": ..., "Inscritos": ..., "Cod IBGE Origem": ...,
         "estudos": {"Nossa aplicação": {...}, "Estudo 2025": {...}, "Cenário Base": {...}}}

    `estudos` é uma lista de dicts: [{"nome": str, "df": DataFrame, "mapa": dict}, ...]
    Retorna (linhas, auditoria_por_estudo). PURO."""
    if df_app is None or len(df_app) == 0 or not estudos:
        return [], {}

    _app_rows = df_app.to_dict("records")
    # índice do estudo da aplicação: por código IBGE e por (município, uf)
    _idx_cod, _idx_mun = {}, {}
    for _i, _r in enumerate(_app_rows):
        _c = str(_r.get("Cod IBGE Origem") or "").strip()
        if _c:
            _idx_cod[_c] = _i
        _m = semantica.normalizar(str(_r.get("Municipio Origem") or _r.get("Origem") or ""))
        _u = str(_r.get("UF Origem") or "").strip().upper()
        if _m:
            _idx_mun[(_m, _u)] = _i
            _idx_mun.setdefault((_m, ""), _i)

    # a base: uma linha por município do NOSSO estudo
    _linhas = []
    for _i, _a in enumerate(_app_rows):
        _val, _mot = _linha_app_valida(_a)
        _linhas.append({
            "_i": _i,
            "Origem": _a.get("Municipio Origem") or _a.get("Origem"),
            "UF": _a.get("UF Origem", ""),
            "Cod IBGE Origem": str(_a.get("Cod IBGE Origem") or ""),
            "Inscritos": float(_a.get("Inscritos") or 0),
            "estudos": {},
            "_app_valida": _val, "_app_motivo": _mot,
        })

    # o NOSSO estudo entra como o primeiro
    for _i, _a in enumerate(_app_rows):
        if not _linhas[_i]["_app_valida"]:
            continue
        try:
            _d = float(_a.get("Distancia"))
        except (TypeError, ValueError):
            continue
        _linhas[_i]["estudos"]["🏢 Nossa aplicação"] = {
            "destino": _a.get("Municipio Destino") or _a.get("Destino"),
            "distancia": _d,
            "tempo_min": _parse_tempo_min(_a.get("Tempo")) if _a.get("Tempo") else None,
            "balsa": str(_a.get("Balsas", "")).strip().lower() in ("sim", "yes", "true", "1"),
            "tipo": _tipo_de_distancia(_a),
            "metodo": "—", "score": 100,
        }

    # cada estudo de REFERÊNCIA
    _aud = {}
    for _e in estudos:
        _nome = str(_e.get("nome") or "Estudo").strip()[:40]
        _df = _e.get("df")
        _mapa = _e.get("mapa") or {}
        if _df is None or len(_df) == 0:
            continue
        _a_e = {"nome": _nome, "total": len(_df), "conciliados": 0, "por_ibge": 0,
                "por_mun_uf": 0, "por_mun": 0, "nao_conciliados": []}

        def _v(_r, _k):
            _c = _mapa.get(_k)
            return _r.get(_c) if _c else None

        for _r in _df.to_dict("records"):
            _cod = _e_codigo_ibge(str(_v(_r, "ibge_origem") or ""))
            _i_app = None
            _met, _sc = "", 0
            if _cod and _cod in _idx_cod:
                _i_app, _met, _sc = _idx_cod[_cod], "Código IBGE", 100
                _a_e["por_ibge"] += 1
            if _i_app is None:
                _m = semantica.normalizar(str(_v(_r, "origem") or ""))
                _u = str(_v(_r, "uf_origem") or "").strip().upper()
                if (_m, _u) in _idx_mun:
                    _i_app, _met, _sc = _idx_mun[(_m, _u)], "Município + UF", 98
                    _a_e["por_mun_uf"] += 1
                elif (_m, "") in _idx_mun:
                    _i_app, _met, _sc = _idx_mun[(_m, "")], "Município", 90
                    _a_e["por_mun"] += 1
            if _i_app is None:
                _a_e["nao_conciliados"].append({
                    "estudo": _nome, "origem": _v(_r, "origem"), "uf": _v(_r, "uf_origem"),
                    "motivo": "Não casou com nenhum município do estudo da aplicação."})
                continue
            try:
                _dist = float(_v(_r, "distancia"))
            except (TypeError, ValueError):
                _dist = None
            if _dist is None or _dist <= 0:
                continue
            _a_e["conciliados"] += 1
            _linhas[_i_app]["estudos"][_nome] = {
                "destino": _v(_r, "destino"),
                "distancia": _dist,
                "tempo_min": (_parse_tempo_min(_v(_r, "tempo"))
                              if _mapa.get("tempo") and _v(_r, "tempo") else None),
                "balsa": None,          # a referência não informa: NÃO INVENTAMOS
                "tipo": "🛣️ Viária (informado)",
                "metodo": _met, "score": _sc,
            }
            # os inscritos: se a referência trouxer e a app não tiver, aproveita
            if not _linhas[_i_app]["Inscritos"] and _mapa.get("inscritos"):
                try:
                    _linhas[_i_app]["Inscritos"] = float(_v(_r, "inscritos") or 0)
                except (TypeError, ValueError):
                    pass
        _aud[_nome] = _a_e

    # só as linhas com pelo menos 2 estudos são COMPARÁVEIS
    _comp = [l for l in _linhas if len(l["estudos"]) >= 2]
    return _comp, _aud


def _comparar_n_estudos(linhas, nomes=None):
    """[N-ESTUDOS - 184ª geração] A ANÁLISE QUE **SÓ EXISTE COM N**.

    ── AS PERGUNTAS NOVAS (e elas mudam a decisão) ──
    Com dois estudos você pergunta "quem ganhou?". Com N, aparecem perguntas melhores:

      🎯 **Onde TODOS concordam** → confiança alta. **Não precisa revisar.** É onde você economiza tempo.
      ⚡ **Onde TODOS divergem** → é **ali** que a decisão é difícil, e é **ali** que o humano precisa
         olhar. Um município em que 4 estudos escolheram 4 polos diferentes está te dizendo algo:
         **não há resposta óbvia, e o modelo sozinho não vai encontrá-la.**
      🏆 **O híbrido de N** → o melhor de CADA município entre TODOS os estudos. Domina todos, por
         construção. Com N estudos, o ganho do híbrido cresce — porque há mais alternativas para escolher.

    ── E O CONSENSO É UM SINAL DE QUALIDADE ──
    Se 4 metodologias INDEPENDENTES chegam ao mesmo polo, esse polo é provavelmente certo. Se elas se
    espalham, é sinal de que o problema ali é genuinamente ambíguo (empate de distâncias, malha viária
    complicada) — e nenhum estudo isolado "está certo". **O consenso mede a DIFICULDADE do problema, não
    só a concordância dos métodos.** PURO."""
    if not linhas:
        return {}
    _nomes = nomes or sorted({n for l in linhas for n in l["estudos"]})
    _tot_c = int(sum(l.get("Inscritos") or 0 for l in linhas))

    _placar = {n: {"municipios": 0, "candidatos": 0} for n in _nomes}
    _km_por_estudo = {n: 0.0 for n in _nomes}
    _km_hibrido = 0.0
    _consenso_total, _divergencia_total = [], []
    _detalhe = []

    for l in linhas:
        _e = l["estudos"]
        _ins = float(l.get("Inscritos") or 0)
        _w = max(_ins, 1.0)
        _validos = {n: v for n, v in _e.items() if v.get("distancia") and v["distancia"] > 0}
        if len(_validos) < 2:
            continue
        for _n, _v in _validos.items():
            _km_por_estudo[_n] += _v["distancia"] * _w

        _melhor_n = min(_validos, key=lambda n: _validos[n]["distancia"])
        _melhor_d = _validos[_melhor_n]["distancia"]
        _km_hibrido += _melhor_d * _w

        # EMPATE TÉCNICO: diferença < 1 km é ruído de geocodificação (a regra da 138ª)
        _ordenados = sorted(_validos.items(), key=lambda kv: kv[1]["distancia"])
        _empate = (len(_ordenados) > 1
                   and _ordenados[1][1]["distancia"] - _ordenados[0][1]["distancia"] < 1.0)
        if not _empate:
            _placar[_melhor_n]["municipios"] += 1
            _placar[_melhor_n]["candidatos"] += int(_ins)

        # CONSENSO: todos escolheram o MESMO polo?
        _polos = {str(v.get("destino") or "").strip().upper() for v in _validos.values()}
        _polos.discard("")
        _n_polos = len(_polos)
        if _n_polos == 1:
            _consenso_total.append(l)
        elif _n_polos == len(_validos):
            _divergencia_total.append(l)

        _pior_d = max(v["distancia"] for v in _validos.values())
        _detalhe.append({
            "Município": l.get("Origem"), "UF": l.get("UF", ""),
            "Candidatos": int(_ins),
            "Estudos comparados": len(_validos),
            "Polos distintos escolhidos": _n_polos,
            "🏆 Melhor estudo": _melhor_n if not _empate else "Empate técnico",
            "Melhor distância (km)": round(_melhor_d, 1),
            "Pior distância (km)": round(_pior_d, 1),
            "Amplitude (km)": round(_pior_d - _melhor_d, 1),
            "Impacto da escolha (km-cand)": round((_pior_d - _melhor_d) * _ins, 1),
            "Consenso": ("🎯 TOTAL" if _n_polos == 1 else
                         ("⚡ DIVERGÊNCIA TOTAL" if _n_polos == len(_validos) else "🟡 Parcial")),
            **{f"{n} (km)": round(_validos[n]["distancia"], 1) if n in _validos else None
               for n in _nomes},
            **{f"{n} → polo": (_validos[n].get("destino") if n in _validos else None)
               for n in _nomes},
        })

    _n_comp = len(_detalhe)
    for _n in _nomes:
        _placar[_n]["pct_municipios"] = (round(100.0 * _placar[_n]["municipios"] / _n_comp, 1)
                                         if _n_comp else 0.0)
        _placar[_n]["pct_candidatos"] = (round(100.0 * _placar[_n]["candidatos"] / _tot_c, 1)
                                         if _tot_c else 0.0)
        _km_por_estudo[_n] = round(_km_por_estudo[_n], 1)

    _melhor_geral = min(_km_por_estudo, key=lambda n: _km_por_estudo[n]) if _km_por_estudo else None
    _ganho_hib = (round(_km_por_estudo[_melhor_geral] - _km_hibrido, 1)
                  if _melhor_geral else 0.0)

    _divergencia_total.sort(key=lambda l: -float(l.get("Inscritos") or 0))
    return {
        "estudos": _nomes, "n_estudos": len(_nomes), "municipios_comparaveis": _n_comp,
        "candidatos": _tot_c,
        "placar": _placar,
        "km_candidato_por_estudo": _km_por_estudo,
        "km_candidato_hibrido": round(_km_hibrido, 1),
        "melhor_estudo_geral": _melhor_geral,
        "ganho_do_hibrido": _ganho_hib,
        "consenso_total": len(_consenso_total),
        "pct_consenso": round(100.0 * len(_consenso_total) / _n_comp, 1) if _n_comp else 0.0,
        "divergencia_total": len(_divergencia_total),
        "pct_divergencia": round(100.0 * len(_divergencia_total) / _n_comp, 1) if _n_comp else 0.0,
        "municipios_divergentes": [
            {"Município": l.get("Origem"), "UF": l.get("UF", ""),
             "Candidatos": int(l.get("Inscritos") or 0),
             **{n: (l["estudos"][n].get("destino") if n in l["estudos"] else "—") for n in _nomes}}
            for l in _divergencia_total[:60]],
        "detalhe": _detalhe,
    }


def _matriz_similaridade(linhas, nomes=None):
    """[N-ESTUDOS - 184ª geração] MATRIZ DE SIMILARIDADE — quais estudos "pensam parecido"?

    Para cada PAR de estudos: em que % dos municípios eles escolheram o MESMO polo?

    ── POR QUE ISTO IMPORTA (e não é enfeite) ──
    Se dois estudos concordam em 97%, **um deles é redundante** — você está pagando por duas metodologias
    que dizem a mesma coisa. Se concordam em 40%, **eles enxergam o problema de formas fundamentalmente
    diferentes**, e vale entender POR QUÊ antes de escolher um.
    É a diferença entre ter **N opiniões** e ter **N cópias da mesma opinião**. PURO."""
    if not linhas:
        return {}
    _nomes = nomes or sorted({n for l in linhas for n in l["estudos"]})
    _m = []
    for _a in _nomes:
        _linha = {"Estudo": _a}
        for _b in _nomes:
            if _a == _b:
                _linha[_b] = 100.0
                continue
            _comuns = [l for l in linhas if _a in l["estudos"] and _b in l["estudos"]]
            if not _comuns:
                _linha[_b] = None
                continue
            _iguais = sum(
                1 for l in _comuns
                if str(l["estudos"][_a].get("destino") or "").strip().upper()
                == str(l["estudos"][_b].get("destino") or "").strip().upper()
                and str(l["estudos"][_a].get("destino") or "").strip())
            _linha[_b] = round(100.0 * _iguais / len(_comuns), 1)
        _m.append(_linha)

    # o par mais parecido e o mais diferente (que é onde mora a informação)
    _pares = []
    for _i, _a in enumerate(_nomes):
        for _b in _nomes[_i + 1:]:
            _v = next((r[_b] for r in _m if r["Estudo"] == _a), None)
            if _v is not None:
                _pares.append((_a, _b, _v))
    _pares.sort(key=lambda x: -x[2])
    return {
        "matriz": _m, "nomes": _nomes,
        "par_mais_parecido": _pares[0] if _pares else None,
        "par_mais_diferente": _pares[-1] if _pares else None,
        "leitura": _montar_leitura_similaridade(_pares),
    }


def _montar_leitura_similaridade(pares):
    """[N-ESTUDOS - 184ª geração] A leitura da matriz, em português. PURA."""
    if not pares:
        return []
    _out = []
    _a, _b, _v = pares[0]
    if _v >= 95:
        _out.append(
            f"🔁 **{_a}** e **{_b}** concordam em **{_v}%** dos municípios. Nesse nível, **um deles é "
            "praticamente REDUNDANTE** — você está pagando (em tempo e em atenção) por duas metodologias "
            "que dizem a mesma coisa. Considere manter só uma.")
    _a2, _b2, _v2 = pares[-1]
    if _v2 <= 60 and len(pares) > 1:
        _out.append(
            f"⚡ **{_a2}** e **{_b2}** concordam em apenas **{_v2}%**. Eles enxergam o problema de formas "
            "**fundamentalmente diferentes** — e é exatamente aí que está a informação. **Vale entender POR "
            "QUÊ** antes de escolher um: pode ser critério diferente (distância × tempo), base de dados "
            "diferente, ou um deles simplesmente errado.")
    if not _out:
        _out.append(
            "⚖️ Os estudos têm concordância intermediária entre si — nem redundantes, nem radicalmente "
            "divergentes. É o cenário mais comum, e o mais útil: cada um traz alguma informação que os "
            "outros não têm.")
    return _out


def _coluna_parece_sim_nao(df, col):
    """[MAPA-REF - 184ª geração] True se a coluna parece BOOLEANA (SIM/NÃO): ≤3 valores distintos, todos em
    {SIM,NAO,S,N,YES,NO,TRUE,FALSE,0,1,X,''}. Protege o mapeamento do Comparador: 'MUNICIPIO_PROVA' (SIM/NÃO)
    escolhida como DESTINO fazia toda a coluna 'Destino Referencia' virar 'NÃO'. Puro e defensivo."""
    try:
        if df is None or not col or col not in df.columns or len(df) == 0:
            return False
        _v = {unidecode(str(x)).strip().upper() for x in df[col].dropna().unique()}
        _v = {x for x in _v if x != ""}
        _BOOL = {"SIM", "NAO", "S", "N", "YES", "NO", "TRUE", "FALSE", "0", "1", "X"}
        return 0 < len(_v) <= 3 and _v.issubset(_BOOL)
    except Exception:
        return False


def _conciliar_comparativo(df_app, df_ref, mapa, limiar_fuzzy=90, limiar_empate_km=1.0):
    """[COMPARADOR - 138ª geração] Concilia a saída da aba Locais de Aplicação (df_app) com a base externa
    de referência (df_ref), pela ORIGEM (município de candidatos). HIERARQUIA, do mais forte ao mais fraco:
    (1) Código IBGE da origem; (2) município + UF; (3) município sem UF; (4) fuzzy controlado (rapidfuzz
    token_set_ratio >= limiar). NENHUM registro é descartado em silêncio: o que não concilia vai para a
    auditoria com o motivo. PURO; mapa = nomes das colunas do df_ref. Retorna (linhas_conciliadas, auditoria)."""
    _mo = mapa.get("origem")
    _md = mapa.get("destino")
    _mi = mapa.get("ibge_origem")
    _mn = mapa.get("inscritos")
    _mdist = mapa.get("distancia")
    _mtempo = mapa.get("tempo")
    _muf = mapa.get("uf_origem")

    def _v(row, col, padrao=None):
        if not col or col not in row:
            return padrao
        v = row[col]
        return padrao if (v is None or (isinstance(v, float) and v != v)) else v

    # índices do lado da aplicação
    idx_ibge, idx_mun_uf, idx_mun = {}, {}, {}
    app_rows = df_app.to_dict("records")
    for i, r in enumerate(app_rows):
        _cod = str(r.get("Cod IBGE Origem", "") or "").strip()
        if _cod and _cod not in ("—", "N/A", "0", "None", "nan"):
            idx_ibge.setdefault(_cod, i)
        _mun = r.get("Municipio Origem") or r.get("Origem") or ""
        _uf = r.get("UF Origem") or ""
        idx_mun_uf.setdefault(_chave_mun(_mun, _uf), i)
        idx_mun.setdefault(_chave_mun(_mun), i)

    linhas, aud = [], {"conciliados": 0, "por_ibge": 0, "por_mun_uf": 0, "por_mun": 0, "por_fuzzy": 0,
                       "nao_conciliados": [], "nao_comparaveis": [], "total_ref": 0}
    _chaves_mun = list(idx_mun.keys())
    # [CONCILIA-SEGURA - 184ª geração] Conjuntos de apoio dos guardas: códigos (só dígitos) das origens da
    # aplicação, e linhas da app já consumidas (para bloquear duplicata por nome/fuzzy).
    _ibge_digs = {re.sub(r"\D", "", str(_k)) for _k in idx_ibge}
    _consumidos_nome = set()
    for r in df_ref.to_dict("records"):
        aud["total_ref"] += 1
        _o_ref = _v(r, _mo, "")
        if not str(_o_ref).strip():
            aud["nao_conciliados"].append({"origem_ref": "(vazio)", "motivo": "Origem vazia na base de referência."})
            continue
        i_app, metodo, score_m = None, "", 0
        _cod_ref = str(_v(r, _mi, "") or "").strip().split(".")[0]
        if _cod_ref and _cod_ref in idx_ibge:
            i_app, metodo, score_m = idx_ibge[_cod_ref], "Código IBGE", 100
            aud["por_ibge"] += 1
        # [CONCILIA-SEGURA - 184ª geração] Se a referência TEM código IBGE válido e ele NÃO existe entre as
        # origens da aplicação, o município genuinamente não está no estudo — cair para nome/fuzzy aqui casa
        # HOMÔNIMOS e fabrica comparações falsas (provado: "São Geraldo"/MG casado a "São Geraldo do
        # Araguaia"/PA; "Careiro da Várzea" duplicando "Careiro"). Vai para não-conciliados com o motivo.
        _dig_ref = re.sub(r"\D", "", _cod_ref)
        if i_app is None and len(_dig_ref) == 7 and _ibge_digs and _dig_ref not in _ibge_digs:
            aud["bloqueado_codigo_ausente"] = aud.get("bloqueado_codigo_ausente", 0) + 1
            aud["nao_conciliados"].append({"origem_ref": str(_o_ref),
                                           "motivo": f"Código IBGE {_dig_ref} da referência não existe entre as "
                                                     "origens do estudo da aplicação (município fora do estudo; "
                                                     "casamento por nome bloqueado para evitar homônimo)."})
            continue
        _uf_ref = str(_v(r, _muf, "") or "").strip().upper()

        def _uf_compativel(_ix):
            # [CONCILIA-SEGURA] Nome/fuzzy só valem se a UF (quando conhecida dos dois lados) BATER.
            if not _uf_ref:
                return True
            _uf_app = str(app_rows[_ix].get("UF Origem", "") or app_rows[_ix].get("UF", "") or "").strip().upper()
            return (not _uf_app) or (_uf_app == _uf_ref)
        if i_app is None:
            _k = _chave_mun(_o_ref, _v(r, _muf, ""))
            if _k in idx_mun_uf:
                i_app, metodo, score_m = idx_mun_uf[_k], "Município + UF", 98
                aud["por_mun_uf"] += 1
        if i_app is None:
            _k2 = _chave_mun(_o_ref)
            if _k2 in idx_mun and _uf_compativel(idx_mun[_k2]) and idx_mun[_k2] not in _consumidos_nome:
                i_app, metodo, score_m = idx_mun[_k2], "Município (sem UF)", 90
                aud["por_mun"] += 1
        if i_app is None and _chaves_mun:
            # [PERF - 139ª geração] process.extractOne (rapidfuzz, laço em C) no lugar do meu laço Python
            # O(n×m) da 138ª: medido 1,8× mais rápido em escala nacional (500 não-casados × 5.571
            # municípios: 3,04 s → 1,73 s). É a mesma primitiva que o app já usa na geocodificação.
            _k2 = _chave_mun(_o_ref)
            try:
                _m = process.extractOne(_k2, _chaves_mun, scorer=fuzz.token_set_ratio,
                                        score_cutoff=limiar_fuzzy)
            except Exception:
                _m = None
            if _m:
                _ix_fz = idx_mun[_m[0]]
                # [CONCILIA-SEGURA] Fuzzy só com UF compatível e sem reconsumir linha já conciliada
                # (evita homônimo cross-UF e derrota duplicada).
                if not _uf_compativel(_ix_fz):
                    aud["fuzzy_bloqueado_uf"] = aud.get("fuzzy_bloqueado_uf", 0) + 1
                    aud["nao_conciliados"].append({"origem_ref": str(_o_ref),
                                                   "motivo": "Similaridade encontrada, mas em OUTRA UF — casamento "
                                                             "bloqueado para evitar homônimo (ex.: São Geraldo/MG × "
                                                             "São Geraldo do Araguaia/PA)."})
                    continue
                if _ix_fz in _consumidos_nome:
                    aud["fuzzy_bloqueado_duplicata"] = aud.get("fuzzy_bloqueado_duplicata", 0) + 1
                    aud["nao_conciliados"].append({"origem_ref": str(_o_ref),
                                                   "motivo": "Linha da aplicação já conciliada por método mais forte — "
                                                             "novo vínculo por similaridade bloqueado (evita derrota "
                                                             "duplicada por homônimo, ex.: Careiro × Careiro da Várzea)."})
                    continue
                i_app, metodo, score_m = _ix_fz, f"Fuzzy ({int(_m[1])}%)", int(_m[1])
                aud["por_fuzzy"] += 1
        if i_app is None:
            aud["nao_conciliados"].append({"origem_ref": str(_o_ref),
                                           "motivo": "Sem correspondência na saída da aplicação (nem por código IBGE, "
                                                     "nem por município/UF, nem por similaridade acima do limiar)."})
            continue
        a = app_rows[i_app]
        aud["conciliados"] += 1
        _consumidos_nome.add(i_app)
        # [ANTI-FALHA - 161ª geração] O estudo da APLICAÇÃO produziu resultado válido para esta linha?
        # Se a rota falhou (Marajó: sem estrada até a ilha), a app gravou Distancia=0 e Municipio="Erro".
        # Comparar isso contra a referência faria a aplicação "vencer pela distância inteira". É mentira.
        _val_app, _mot_app = _linha_app_valida(a)
        if not _val_app:
            aud.setdefault("nao_comparaveis", []).append({
                "origem_ref": str(_o_ref), "municipio": a.get("Municipio Origem") or a.get("Origem"),
                "uf": a.get("UF Origem", ""), "cod_ibge": a.get("Cod IBGE Origem", ""),
                "metodo_conciliacao": metodo, "motivo": _mot_app})
            continue
        try:
            _dist_ref = float(_v(r, _mdist)) if _v(r, _mdist) is not None else None
        except (TypeError, ValueError):
            _dist_ref = None
        try:
            _insc = float(_v(r, _mn, 0) or 0)
        except (TypeError, ValueError):
            _insc = 0.0
        _t_ref = _v(r, _mtempo)
        linhas.append({
            "Origem": a.get("Municipio Origem") or a.get("Origem"),
            "UF": a.get("UF Origem", ""),
            "Cod IBGE Origem": a.get("Cod IBGE Origem", ""),
            "Inscritos": _insc,
            "Metodo Conciliacao": metodo,
            "Score Conciliacao": score_m,
            "Destino Referencia": str(_v(r, _md, "") or ""),
            "Destino Aplicacao": a.get("Municipio Destino") or a.get("Destino"),
            "Distancia Referencia": _dist_ref,
            "Distancia Aplicacao": a.get("Distancia"),
            "Tempo Referencia": _t_ref,
            "Tempo Aplicacao": a.get("Tempo"),
            "Balsa Aplicacao": a.get("Balsas", ""),
            "Sinuosidade Aplicacao": a.get("Fator Sinuosidade"),
            "Modo Aplicacao": a.get("Modo/Acesso", ""),
            # [GEO-GARANTIDO - 162ª geração] o tipo de distância vai JUNTO, sempre visível.
            "Tipo de Distancia": _tipo_de_distancia(a),
        })
        # [LADO-A-LADO - 164ª geração] NADA DA PLANILHA DO CONCORRENTE É DESCARTADO.
        # A versão anterior guardava SÓ as colunas mapeadas — modo de acesso, balsa, score,
        # justificativa e qualquer outra coluna que a referência trouxesse eram jogadas fora EM
        # SILÊNCIO. Perda de dado do usuário, sem aviso. Agora TODA coluna extra da referência é
        # preservada com o prefixo "REF · ", e todo o nosso estudo entra com o prefixo "APP · ".
        # O usuário vê os DOIS estudos LADO A LADO, campo a campo — e nada se perde no caminho.
        _mapeadas = {c for c in mapa.values() if c}
        for _ck, _cv in r.items():
            if _ck in _mapeadas or _ck is None:
                continue
            if _cv is None or (isinstance(_cv, float) and _cv != _cv):
                _cv = ""
            linhas[-1][f"REF · {_ck}"] = _cv
        # ---- o NOSSO estudo, campo a campo (o que a plataforma produziu) ----
        for _ak, _rot in (("Cod IBGE Destino", "Cód IBGE do Polo"), ("UF Destino", "UF do Polo"),
                          ("Linha Reta", "Linha Reta (km)"), ("Score Final Global", "Score"),
                          ("Fonte Rota", "Fonte da Rota"), ("Integridade Geográfica", "Integridade"),
                          ("Alerta de Integridade", "Alerta de Integridade"),
                          ("Confiança Identificação", "Confiança da Identificação"),
                          ("Risco de Confusão", "Risco de Homônimo"),
                          ("Justificativa Hub", "Justificativa da Escolha"),
                          ("Custo Efetivo Hub (km-eq)", "Custo Efetivo (km-eq)"),
                          ("Lat/Lon Origem", "Coordenadas da Origem"),
                          ("Lat/Lon Destino", "Coordenadas do Polo")):
            if _ak in a and a.get(_ak) not in (None, ""):
                linhas[-1][f"APP · {_rot}"] = a.get(_ak)
    return linhas, aud


def _comparar_alocacoes(linhas, parse_tempo=None, limiar_empate_km=1.0):
    """[COMPARADOR - 138ª geração] Compara, linha a linha, a alocação da APLICAÇÃO contra a da REFERÊNCIA e
    produz as colunas de decisão: mesmo destino?, diferença absoluta e percentual, economia de km, economia
    PONDERADA por inscritos, economia de tempo, vencedor e JUSTIFICATIVA técnica. Convenção: economia
    positiva = a aplicação levou o candidato mais perto. Empate técnico = |Δ| < 1 km (ruído de geocodificação).
    PURO; parse_tempo injetável. Devolve a lista de linhas enriquecida."""
    parse_tempo = parse_tempo or _parse_tempo_min
    out = []
    for l in linhas:
        d = dict(l)
        try:
            _dr = float(d["Distancia Referencia"]) if d["Distancia Referencia"] is not None else None
        except (TypeError, ValueError):
            _dr = None
        try:
            _da = float(d["Distancia Aplicacao"]) if d["Distancia Aplicacao"] is not None else None
        except (TypeError, ValueError):
            _da = None
        _mesmo = (_chave_mun(d.get("Destino Referencia")) == _chave_mun(d.get("Destino Aplicacao"))
                  if (d.get("Destino Referencia") and d.get("Destino Aplicacao")) else None)
        d["Mesmo Destino"] = "Sim" if _mesmo else ("Não" if _mesmo is False else "—")
        _insc = float(d.get("Inscritos") or 0)

        # [ANTI-FALHA - 161ª geração] A BARREIRA QUE FALTAVA. Antes: `if ... and _dr > 0:` — testava a
        # REFERÊNCIA e NUNCA a APLICAÇÃO. Uma distância ZERO (rota falhada) virava economia de 250 km.
        # Agora AMBAS precisam ser positivas. Cinto e suspensório: a conciliação já barra a linha
        # inválida, mas esta função é PÚBLICA e pode receber dado de outra origem — ela se protege sozinha.
        if _dr is not None and _da is not None and _dr > 0 and _da > 0:
            _dif = round(_dr - _da, 2)                    # + = aplicação mais curta
            d["Diferenca Abs (km)"] = _dif
            d["Diferenca Pct (%)"] = round(100.0 * _dif / _dr, 2)
            d["Economia km"] = max(0.0, _dif)
            d["Economia km x Inscritos"] = round(_dif * _insc, 1)
            # [LIMIAR-EMPATE - 184ª geração] Limiar CONFIGURÁVEL: diferenças abaixo dele são ruído de
            # medição entre fontes (matriz pré-computada × roteamento ao vivo; mediana real ~2 km no mesmo
            # destino), não vitória.
            if abs(_dif) < float(limiar_empate_km):
                d["Vencedor Distancia"] = "Empate"
            elif _dif > 0:
                d["Vencedor Distancia"] = "Aplicação"
            else:
                d["Vencedor Distancia"] = "Referência"
        else:
            d["Diferenca Abs (km)"] = None
            d["Diferenca Pct (%)"] = None
            d["Economia km"] = 0.0
            d["Economia km x Inscritos"] = 0.0
            d["Vencedor Distancia"] = "—"

        _tr = parse_tempo(d.get("Tempo Referencia")) if d.get("Tempo Referencia") not in (None, "") else None
        _ta = parse_tempo(d.get("Tempo Aplicacao")) if d.get("Tempo Aplicacao") not in (None, "") else None
        if _tr is not None and _ta is not None:
            _dt = round(_tr - _ta, 1)
            d["Diferenca Tempo (min)"] = _dt
            d["Economia Tempo x Inscritos (min)"] = round(_dt * _insc, 1)
            d["Vencedor Tempo"] = "Empate" if abs(_dt) < 2 else ("Aplicação" if _dt > 0 else "Referência")
        else:
            d["Diferenca Tempo (min)"] = None
            d["Economia Tempo x Inscritos (min)"] = 0.0
            d["Vencedor Tempo"] = "—"

        _just = []
        if d["Vencedor Distancia"] == "Aplicação":
            _just.append(f"deslocamento {abs(d['Diferenca Pct (%)']):.0f}% mais curto "
                         f"({_da:.0f} km vs {_dr:.0f} km)")
        elif d["Vencedor Distancia"] == "Referência":
            _just.append(f"deslocamento {abs(d['Diferenca Pct (%)']):.0f}% mais longo "
                         f"({_da:.0f} km vs {_dr:.0f} km)")
        elif d["Vencedor Distancia"] == "Empate":
            _just.append("distâncias equivalentes (diferença < 1 km)")
        if d["Vencedor Tempo"] in ("Aplicação", "Referência"):
            _just.append(f"tempo {'menor' if d['Vencedor Tempo'] == 'Aplicação' else 'maior'} "
                         f"em {abs(d['Diferenca Tempo (min)']):.0f} min")
        if d["Mesmo Destino"] == "Não":
            _just.append(f"local de prova diferente ({d.get('Destino Aplicacao')} vs {d.get('Destino Referencia')})")
        if str(d.get("Balsa Aplicacao", "")).strip().lower() in ("sim", "yes", "true", "1"):
            _just.append("⚠️ o trajeto da aplicação usa balsa")
        if _insc:
            _just.append(f"impacta {int(_insc)} candidato(s)")
        d["Justificativa"] = "; ".join(_just).capitalize() if _just else "Sem dados suficientes para comparar."
        # [COMPARADOR - 141ª geração] Faixa COM SINAL: 60 km a favor e 60 km contra não são a mesma coisa.
        d["Faixa de Diferenca"] = _faixa_diferenca(d["Diferenca Abs (km)"])
        # [MULTI-CMP - 167ª geração] O VENCEDOR PELO ESFORÇO REAL, não só por quilômetro.
        # A própria plataforma já sabe, desde a 129ª, que a MENOR DISTÂNCIA NÃO É NECESSARIAMENTE A MELHOR
        # SOLUÇÃO. O motor de alocação decide por CUSTO EFETIVO — mas o COMPARADOR ainda usava régua de km.
        # Duas partes da mesma app com critérios diferentes. Agora falam a mesma língua.
        try:
            _vm, _crit, _exp = _vencedor_multicriterio_comparacao(d, limiar_empate_km=limiar_empate_km)
            d["Vencedor (Esforço Real)"] = _vm
            d["Criterio Usado"] = _crit
            d["Explicacao do Criterio"] = _exp
            d["Criterio Inverteu o Resultado"] = (
                "Sim" if (_vm != d["Vencedor Distancia"] and _vm not in ("—", "Empate")
                          and d["Vencedor Distancia"] not in ("—", "Empate")) else "Não")
        except Exception as _e_vm:
            logger.error(f"[MULTI-CMP] Falha no vencedor multicritério: {_e_vm}")
        # [V307 · FATIA 1] Proveniência + validação da regra viária + classe da divergência.
        # ADITIVO e defensivo: só cria chaves NOVAS em d, a partir de dados já presentes;
        # não altera nenhum campo/decisão existente. Se algo falhar, o comparador segue igual.
        try:
            _da_km = d.get("Distancia Aplicacao")
            _dr_km = d.get("Distancia Referencia")
            _balsa_app = d.get("Balsa Aplicacao", "")
            _fonte_app = d.get("Fonte Aplicacao", d.get("Motor Aplicacao", ""))
            _vr_app = d.get("Razao V/R Aplicacao", d.get("VR Aplicacao"))
            _prov_app = _v307_classificar_proveniencia_distancia(
                _da_km, _fonte_app, d.get("Status Aplicacao", ""),
                tem_balsa=_balsa_app, vr=_vr_app, fluvial=False)
            _prov_ref = _v307_classificar_proveniencia_distancia(
                _dr_km, d.get("Fonte Referencia", ""), d.get("Status Referencia", ""),
                fluvial=_v307_sim(d.get("Fluvial Referencia", d.get("Acesso Referencia", ""))))
            d["Proveniência Aplicação"] = _prov_app["rotulo"]
            d["Confiabilidade Distância (App)"] = _prov_app["confiabilidade"]
            # Validação da REGRA "Menor Rota Viária" (§356/§15/§19): o lado declarado
            # vencedor honra a menor viária real? Sinaliza sem trocar nada.
            _venc_lbl = d.get("Vencedor (Esforço Real)", d.get("Vencedor Distancia", "—"))
            if _venc_lbl == "Aplicação":
                _cv = _v307_validar_vencedor_cruzado(_da_km, _dr_km, _prov_app, _prov_ref)
            elif _venc_lbl == "Referência":
                _cv = _v307_validar_vencedor_cruzado(_dr_km, _da_km, _prov_ref, _prov_app)
            else:
                _cv = {"nivel": "ok", "alerta": False,
                       "motivo": "Empate/sem dado — regra viária não aplicável.", "acao": ""}
            d["Validação Regra Viária"] = _cv["nivel"]
            d["Alerta da Decisão"] = _cv["motivo"] if _cv.get("alerta") else ""
            d["Ação Sugerida"] = _cv.get("acao", "")
            # Classe da divergência quando a REFERÊNCIA venceu (aprendizado §12).
            if _venc_lbl == "Referência":
                _nat = str(d.get("Justificativa", "")) + " " + str(d.get("Explicacao do Criterio", ""))
                _cat, _evit, _exp = _v307_classificar_derrota(
                    vr_app=_vr_app, tem_balsa_app=_balsa_app,
                    fluvial_ref=_prov_ref["tipo"] == "fluvial_estimada",
                    natureza=_nat, dif_km=d.get("Diferenca Abs (km)"))
                d["Classe da Divergência"] = _cat
                d["Divergência Evitável"] = "Sim" if _evit else "Não"
                d["Diagnóstico da Divergência"] = _exp
            else:
                d["Classe da Divergência"] = _v307_rotulo_ausencia("na")
                d["Divergência Evitável"] = _v307_rotulo_ausencia("na")
                d["Diagnóstico da Divergência"] = ""
        except Exception as _e_v307:
            logger.error(f"[V307-PROVENIENCIA] Falha na camada de proveniência: {_e_v307}")
        # [V316 · Melhoria 3, fatia 5] Quantificação explícita do trade-off de balsa (app × referência).
        # Complementa o veredito (que já prioriza o lado sem balsa) com a economia em km, exportável.
        try:
            d["Análise de Balsa"] = _v316_comparador_balsa(
                d.get("Distancia Aplicacao"), d.get("Distancia Referencia"),
                d.get("Balsa Aplicação", d.get("Balsa Aplicacao", "")),
                d.get("Balsa Referência", d.get("Balsa Referencia", "")))
        except Exception as _e_v316b:
            logger.error(f"[V316-CMP-BALSA] análise de balsa do comparador: {_e_v316b}")
        out.append(d)
    return out




def _estatisticas_comparacao(linhas, uf_para_regiao=None):
    """[COMPARADOR - 138ª geração] Agrega a comparação em Brasil / Região / UF. Todo indicador de impacto é
    PONDERADO POR INSCRITOS — é o número de candidatos que importa, não o de linhas: 1 município com 5.000
    inscritos pesa mais que 50 municípios com 10. PURO; mapa UF→região injetável."""
    ufr = uf_para_regiao if uf_para_regiao is not None else _UF_PARA_REGIAO

    def _bloco(ls):
        n = len(ls)
        insc = sum(float(l.get("Inscritos") or 0) for l in ls)
        _vd = [l.get("Vencedor Distancia") for l in ls]
        _venc_app = _vd.count("Aplicação")
        _venc_ref = _vd.count("Referência")
        _emp = _vd.count("Empate")
        _comp = _venc_app + _venc_ref + _emp
        _mesmo = sum(1 for l in ls if l.get("Mesmo Destino") == "Sim")
        _difdest = sum(1 for l in ls if l.get("Mesmo Destino") == "Não")
        _insc_mesmo = sum(float(l.get("Inscritos") or 0) for l in ls if l.get("Mesmo Destino") == "Sim")
        _insc_dif = sum(float(l.get("Inscritos") or 0) for l in ls if l.get("Mesmo Destino") == "Não")
        _econ_km = sum(float(l.get("Diferenca Abs (km)") or 0) for l in ls)
        _econ_pond = sum(float(l.get("Economia km x Inscritos") or 0) for l in ls)
        _econ_t = sum(float(l.get("Economia Tempo x Inscritos (min)") or 0) for l in ls)
        _benef = sum(float(l.get("Inscritos") or 0) for l in ls if (l.get("Diferenca Abs (km)") or 0) > 1)
        _prej = sum(float(l.get("Inscritos") or 0) for l in ls if (l.get("Diferenca Abs (km)") or 0) < -1)
        _difs = [float(l["Diferenca Pct (%)"]) for l in ls if l.get("Diferenca Pct (%)") is not None]
        _faixas = {}
        for _f in (5, 10, 20, 50, 100):
            _faixas[f"≥{_f} km"] = sum(float(l.get("Inscritos") or 0) for l in ls
                                       if (l.get("Diferenca Abs (km)") or 0) >= _f)
        return {
            "municipios": n, "inscritos": int(insc), "comparaveis": _comp,
            "venceu_app": _venc_app, "venceu_ref": _venc_ref, "empates": _emp,
            "pct_venceu_app": round(100.0 * _venc_app / _comp, 1) if _comp else 0.0,
            "pct_venceu_ref": round(100.0 * _venc_ref / _comp, 1) if _comp else 0.0,
            "pct_empate": round(100.0 * _emp / _comp, 1) if _comp else 0.0,
            "mesmo_destino": _mesmo, "destino_diferente": _difdest,
            "pct_convergencia": round(100.0 * _mesmo / (_mesmo + _difdest), 1) if (_mesmo + _difdest) else 0.0,
            "inscritos_mesmo_destino": int(_insc_mesmo), "inscritos_destino_diferente": int(_insc_dif),
            "economia_km_total": round(_econ_km, 1),
            "economia_km_media": round(_econ_km / n, 2) if n else 0.0,
            "economia_ponderada_km": round(_econ_pond, 1),
            "economia_km_por_candidato": round(_econ_pond / insc, 2) if insc else 0.0,
            "economia_tempo_ponderada_min": round(_econ_t, 1),
            "candidatos_beneficiados": int(_benef), "candidatos_prejudicados": int(_prej),
            "reducao_pct_media": round(sum(_difs) / len(_difs), 2) if _difs else 0.0,
            "faixas_economia_candidatos": {k: int(v) for k, v in _faixas.items()},
        }

    br = _bloco(linhas)
    por_uf, por_reg = {}, {}
    for l in linhas:
        _uf = str(l.get("UF") or "").upper()
        por_uf.setdefault(_uf or "—", []).append(l)
        por_reg.setdefault(ufr.get(_uf, "Indefinido"), []).append(l)
    return {
        "brasil": br,
        "por_uf": {u: _bloco(ls) for u, ls in sorted(por_uf.items())},
        "por_regiao": {r: _bloco(ls) for r, ls in sorted(por_reg.items())},
    }


def _escrever_mapa_calor(writer, pares_uf_dist, nome_aba="Mapa de Calor UF"):
    """[MAPA-CALOR - 184ª geração] NÚCLEO reutilizável: dado um iterável de (UF, distância_km), escreve uma
    matriz UF × faixa de distância (nº de rotas) com FORMATAÇÃO CONDICIONAL (heatmap branco→vermelho). Serve
    tanto ao Comparador quanto à planilha de Locais. Defensivo; usa xlsxwriter. Retorna nada."""
    try:
        _wb = getattr(writer, "book", None)
        if _wb is None or not hasattr(_wb, "add_format"):
            return
        import pandas as _pd
        _df = _pd.DataFrame([{"UF": str(_u or "—").strip().upper()[:2] or "—",
                              "d": _pd.to_numeric(_d, errors="coerce")} for _u, _d in pares_uf_dist])
        _df = _df[_df["d"].notna()]
        if _df.empty or _df["UF"].nunique() == 0:
            return
        _labs = ["0-50", "50-100", "100-150", "150-200", "200-300", "300-500", "500+"]
        _df["faixa"] = _pd.cut(_df["d"], bins=[0, 50, 100, 150, 200, 300, 500, 10**12],
                               labels=_labs, right=False)
        _mat = _df.groupby(["UF", "faixa"], observed=False).size().unstack("faixa", fill_value=0)
        _mat = _mat.reindex(columns=_labs, fill_value=0)
        _mat["Total"] = _mat.sum(axis=1)
        _mat = _mat.sort_values("Total", ascending=False)
        _ws = _wb.add_worksheet(nome_aba)
        writer.sheets[nome_aba] = _ws
        _hd = _wb.add_format({"bold": True, "bg_color": "#1e3a8a", "font_color": "white",
                              "align": "center", "border": 1})
        _uf_fmt = _wb.add_format({"bold": True, "border": 1})
        _cell = _wb.add_format({"border": 1, "align": "center"})
        _ws.write("A1", "UF \\ Faixa (km)", _hd)
        for _j, _lab in enumerate(_labs + ["Total"]):
            _ws.write(0, _j + 1, _lab, _hd)
        for _i, (_uf, _row) in enumerate(_mat.iterrows()):
            _ws.write(_i + 1, 0, _uf, _uf_fmt)
            for _j, _lab in enumerate(_labs + ["Total"]):
                _ws.write(_i + 1, _j + 1, int(_row[_lab]), _cell)
        _nrows = len(_mat)
        if _nrows > 0:
            _ws.conditional_format(1, 1, _nrows, len(_labs), {
                "type": "3_color_scale", "min_color": "#ffffff", "mid_color": "#fca5a5",
                "max_color": "#b91c1c"})
        _ws.set_column("A:A", 14)
        _ws.set_column(1, len(_labs) + 1, 10)
        _ws.freeze_panes(1, 1)
        _ws.write(_nrows + 3, 0, "Leitura: cada célula é o nº de rotas do estado naquela faixa de distância; "
                  "quanto mais vermelho, mais rotas longas concentradas ali.")
    except Exception:
        logger.error("[MAPA-CALOR] Falha ao montar o mapa de calor UF × faixa (%s)", nome_aba, exc_info=True)


def _aba_mapa_calor_uf(writer, linhas):
    """[MAPA-CALOR - 184ª geração] Mapa de calor do Comparador — delega ao núcleo com (UF, Distancia
    Aplicacao) de cada linha conciliada."""
    if not linhas:
        return
    _escrever_mapa_calor(writer, ((_l.get("UF", ""), _l.get("Distancia Aplicacao")) for _l in linhas))


def _aba_mapa_calor_alocacao(writer, df):
    """[MAPA-CALOR - 184ª geração] Mapa de calor da planilha de Locais — delega ao núcleo com (UF Origem,
    Distancia) do df final. Defensivo: sem as colunas, não faz nada."""
    try:
        if df is None or getattr(df, "empty", True):
            return
        if 'UF Origem' not in df.columns or 'Distancia' not in df.columns:
            return
        _escrever_mapa_calor(writer, zip(df['UF Origem'].tolist(), df['Distancia'].tolist()))
    except Exception:
        logger.error("[MAPA-CALOR] Falha no mapa de calor da alocação", exc_info=True)




# <<< [DIVERGENCIA-XAI 236ª] INÍCIO — bloco inserido (núcleo puro + saídas + orquestrador + painel) >>>
# ==============================================================================
# [DIVERGENCIA-XAI - 236ª geração] MOTOR DE ANÁLISE INTELIGENTE DE DIVERGÊNCIAS
# ------------------------------------------------------------------------------
# Núcleo 100% PURO e testável (sem Streamlit, sem rede). A rede vive só no
# orquestrador _reprocessar_rotas_divergentes (rota origem→destino_ref pelos
# MESMOS motores). Reaproveita o framework multicritério já validado da app
# (_indices_compostos_hub) e os classificadores existentes.
# ==============================================================================

def _num_seguro(v, padrao=None):
    """Converte para float com segurança. PURO."""
    try:
        if v is None or (isinstance(v, float) and v != v):
            return padrao
        return float(v)
    except (TypeError, ValueError):
        return padrao


def _bool_balsa(v):
    """Interpreta o campo balsa em bool. PURO."""
    return str(v or "").strip().lower() in ("sim", "yes", "true", "1", "com balsa")


def _motor_curto(fonte_rota):
    """Nome curto e legível do motor de rota a partir da 'Fonte da Rota'. PURO."""
    _f = str(fonte_rota or "").upper()
    if "GOOGLE" in _f:
        return "Google"
    if "GRAPHHOPPER" in _f:
        return "GraphHopper"
    if "VALHALLA" in _f:
        return "Valhalla"
    if "ORS" in _f or "OPENROUTE" in _f:
        return "ORS"
    if "FOSSGIS" in _f:
        return "OSRM (FOSSGIS)"
    if "OSRM" in _f:
        return "OSRM"
    if "KARNEY" in _f or "GEODÉS" in _f or "GEODES" in _f or "RETA" in _f:
        return "Geodésico"
    return (str(fonte_rota).strip() or "—")


def _parse_coord_par(v):
    """Extrai (lat, lon) de 'lat, lon' ou tupla/lista. Retorna (None, None) se inválido. PURO."""
    if v is None:
        return (None, None)
    if isinstance(v, (list, tuple)) and len(v) >= 2:
        return (_num_seguro(v[0]), _num_seguro(v[1]))
    _s = str(v).replace(";", ",")
    _p = [x.strip() for x in _s.split(",") if x.strip()]
    if len(_p) >= 2:
        return (_num_seguro(_p[0]), _num_seguro(_p[1]))
    return (None, None)


def _fatos_rota_divergencia(campos):
    """[DIVERGENCIA-XAI - 236ª] Normaliza os SINAIS de UMA rota (aplicação OU referência — ambas medidas
    pelos MESMOS motores) num dicionário de FATOS uniforme para a análise de divergência. PURO e testável.

    Espera um dict `campos` com chaves flexíveis (aceita o formato do RotaPipeline convertido e o formato da
    linha de conciliação). Reusa _classificar_modo_acesso e _classificar_razao_vr (helpers já validados).
    """
    _dist = _num_seguro(campos.get("distancia_km"))
    _reta = _num_seguro(campos.get("linha_reta_km"))
    _tem_balsa = _bool_balsa(campos.get("balsa"))
    _fonte = str(campos.get("fonte_rota") or "")
    _lat_o, _lon_o = _parse_coord_par(campos.get("coord_origem"))
    _lat_d, _lon_d = _parse_coord_par(campos.get("coord_destino"))
    if _lat_d is None:
        _lat_d = _num_seguro(campos.get("lat_destino"))
        _lon_d = _num_seguro(campos.get("lon_destino"))
    if _lat_o is None:
        _lat_o = _num_seguro(campos.get("lat_origem"))
        _lon_o = _num_seguro(campos.get("lon_origem"))

    # razão viária/reta (circuity/detour factor)
    _razao = None
    if _dist and _reta and _reta > 0:
        _razao = round(_dist / _reta, 3)
    # fallback: sinuosidade explícita informada (coluna do estudo)
    if _razao is None:
        _razao = _num_seguro(campos.get("razao_vr"))

    _modo = _classificar_modo_acesso(_fonte, "Sim" if _tem_balsa else "Não",
                                     _lat_o, _lon_o, _lat_d, _lon_d)
    # se a linha já traz um modo textual do estudo, respeita quando o derivado for genérico
    _modo_estudo = str(campos.get("modo_acesso") or "").strip()
    if _modo_estudo and _modo == "Rodoviário":
        _mm = _modo_estudo.lower()
        if "fluvial" in _mm or "isolado" in _mm or "balsa" in _mm or "aquav" in _mm:
            _modo = _modo_estudo

    _mlow = (str(_modo) + " " + _modo_estudo).lower()
    _fluvial = ("fluvial" in _mlow) or ("isolado" in _mlow) or ("aquav" in _mlow) or ("hidrov" in _mlow)
    _flu_lista = bool(campos.get("fluvial_lista"))  # município consta na lista IBGE REGIC
    _fluvial = _fluvial or _flu_lista

    _fonte_up = _fonte.upper()
    _geodesica = ("GEOD" in _fonte_up) or ("KARNEY" in _fonte_up) or ("RETA" in _fonte_up)
    _roteada = bool(_dist and not _geodesica)

    _tempo_min = campos.get("tempo_min")
    if _tempo_min is None and campos.get("tempo") is not None:
        _t = parse_tempo_minutos(campos.get("tempo"))
        _tempo_min = None if _t is None or _t >= 999999 else _t
    _tempo_min = _num_seguro(_tempo_min)
    _vel = None
    if _dist and _tempo_min and _tempo_min > 0:
        _vel = round(_dist / (_tempo_min / 60.0), 1)

    _score = _num_seguro(campos.get("score"))
    if _score is None:
        _score = _num_seguro(campos.get("score_num"))

    return {
        "destino": str(campos.get("destino") or "—"),
        "uf_destino": str(campos.get("uf_destino") or ""),
        "cod_ibge_destino": str(campos.get("cod_ibge_destino") or ""),
        "distancia_km": _dist,
        "linha_reta_km": _reta,
        "razao_vr": _razao,
        "razao_vr_classe": _classificar_razao_vr(_razao) if _razao else "—",
        "tem_balsa": _tem_balsa,
        "modo_acesso": _modo,
        "fluvial_isolado": _fluvial,
        "fonte_rota": _fonte,
        "motor": _motor_curto(_fonte),
        "tempo_min": _tempo_min,
        "velocidade_kmh": _vel,
        "score": _score,
        "coord_destino": (_lat_d, _lon_d) if (_lat_d is not None and _lon_d is not None) else None,
        "geodesica": _geodesica,
        "roteada": _roteada,
    }


def _indice_qualidade_escolha(fatos, dif_km_vs_alt=0.0, dif_pct_vs_alt=0.0, divergencia_pct=0.0):
    """[DIVERGENCIA-XAI - 236ª] ÍNDICE DE QUALIDADE DA ESCOLHA (0-100) de UMA solução, reaproveitando o
    framework multicritério JÁ VALIDADO da aplicação (_indices_compostos_hub) e sintetizando um composto.
    `dif_*_vs_alt` = vantagem desta escolha sobre a ALTERNATIVA (a escolha do outro estudo): positivo se esta
    é mais curta. PURO e determinístico. Nada é inventado — todos os sinais já foram medidos.

    Composto = 0.42·Acessibilidade + 0.33·Eficiência + 0.25·Robustez (acessibilidade pesa mais porque, na
    logística de prova, chegar de forma confiável importa mais que o quilômetro isolado — princípio que a
    própria app já adota no motor de alocação por custo efetivo).
    """
    _idx = _indices_compostos_hub(
        fatos.get("razao_vr") or 0.0,
        bool(fatos.get("tem_balsa")),
        fatos.get("modo_acesso") or "",
        fatos.get("score") if fatos.get("score") is not None else 75.0,
        _num_seguro(divergencia_pct, 0.0),
        _num_seguro(dif_km_vs_alt, 0.0),
        _num_seguro(dif_pct_vs_alt, 0.0),
    )
    _acess = _idx["acessibilidade"]
    _efic = _idx["eficiencia"]
    _robu = _idx["robustez"]
    _composto = round(max(0.0, min(100.0, 0.42 * _acess + 0.33 * _efic + 0.25 * _robu)), 1)

    def _lbl(v):
        if v >= 85:
            return "Excelente"
        if v >= 70:
            return "Muito Bom"
        if v >= 55:
            return "Bom"
        if v >= 40:
            return "Regular"
        if v >= 25:
            return "Ruim"
        return "Crítico"

    return {
        "composto": _composto, "composto_lbl": _lbl(_composto),
        "acessibilidade": _acess, "eficiencia": _efic, "robustez": _robu,
        "componentes": _idx.get("componentes", {}),
    }


def _classificar_divergencia(fatos_app, fatos_ref, dif_km, limiar_empate_km=1.0, tol_sinuosidade=0.25):
    """[DIVERGENCIA-XAI - 236ª] Classifica automaticamente a natureza da divergência entre a escolha da
    aplicação e a da referência. PURO. Retorna dict {categoria, subcategorias:[...], vantagem_de, cor}.
    Prioridade das causas (da mais decisiva à menos): empate → balsa → fluvial/isolado → sem-rota →
    sinuosidade → motor → geocodificação → puramente viária, com sobreposição de vantagem operacional.
    """
    _da = fatos_app.get("distancia_km")
    _dr = fatos_ref.get("distancia_km")
    _dif = _num_seguro(dif_km)  # + = aplicação mais curta (dist_ref - dist_app)
    _subs = []

    # quem tem a menor distância bruta
    _vant_dist = "—"
    if _da is not None and _dr is not None:
        if abs(_da - _dr) < float(limiar_empate_km):
            _vant_dist = "Empate"
        elif _da < _dr:
            _vant_dist = "Aplicação"
        else:
            _vant_dist = "Referência"

    _balsa_app, _balsa_ref = bool(fatos_app.get("tem_balsa")), bool(fatos_ref.get("tem_balsa"))
    _flu_app, _flu_ref = bool(fatos_app.get("fluvial_isolado")), bool(fatos_ref.get("fluvial_isolado"))
    _rot_app, _rot_ref = bool(fatos_app.get("roteada")), bool(fatos_ref.get("roteada"))
    _mot_app, _mot_ref = fatos_app.get("motor"), fatos_ref.get("motor")
    _rvr_app = fatos_app.get("razao_vr") or 0.0
    _rvr_ref = fatos_ref.get("razao_vr") or 0.0
    _sc_app = fatos_app.get("score")
    _sc_ref = fatos_ref.get("score")

    # fatores contribuintes (acumulados)
    if _balsa_app != _balsa_ref:
        _subs.append("Diferença por balsa")
    if _flu_app != _flu_ref:
        _subs.append("Diferença por acesso fluvial/isolado")
    if _rot_app != _rot_ref:
        _subs.append("Diferença por ausência de rota rodoviária (distância geodésica de um lado)")
    if _rvr_app > 0 and _rvr_ref > 0 and abs(_rvr_app - _rvr_ref) / max(_rvr_app, _rvr_ref) >= tol_sinuosidade:
        _subs.append("Diferença por sinuosidade da rota")
    if _mot_app and _mot_ref and _mot_app != _mot_ref:
        _subs.append("Diferença por motor de roteamento")
    if _sc_app is not None and _sc_ref is not None and abs(_sc_app - _sc_ref) >= 15:
        _subs.append("Diferença por confiabilidade da geocodificação")

    # categoria PRINCIPAL (a de maior peso operacional)
    if _vant_dist == "Empate" and not _subs:
        _cat = "Empate técnico (diferença estatisticamente irrelevante)"
        _vant = "Empate"
        _cor = "#64748b"
    elif _balsa_app != _balsa_ref:
        # a solução SEM balsa tem vantagem operacional
        _vant = "Referência" if _balsa_app else "Aplicação"
        _cat = "Diferença por balsa (dependência de travessia hidroviária)"
        _cor = "#0891b2"
    elif _flu_app != _flu_ref or _rot_app != _rot_ref:
        _vant = "Referência" if (_flu_app or not _rot_app) else "Aplicação"
        _cat = "Diferença por acesso (fluvial/isolado × rodoviário)"
        _cor = "#2563eb"
    elif "Diferença por sinuosidade da rota" in _subs:
        _vant = "Aplicação" if _rvr_app < _rvr_ref else "Referência"
        _cat = "Diferença por sinuosidade (trajeto menos direto de um lado)"
        _cor = "#7c3aed"
    elif "Diferença por confiabilidade da geocodificação" in _subs:
        _vant = "Aplicação" if (_sc_app or 0) > (_sc_ref or 0) else "Referência"
        _cat = "Diferença por geocodificação/confiabilidade"
        _cor = "#db2777"
    elif "Diferença por motor de roteamento" in _subs:
        _vant = _vant_dist
        _cat = "Diferença por motor (malhas cartográficas distintas)"
        _cor = "#ca8a04"
    elif _vant_dist in ("Aplicação", "Referência"):
        _vant = _vant_dist
        _cat = f"Vantagem puramente viária ({'aplicação' if _vant_dist == 'Aplicação' else 'referência'} mais curta)"
        _cor = "#16a34a" if _vant_dist == "Aplicação" else "#dc2626"
    else:
        _vant = "Empate"
        _cat = "Empate técnico (diferença estatisticamente irrelevante)"
        _cor = "#64748b"

    # sobreposição: a mais longa evita balsa/fluvial → vantagem OPERACIONAL da mais longa
    _oper = None
    if _vant_dist in ("Aplicação", "Referência"):
        _mais_longa = "Referência" if _vant_dist == "Aplicação" else "Aplicação"
        _longa_evita = (
            (_mais_longa == "Aplicação" and (not _balsa_app) and (not _flu_app) and (_balsa_ref or _flu_ref)) or
            (_mais_longa == "Referência" and (not _balsa_ref) and (not _flu_ref) and (_balsa_app or _flu_app))
        )
        if _longa_evita:
            _oper = _mais_longa
            if "Vantagem operacional (rota mais longa, porém sem barreira)" not in _subs:
                _subs.insert(0, "Vantagem operacional (rota mais longa, porém sem barreira)")

    return {
        "categoria": _cat,
        "subcategorias": _subs,
        "vantagem_de": _vant,
        "vantagem_distancia": _vant_dist,
        "vantagem_operacional": _oper,
        "cor": _cor,
    }


def _hipoteses_divergencia(fatos_app, fatos_ref, dif_km, limiar_empate_km=1.0):
    """[DIVERGENCIA-XAI - 236ª] Levanta HIPÓTESES TÉCNICAS para a divergência, a partir dos sinais medidos.
    PURO. Retorna lista de strings (didáticas). Só inclui a hipótese quando o sinal a sustenta."""
    _h = []
    _mot_app, _mot_ref = fatos_app.get("motor"), fatos_ref.get("motor")
    _rvr_app = fatos_app.get("razao_vr") or 0.0
    _rvr_ref = fatos_ref.get("razao_vr") or 0.0
    _dif = abs(_num_seguro(dif_km, 0.0))

    if _mot_app and _mot_ref and _mot_app != _mot_ref:
        _h.append(f"Malhas cartográficas distintas: as rotas venceram por motores diferentes "
                  f"({_mot_app} × {_mot_ref}) — bases de mapa (OSM × Google) e datas de atualização não "
                  f"coincidem, o que explica traçados e quilometragens diferentes.")
    if fatos_app.get("tem_balsa") != fatos_ref.get("tem_balsa"):
        _lado = "aplicação" if fatos_app.get("tem_balsa") else "referência"
        _h.append(f"Travessia por balsa em um dos trajetos (lado da {_lado}): a malha viária pode estar "
                  f"interrompida por corpo d'água, forçando a balsa — dependência de horário, capacidade e "
                  f"condições hidrológicas.")
    if fatos_app.get("fluvial_isolado") != fatos_ref.get("fluvial_isolado"):
        _h.append("Município de acesso fluvial/isolado em um dos lados: não há rota puramente rodoviária "
                  "(lista oficial IBGE REGIC), então a distância é geodésica — comparar com uma viária é "
                  "comparar naturezas diferentes.")
    if _rvr_app > 0 and _rvr_ref > 0 and abs(_rvr_app - _rvr_ref) / max(_rvr_app, _rvr_ref) >= 0.25:
        _mais = "aplicação" if _rvr_app > _rvr_ref else "referência"
        _h.append(f"Rota mais sinuosa na {_mais} (razão viária/reta {max(_rvr_app, _rvr_ref):.2f}× vs "
                  f"{min(_rvr_app, _rvr_ref):.2f}×): contorno de barreira natural (rio, serra) ou via "
                  f"secundária alongando o trajeto.")
    _sc_app, _sc_ref = fatos_app.get("score"), fatos_ref.get("score")
    if _sc_app is not None and _sc_ref is not None and abs(_sc_app - _sc_ref) >= 15:
        _h.append("Geocodificação divergente: a confiabilidade da identificação territorial difere entre os "
                  "destinos (score desigual) — um endereço pode ter caído num ponto diferente do esperado, "
                  "deslocando a origem/destino da medição.")
    if _dif < max(5.0, float(limiar_empate_km) * 3):
        _h.append("Diferença pequena e possivelmente dentro do ruído de medição (matriz pré-computada × "
                  "roteamento ao vivo). Também pode refletir a PENALIZAÇÃO MULTICRITÉRIO da aplicação, que "
                  "aceita alguns km a mais para evitar balsa/isolamento — decisão deliberada, não erro.")
    if not _h:
        _h.append("Sem sinal técnico dominante: a diferença decorre da escolha de polos distintos com "
                  "trajetos rodoviários comparáveis; a decisão recai sobre a menor distância viária.")
    return _h


def _parecer_divergencia(ctx, fatos_app, fatos_ref, classif, iq_app, iq_ref, dif_km, dif_tempo, insc):
    """[DIVERGENCIA-XAI - 236ª] PARECER TÉCNICO DIDÁTICO da divergência, em linguagem natural. PURO.
    Explica o que cada solução escolheu, POR QUE diverge, o trade-off, e o veredito para o candidato e para
    a operação — reconhecendo com transparência quando a referência é superior e diagnosticando o porquê.
    Retorna str."""
    _mun = ctx.get("municipio", "o município")
    _dapp = fatos_app.get("destino", "—")
    _dref = fatos_ref.get("destino", "—")
    _da = fatos_app.get("distancia_km")
    _dr = fatos_ref.get("distancia_km")
    _dif = _num_seguro(dif_km, 0.0)  # + = app mais curta
    _absdif = abs(_dif)
    _vant = classif.get("vantagem_de")
    _insc = int(_num_seguro(insc, 0) or 0)

    _p = []
    # 1) abertura factual
    if _da is not None and _dr is not None:
        _p.append(f"Para {_mun}, a aplicação indicou **{_dapp}** ({_da:.0f} km) e o estudo de referência "
                  f"indicou **{_dref}** ({_dr:.0f} km) — uma diferença de {_absdif:.0f} km.")
    else:
        _p.append(f"Para {_mun}, a aplicação indicou **{_dapp}** e o estudo de referência indicou **{_dref}**.")

    # 2) causa principal
    _p.append(f"A natureza da divergência é: _{classif.get('categoria')}_.")

    # 3) trade-off operacional
    _tr = []
    if fatos_app.get("tem_balsa") and not fatos_ref.get("tem_balsa"):
        _tr.append("o trajeto da **aplicação depende de balsa** (sujeito a horário, capacidade e clima), "
                   "enquanto o da referência é rodoviário")
    elif fatos_ref.get("tem_balsa") and not fatos_app.get("tem_balsa"):
        _tr.append("o trajeto da **referência depende de balsa** (sujeito a horário, capacidade e clima), "
                   "enquanto o da aplicação é exclusivamente rodoviário")
    if fatos_app.get("fluvial_isolado") and not fatos_ref.get("fluvial_isolado"):
        _tr.append("o destino da **aplicação é de acesso fluvial/isolado** (sem rota rodoviária plena)")
    elif fatos_ref.get("fluvial_isolado") and not fatos_app.get("fluvial_isolado"):
        _tr.append("o destino da **referência é de acesso fluvial/isolado** (sem rota rodoviária plena)")
    _rvr_app = fatos_app.get("razao_vr") or 0.0
    _rvr_ref = fatos_ref.get("razao_vr") or 0.0
    if _rvr_app > 0 and _rvr_ref > 0 and abs(_rvr_app - _rvr_ref) / max(_rvr_app, _rvr_ref) >= 0.25:
        _mais = "da aplicação" if _rvr_app > _rvr_ref else "da referência"
        _tr.append(f"a rota {_mais} é sensivelmente mais sinuosa (razão viária/reta "
                   f"{max(_rvr_app, _rvr_ref):.2f}× vs {min(_rvr_app, _rvr_ref):.2f}×)")
    _dt = _num_seguro(dif_tempo)
    if _dt is not None and abs(_dt) >= 5:
        _lado = "a aplicação" if _dt > 0 else "a referência"
        _tr.append(f"{_lado} economiza cerca de {abs(_dt):.0f} min de deslocamento")
    if _tr:
        _p.append("No trade-off, " + "; ".join(_tr) + ".")

    # 4) veredito por qualidade
    _cq_app = iq_app.get("composto", 0.0)
    _cq_ref = iq_ref.get("composto", 0.0)
    if _vant == "Aplicação":
        _porque = []
        if fatos_ref.get("tem_balsa") and not fatos_app.get("tem_balsa"):
            _porque.append("evita a balsa")
        if fatos_ref.get("fluvial_isolado") and not fatos_app.get("fluvial_isolado"):
            _porque.append("evita um destino isolado")
        if _da is not None and _dr is not None and _da < _dr:
            _porque.append(f"reduz o deslocamento em {_absdif:.0f} km")
        if _dt is not None and _dt > 5:
            _porque.append(f"corta ~{abs(_dt):.0f} min")
        _txt = ", ".join(_porque) if _porque else "oferece melhor equilíbrio logístico"
        _p.append(f"**Veredito: a escolha da APLICAÇÃO é superior** para o candidato e para a operação — ela "
                  f"{_txt} (Índice de Qualidade {_cq_app:.0f} vs {_cq_ref:.0f}).")
    elif _vant == "Referência":
        # reconhecimento transparente + diagnóstico do porquê a app perdeu
        _porque_ref = []
        if _dr is not None and _da is not None and _dr < _da:
            _porque_ref.append(f"leva o candidato {_absdif:.0f} km mais perto")
        if fatos_app.get("tem_balsa") and not fatos_ref.get("tem_balsa"):
            _porque_ref.append("sem depender de balsa")
        if _dt is not None and _dt < -5:
            _porque_ref.append(f"economizando ~{abs(_dt):.0f} min")
        _txt = ", ".join(_porque_ref) if _porque_ref else "com melhor índice logístico"
        _p.append(f"**Veredito: a escolha da REFERÊNCIA é superior** neste caso — ela {_txt} "
                  f"(Índice de Qualidade {_cq_ref:.0f} vs {_cq_app:.0f}).")
        # diagnóstico honesto do gargalo interno
        _diag = _diagnostico_derrota_app(fatos_app, fatos_ref, dif_km, classif)
        if _diag:
            _p.append("Por que a aplicação não venceu aqui: " + _diag)
    else:
        _p.append(f"**Veredito: empate técnico** — as duas soluções são operacionalmente equivalentes "
                  f"(Índice de Qualidade {_cq_app:.0f} × {_cq_ref:.0f}); a diferença está dentro do ruído de "
                  f"medição e não justifica trocar de polo.")

    if _insc:
        _p.append(f"Impacto: **{_insc} candidato(s)**.")
    return " ".join(_p)


def _diagnostico_derrota_app(fatos_app, fatos_ref, dif_km, classif):
    """[DIVERGENCIA-XAI - 236ª] Quando a REFERÊNCIA vence, diagnostica o gargalo INTERNO da aplicação
    (excesso de penalização, escolha conservadora, critério secundário, geocodificação, oportunidade
    perdida). PURO. Retorna str (pode ser vazia)."""
    _absdif = abs(_num_seguro(dif_km, 0.0))
    _app_balsa = bool(fatos_app.get("tem_balsa"))
    _ref_balsa = bool(fatos_ref.get("tem_balsa"))
    _app_flu = bool(fatos_app.get("fluvial_isolado"))
    _ref_flu = bool(fatos_ref.get("fluvial_isolado"))

    # a app escolheu a mais longa SEM ganho operacional aparente (a de referência também é limpa)
    if (not _ref_balsa) and (not _ref_flu) and (not _app_balsa) and (not _app_flu):
        if _absdif >= 20:
            return ("a aplicação preferiu um polo rodoviário mais distante sem barreira que o justificasse "
                    "— possível **oportunidade perdida**: revisar se o polo de referência estava no universo "
                    "de destinos avaliado e se a matriz de distâncias o considerou.")
        return ("diferença pequena; provavelmente a matriz pré-computada e o roteamento ao vivo divergiram "
                "por poucos km, ou houve **penalização multicritério** marginal — vale conferir se o critério "
                "de desempate está calibrado.")
    # a app aceitou balsa/isolamento e ainda ficou mais longe
    if (_app_balsa or _app_flu) and (not _ref_balsa) and (not _ref_flu):
        return ("a aplicação escolheu um destino com balsa/isolamento **e** mais distante — a referência "
                "achou uma alternativa rodoviária melhor em ambos os aspectos; **auditar a geocodificação do "
                "polo** e verificar se a opção rodoviária constava na lista de candidatos.")
    # a app foi conservadora (evitou balsa/isolamento) e por isso ficou mais longa — não é erro
    if (_ref_balsa or _ref_flu) and (not _app_balsa) and (not _app_flu):
        return ("na verdade **não é um gargalo**: a aplicação ficou mais longa porque **evitou balsa/"
                "isolamento** — uma escolha conservadora deliberada. Só reveja se, no seu contexto, a menor "
                "distância da referência compensa a dependência hidroviária.")
    if "motor" in str(classif.get("categoria", "")).lower():
        return ("a diferença vem do **motor de roteamento** (malha cartográfica): o polo da referência pode "
                "ser realmente mais próximo por uma via que falta na base usada pela aplicação — caso para "
                "**auditoria de rota** com um segundo motor.")
    return ""


def _recomendacao_divergencia(ctx, classif, iq_app, iq_ref, dif_km, insc, fatos_app, fatos_ref):
    """[DIVERGENCIA-XAI - 236ª] Recomendação PRÁTICA por caso. PURO. Retorna str curta e acionável."""
    _vant = classif.get("vantagem_de")
    _insc = int(_num_seguro(insc, 0) or 0)
    _absdif = abs(_num_seguro(dif_km, 0.0))
    if _vant == "Referência" and _absdif >= 20 and _insc >= 50:
        return ("🔴 Oportunidade ALTA: revisar manualmente — a referência leva vantagem relevante com muitos "
                "candidatos. Conferir se o polo dela estava no universo de destinos e recalibrar a alocação.")
    if _vant == "Referência" and (_absdif >= 20 or _insc >= 50):
        return ("🟠 Revisar: a referência é superior aqui. Auditar a rota e a geocodificação do polo escolhido "
                "pela aplicação.")
    if _vant == "Referência":
        return ("🟡 Conferir: pequena vantagem da referência. Verificar se compensa trocar de polo dado o "
                "eventual trade-off operacional.")
    if _vant == "Aplicação" and (fatos_ref.get("tem_balsa") or fatos_ref.get("fluvial_isolado")):
        return ("🟢 Manter a aplicação: ela evita balsa/isolamento. Divergência favorável e bem fundamentada.")
    if _vant == "Aplicação":
        return "🟢 Manter a aplicação: escolha mais curta e/ou mais robusta."
    return "⚪ Empate técnico: qualquer das duas serve; manter a atual evita retrabalho."


def _analisar_divergencia_par(linha, fatos_app, fatos_ref, limiar_empate_km=1.0):
    """[DIVERGENCIA-XAI - 236ª] Analisa UMA divergência município a município. PURO. Junta classificação,
    índices de qualidade das DUAS escolhas, parecer, hipóteses e recomendação, e define o vencedor por
    QUALIDADE. Retorna um dict rico (uma linha do diagnóstico)."""
    _mun = linha.get("Origem") or linha.get("municipio") or "—"
    _uf = str(linha.get("UF") or "").upper()
    _insc = _num_seguro(linha.get("Inscritos"), 0.0) or 0.0
    _da = fatos_app.get("distancia_km")
    _dr = fatos_ref.get("distancia_km")

    _dif_km = None
    if _da is not None and _dr is not None:
        _dif_km = round(_dr - _da, 2)  # + = aplicação mais curta
    _dif_pct = None
    if _dif_km is not None and _dr and _dr > 0:
        _dif_pct = round(100.0 * _dif_km / _dr, 2)

    _ta, _tr = fatos_app.get("tempo_min"), fatos_ref.get("tempo_min")
    _dif_tempo = round(_tr - _ta, 1) if (_ta is not None and _tr is not None) else None

    # divergência de motores (se ambos roteados) — alimenta o índice de robustez
    _diverg = _metricas_divergencia(_da, _dr) if (_da and _dr) else None
    _div_pct = _diverg["pct"] if _diverg else 0.0

    _classif = _classificar_divergencia(fatos_app, fatos_ref, _dif_km, limiar_empate_km=limiar_empate_km)

    # índice de qualidade de cada escolha (vantagem de cada uma sobre a outra)
    _difkm_app = _dif_km if _dif_km is not None else 0.0
    _difpct_app = _dif_pct if _dif_pct is not None else 0.0
    _iq_app = _indice_qualidade_escolha(fatos_app, _difkm_app, _difpct_app, _div_pct)
    _difkm_ref = (-_dif_km) if _dif_km is not None else 0.0
    _difpct_ref = round(100.0 * _difkm_ref / _da, 2) if (_da and _da > 0 and _dif_km is not None) else 0.0
    _iq_ref = _indice_qualidade_escolha(fatos_ref, _difkm_ref, _difpct_ref, _div_pct)

    _ctx = {"municipio": _mun, "uf": _uf}
    _parecer = _parecer_divergencia(_ctx, fatos_app, fatos_ref, _classif, _iq_app, _iq_ref,
                                    _dif_km, _dif_tempo, _insc)
    _hip = _hipoteses_divergencia(fatos_app, fatos_ref, _dif_km, limiar_empate_km=limiar_empate_km)
    _rec = _recomendacao_divergencia(_ctx, _classif, _iq_app, _iq_ref, _dif_km, _insc, fatos_app, fatos_ref)

    # vencedor por QUALIDADE (empate se |Δíndice| < 3 pontos)
    _cq_app, _cq_ref = _iq_app["composto"], _iq_ref["composto"]
    if abs(_cq_app - _cq_ref) < 3.0:
        _venc_q = "Empate"
    else:
        _venc_q = "Aplicação" if _cq_app > _cq_ref else "Referência"

    return {
        "Município": _mun, "UF": _uf, "Inscritos": int(_insc),
        "Destino Aplicação": fatos_app.get("destino"), "Destino Referência": fatos_ref.get("destino"),
        "Coord Origem": fatos_app.get("coord_origem") or fatos_ref.get("coord_origem"),
        "Coord Destino Aplicação": fatos_app.get("coord_destino"),
        "Coord Destino Referência": fatos_ref.get("coord_destino"),
        "IBGE Destino Aplicação": fatos_app.get("cod_ibge_destino"),
        "IBGE Destino Referência": fatos_ref.get("cod_ibge_destino"),

        "Distância Aplicação (km)": _da, "Distância Referência (km)": _dr,
        "Diferença (km)": _dif_km, "Diferença (%)": _dif_pct,
        "Diferença Tempo (min)": _dif_tempo,
        "Balsa Aplicação": "Sim" if fatos_app.get("tem_balsa") else "Não",
        "Balsa Referência": "Sim" if fatos_ref.get("tem_balsa") else "Não",
        "Acesso Aplicação": fatos_app.get("modo_acesso"),
        "Acesso Referência": fatos_ref.get("modo_acesso"),
        "Sinuosidade Aplicação (V/R)": fatos_app.get("razao_vr"),
        "Sinuosidade Referência (V/R)": fatos_ref.get("razao_vr"),
        "Motor Aplicação": fatos_app.get("motor"), "Motor Referência": fatos_ref.get("motor"),
        "Divergência Motores (%)": _div_pct,
        "Categoria": _classif["categoria"],
        "Subcategorias": "; ".join(_classif["subcategorias"]) if _classif["subcategorias"] else "—",
        "Vantagem de": _classif["vantagem_de"],
        "Índice Qualidade Aplicação": _cq_app,
        "Índice Qualidade Referência": _cq_ref,
        "Vencedor (Qualidade)": _venc_q,
        "Parecer Técnico": _parecer,
        "Hipóteses": _hip,
        "Recomendação": _rec,
        "Impacto (km × inscritos)": round((_dif_km or 0.0) * _insc, 1),
        "_cor": _classif["cor"],
        "_iq_app": _iq_app, "_iq_ref": _iq_ref, "_classif": _classif,
    }


def _agregar_diagnostico_divergencias(analises, uf_para_regiao=None):
    """[DIVERGENCIA-XAI - 236ª] Agrega as análises por município em INTELIGÊNCIA: resumo executivo, insights
    automáticos DATA-DRIVEN, ranking das causas, distribuições, maiores perdas/ganhos, oportunidades e
    recomendações agregadas. PURO. `uf_para_regiao` injetável (default _UF_PARA_REGIAO)."""
    _ufr = uf_para_regiao if uf_para_regiao is not None else _UF_PARA_REGIAO
    _n = len(analises)
    if _n == 0:
        return {"n_divergencias": 0, "resumo": {}, "insights": [], "ranking_causas": [],
                "distribuicoes": {}, "maiores_perdas": [], "maiores_ganhos": [],
                "oportunidades": [], "recomendacoes": []}

    _insc_tot = sum(int(a.get("Inscritos") or 0) for a in analises)
    _venc = [a.get("Vencedor (Qualidade)") for a in analises]
    _v_app = _venc.count("Aplicação")
    _v_ref = _venc.count("Referência")
    _v_emp = _venc.count("Empate")
    _insc_app = sum(int(a.get("Inscritos") or 0) for a in analises if a.get("Vencedor (Qualidade)") == "Aplicação")
    _insc_ref = sum(int(a.get("Inscritos") or 0) for a in analises if a.get("Vencedor (Qualidade)") == "Referência")

    # perdas = casos em que a referência é superior por qualidade
    _perdas = [a for a in analises if a.get("Vencedor (Qualidade)") == "Referência"]
    _ganhos = [a for a in analises if a.get("Vencedor (Qualidade)") == "Aplicação"]

    _resumo = {
        "divergencias": _n, "inscritos_impactados": _insc_tot,
        "app_superior": _v_app, "ref_superior": _v_ref, "empates": _v_emp,
        "pct_app_superior": round(100.0 * _v_app / _n, 1),
        "pct_ref_superior": round(100.0 * _v_ref / _n, 1),
        "pct_empate": round(100.0 * _v_emp / _n, 1),
        "inscritos_beneficiados_app": _insc_app, "inscritos_em_perda": _insc_ref,
    }

    # ------- INSIGHTS AUTOMÁTICOS (fundamentados nos dados) -------
    _ins = []
    if _perdas:
        _dif_perdas = [abs(a.get("Diferença (km)") or 0.0) for a in _perdas]
        _lt5 = sum(1 for d in _dif_perdas if d < 5)
        if _dif_perdas:
            _ins.append(f"{round(100.0 * _lt5 / len(_perdas))}% das perdas ocorreram por diferenças inferiores "
                        f"a 5 km — margens estreitas, sensíveis a ruído de medição e a critério de desempate.")
        _flu_perdas = sum(1 for a in _perdas if "fluvial" in str(a.get("Categoria", "")).lower()
                          or a.get("Balsa Aplicação") == "Sim")
        if _flu_perdas:
            _ins.append(f"{round(100.0 * _flu_perdas / len(_perdas))}% das perdas envolvem balsa ou acesso "
                        f"fluvial/isolado no lado da aplicação — a menor distância da referência frequentemente "
                        f"vem de assumir uma travessia que a aplicação evitou.")
    if _ganhos:
        _g_evita = sum(1 for a in _ganhos if a.get("Balsa Referência") == "Sim"
                       or "fluvial" in str(a.get("Acesso Referência", "")).lower())
        if _g_evita:
            _ins.append(f"A aplicação vence com mais frequência quando prioriza **acessibilidade rodoviária**: "
                        f"{round(100.0 * _g_evita / len(_ganhos))}% dos seus ganhos evitam balsa/isolamento da "
                        f"referência.")
    # concentração regional das perdas
    _perda_reg = {}
    for a in _perdas:
        _r = _ufr.get(str(a.get("UF") or "").upper(), "Indefinido")
        _perda_reg[_r] = _perda_reg.get(_r, 0) + int(a.get("Inscritos") or 0)
    if _perda_reg:
        _reg_top = max(_perda_reg, key=_perda_reg.get)
        if _perda_reg[_reg_top] > 0:
            _ins.append(f"Os maiores ganhos da referência concentram-se na região **{_reg_top}** "
                        f"({_perda_reg[_reg_top]} candidatos em perda) — foco prioritário de revisão.")
    # padrão da referência
    _ref_puro_dist = sum(1 for a in _perdas if "puramente viária" in str(a.get("Categoria", "")).lower())
    if _perdas and _ref_puro_dist:
        _ins.append(f"A referência vence principalmente em cenários de **menor distância absoluta** "
                    f"({round(100.0 * _ref_puro_dist / len(_perdas))}% das perdas são vantagem puramente "
                    f"viária), sem ganho operacional adicional.")
    if not _ins:
        _ins.append("As divergências não formam um padrão dominante — são casos pontuais de polos distintos "
                    "com trajetos comparáveis.")

    # ------- RANKING DAS CAUSAS -------
    _causas = {}
    for a in analises:
        _c = a.get("Categoria", "—")
        if _c not in _causas:
            _causas[_c] = {"Causa": _c, "Casos": 0, "Inscritos": 0}
        _causas[_c]["Casos"] += 1
        _causas[_c]["Inscritos"] += int(a.get("Inscritos") or 0)
    _ranking_causas = sorted(_causas.values(), key=lambda x: (-x["Inscritos"], -x["Casos"]))

    # ------- DISTRIBUIÇÕES -------
    def _distrib(keyfn):
        _d = {}
        for a in analises:
            _k = keyfn(a) or "—"
            if _k not in _d:
                _d[_k] = {"Categoria": _k, "Casos": 0, "Inscritos": 0}
            _d[_k]["Casos"] += 1
            _d[_k]["Inscritos"] += int(a.get("Inscritos") or 0)
        return sorted(_d.values(), key=lambda x: -x["Inscritos"])

    _distribuicoes = {
        "por_uf": _distrib(lambda a: str(a.get("UF") or "—").upper()),
        "por_regiao": _distrib(lambda a: _ufr.get(str(a.get("UF") or "").upper(), "Indefinido")),
        "por_categoria": _distrib(lambda a: a.get("Categoria")),
        "por_vencedor": _distrib(lambda a: a.get("Vencedor (Qualidade)")),
        "por_motor_ref": _distrib(lambda a: a.get("Motor Referência")),
        "por_acesso_app": _distrib(lambda a: a.get("Acesso Aplicação")),
        "por_balsa": _distrib(lambda a: "Aplicação com balsa" if a.get("Balsa Aplicação") == "Sim"
                              else ("Referência com balsa" if a.get("Balsa Referência") == "Sim" else "Sem balsa")),
    }

    # ------- MAIORES PERDAS / GANHOS (ponderado por inscritos) -------
    def _slim(a):
        return {k: a.get(k) for k in ("Município", "UF", "Inscritos", "Destino Aplicação",
                                      "Destino Referência", "Diferença (km)", "Categoria",
                                      "Índice Qualidade Aplicação", "Índice Qualidade Referência",
                                      "Recomendação")}
    _maiores_perdas = [_slim(a) for a in sorted(
        _perdas, key=lambda a: (abs(a.get("Diferença (km)") or 0.0) * (int(a.get("Inscritos") or 0) or 1)),
        reverse=True)[:50]]
    _maiores_ganhos = [_slim(a) for a in sorted(
        _ganhos, key=lambda a: (abs(a.get("Diferença (km)") or 0.0) * (int(a.get("Inscritos") or 0) or 1)),
        reverse=True)[:50]]

    # ------- OPORTUNIDADES (perdas relevantes = onde a app pode melhorar) -------
    _opp = []
    for a in _perdas:
        _score_opp = abs(a.get("Diferença (km)") or 0.0) * (int(a.get("Inscritos") or 0) or 1)
        _opp.append({"Município": a.get("Município"), "UF": a.get("UF"), "Inscritos": a.get("Inscritos"),
                     "Ganho potencial (km)": abs(a.get("Diferença (km)") or 0.0),
                     "Impacto (km × inscritos)": round(_score_opp, 1),
                     "Causa": a.get("Categoria"), "Ação": a.get("Recomendação")})
    _opp = sorted(_opp, key=lambda x: -x["Impacto (km × inscritos)"])[:50]

    # ------- RECOMENDAÇÕES AGREGADAS -------
    _recs = []
    if _maiores_perdas:
        _topn = _maiores_perdas[:10]
        _recs.append(f"Revisar manualmente os **{len(_topn)} municípios de maior perda** (lista de "
                     f"Oportunidades) — concentram o maior ganho potencial ponderado por candidatos.")
    # polos recorrentes onde a app perde
    _polo_perda = {}
    for a in _perdas:
        _pp = a.get("Destino Aplicação") or "—"
        _polo_perda[_pp] = _polo_perda.get(_pp, 0) + 1
    _polo_rec = [p for p, c in sorted(_polo_perda.items(), key=lambda x: -x[1]) if c >= 3][:5]
    if _polo_rec:
        _recs.append(f"Reavaliar os polos onde a aplicação mais perde: {', '.join(_polo_rec)} "
                     f"(recorrentes em ≥3 divergências desfavoráveis).")
    _perda_empate = sum(1 for a in _perdas if abs(a.get("Diferença (km)") or 0.0) < 5)
    if _perdas and _perda_empate / max(1, len(_perdas)) >= 0.4:
        _recs.append("Recalibrar o **critério de desempate/penalização multicritério**: boa parte das perdas "
                     "está em margens < 5 km, onde o ajuste fino da penalização pode inverter o resultado a "
                     "favor da aplicação sem prejuízo operacional.")
    _alta_div = [a for a in analises if (a.get("Divergência Motores (%)") or 0) >= 30]
    if _alta_div:
        _recs.append(f"Auditar as rotas com **alta divergência entre motores** ({len(_alta_div)} casos ≥30%): "
                     f"conferir com um segundo motor qual malha reflete a via real.")
    if _v_app >= _v_ref and _v_ref > 0:
        _recs.append("Manter a política atual da aplicação (ela é superior na maioria), tratando as perdas como "
                     "exceções pontuais a revisar caso a caso.")
    if not _recs:
        _recs.append("Nenhuma ação sistemática necessária — as divergências são pontuais e bem explicadas.")

    return {
        "n_divergencias": _n, "resumo": _resumo, "insights": _ins,
        "ranking_causas": _ranking_causas, "distribuicoes": _distribuicoes,
        "maiores_perdas": _maiores_perdas, "maiores_ganhos": _maiores_ganhos,
        "oportunidades": _opp, "recomendacoes": _recs,
    }


# ==============================================================================
# [DIVERGENCIA-XAI - 236ª] SAÍDA 1/2 — SEÇÃO HTML "Diagnóstico Inteligente das Divergências"
# ==============================================================================
def _div_tabela_html(titulo, colunas, linhas, _he):
    """Renderiza uma tabela HTML simples e responsiva. PURO."""
    if not linhas:
        return ""
    _th = "".join(f"<th>{_he.escape(str(c))}</th>" for c in colunas)
    _tr = ""
    for _l in linhas:
        _tds = "".join(f"<td>{_he.escape(str(_l.get(c, '—')))}</td>" for c in colunas)
        _tr += f"<tr>{_tds}</tr>"
    return (f'<h3>{_he.escape(titulo)}</h3>'
            f'<div class="tbl-wrap"><table class="dvt"><thead><tr>{_th}</tr></thead>'
            f'<tbody>{_tr}</tbody></table></div>')


def _div_barras_html(titulo, pares, unidade="", _he=None):
    """Barras horizontais em HTML puro (sem Plotly) para distribuições. `pares` = lista de (rótulo, valor).
    PURO e offline."""
    import html as _hh
    _he = _he or _hh
    _pares = [(str(k), float(v)) for k, v in pares if v is not None]
    if not _pares:
        return ""
    _max = max(v for _, v in _pares) or 1.0
    _rows = ""
    for _k, _v in _pares:
        _pct = max(2.0, 100.0 * _v / _max)
        _rows += (f'<div class="dvb-row"><div class="dvb-lbl">{_he.escape(_k)}</div>'
                  f'<div class="dvb-bar"><div class="dvb-fill" style="width:{_pct:.1f}%"></div></div>'
                  f'<div class="dvb-val">{_v:,.0f}{_he.escape(unidade)}</div></div>')
    return f'<h3>{_he.escape(titulo)}</h3><div class="dvb">{_rows}</div>'


def _diagnostico_divergencias_html(diag):
    """[DIVERGENCIA-XAI - 236ª] Seção HTML autocontida do "Diagnóstico Inteligente das Divergências".
    PURA e defensiva: diag vazio → ''. Retorna um <section> completo (com <h2>) pronto para o relatório."""
    import html as _he
    try:
        if not diag or not diag.get("n_divergencias"):
            return ""
        _r = diag.get("resumo", {})
        _analises = diag.get("analises") or []
        _ag = diag.get("agregado") or diag  # aceita tanto o dict completo quanto o agregado direto
        if "resumo" not in _ag and "resumo" in diag:
            _ag = diag
        _res = _ag.get("resumo", _r)
        _ins = _ag.get("insights", [])
        _rank = _ag.get("ranking_causas", [])
        _dist = _ag.get("distribuicoes", {})
        _perdas = _ag.get("maiores_perdas", [])
        _ganhos = _ag.get("maiores_ganhos", [])
        _opp = _ag.get("oportunidades", [])
        _recs = _ag.get("recomendacoes", [])
        _n = _ag.get("n_divergencias", len(_analises))

        # ---- KPIs ----
        def _kpi(v, r):
            return (f'<div class="dv-kpi"><div class="dv-kpi-v">{v}</div>'
                    f'<div class="dv-kpi-r">{_he.escape(r)}</div></div>')
        _kpis = ('<div class="dv-kpis">'
                 + _kpi(f'{_n:,}', "municípios com destino diferente")
                 + _kpi(f'{int(_res.get("inscritos_impactados", 0)):,}', "candidatos impactados")
                 + _kpi(f'{_res.get("app_superior", 0)}', "vitórias da aplicação (por qualidade)")
                 + _kpi(f'{_res.get("ref_superior", 0)}', "vitórias da referência (por qualidade)")
                 + _kpi(f'{_res.get("empates", 0)}', "empates técnicos")
                 + '</div>')

        # ---- resumo executivo ----
        _pa = _res.get("pct_app_superior", 0.0)
        _pr = _res.get("pct_ref_superior", 0.0)
        _resumo_txt = (f"Foram investigadas <b>{_n}</b> divergências (municípios em que a aplicação e o estudo "
                       f"de referência escolheram locais de prova diferentes), impactando "
                       f"<b>{int(_res.get('inscritos_impactados', 0)):,}</b> candidatos. Avaliando cada escolha "
                       f"por um <b>Índice de Qualidade multicritério</b> (distância, tempo, acessibilidade, "
                       f"robustez, confiabilidade e risco operacional), a aplicação foi superior em "
                       f"<b>{_pa:.0f}%</b> dos casos e a referência em <b>{_pr:.0f}%</b>. "
                       f"Abaixo, o porquê de cada resultado — com pareceres técnicos, hipóteses e recomendações "
                       f"acionáveis.")
        # Caixa inline autossuficiente (NÃO usa _caixa_explicativa, que depende de um _he global
        # inexistente no módulo — ver auditoria). _resumo_txt é HTML que nós mesmos geramos.
        _box_resumo = (f'<div class="dv-box"><div class="dv-box-t">💡 Resumo executivo</div>'
                       f'<div class="dv-box-c">{_resumo_txt}</div></div>')

        # ---- causas das vitórias (app × ref) ----
        _causas_app, _causas_ref = {}, {}
        for a in _analises:
            _c = a.get("Categoria", "—")
            if a.get("Vencedor (Qualidade)") == "Aplicação":
                _causas_app[_c] = _causas_app.get(_c, 0) + 1
            elif a.get("Vencedor (Qualidade)") == "Referência":
                _causas_ref[_c] = _causas_ref.get(_c, 0) + 1
        _bar_app = _div_barras_html("Principais causas das vitórias da APLICAÇÃO",
                                    sorted(_causas_app.items(), key=lambda x: -x[1]), " casos", _he)
        _bar_ref = _div_barras_html("Principais causas das vitórias da REFERÊNCIA",
                                    sorted(_causas_ref.items(), key=lambda x: -x[1]), " casos", _he)

        # ---- ranking dos fatores determinantes ----
        _tab_rank = _div_tabela_html("Ranking dos fatores determinantes (por candidatos impactados)",
                                     ["Causa", "Casos", "Inscritos"], _rank[:15], _he)

        # ---- distribuições ----
        _dist_html = ""
        _mapa_dist = [("por_uf", "Distribuição por UF (candidatos)"),
                      ("por_regiao", "Distribuição por região (candidatos)"),
                      ("por_vencedor", "Distribuição por vencedor (candidatos)"),
                      ("por_acesso_app", "Distribuição por tipo de acesso da aplicação (candidatos)"),
                      ("por_balsa", "Distribuição por presença de balsa (candidatos)")]
        for _k, _t in _mapa_dist:
            _d = _dist.get(_k, [])
            if _d:
                _pares = [(x.get("Categoria", "—"), x.get("Inscritos", 0)) for x in _d[:8]]
                _dist_html += _div_barras_html(_t, _pares, "", _he)

        # ---- insights ----
        _ins_html = ""
        if _ins:
            _lis = "".join(f"<li>{_he.escape(x)}</li>" for x in _ins)
            _ins_html = f'<h3>🔎 Insights automáticos</h3><ul class="dv-ins">{_lis}</ul>'

        # ---- oportunidades ----
        _tab_opp = _div_tabela_html("🎯 Oportunidades de melhoria (maior ganho potencial ponderado)",
                                    ["Município", "UF", "Inscritos", "Ganho potencial (km)",
                                     "Impacto (km × inscritos)", "Causa"], _opp[:15], _he)

        # ---- recomendações ----
        _rec_html = ""
        if _recs:
            _lis = "".join(f"<li>{_he.escape(x)}</li>" for x in _recs)
            _rec_html = f'<h3>✅ Recomendações automáticas</h3><ul class="dv-rec">{_lis}</ul>'

        # ---- pareceres técnicos (top casos por impacto) ----
        _ordenadas = sorted(_analises, key=lambda a: abs((a.get("Diferença (km)") or 0.0)
                            * (int(a.get("Inscritos") or 0) or 1)), reverse=True)[:20]
        _pareceres = ""
        for a in _ordenadas:
            _cor = a.get("_cor", "#64748b")
            _venc = a.get("Vencedor (Qualidade)", "—")
            _hip = a.get("Hipóteses") or []
            _hip_html = "".join(f"<li>{_he.escape(h)}</li>" for h in _hip)
            _pareceres += (
                f'<div class="dv-caso" style="border-left:4px solid {_cor}">'
                f'<div class="dv-caso-h"><b>{_he.escape(str(a.get("Município")))}/{_he.escape(str(a.get("UF")))}</b>'
                f' · {_he.escape(str(a.get("Categoria")))} · <span class="dv-tag">Vantagem: {_he.escape(_venc)}</span></div>'
                f'<div class="dv-caso-p">{_he.escape(a.get("Parecer Técnico", ""))}</div>'
                f'<div class="dv-caso-hip"><b>Hipóteses técnicas:</b><ul>{_hip_html}</ul></div>'
                f'<div class="dv-caso-rec">{_he.escape(a.get("Recomendação", ""))}</div>'
                f'</div>')
        _pareceres_html = (f'<h3>📝 Pareceres técnicos — os {len(_ordenadas)} casos de maior impacto</h3>'
                           f'<div class="dv-casos">{_pareceres}</div>') if _pareceres else ""

        _css = (
            '<style>'
            '.dv-kpis{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}'
            '.dv-kpi{flex:1;min-width:150px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:14px}'
            '.dv-kpi-v{font-size:26px;font-weight:800;color:#0f172a}'
            '.dv-kpi-r{font-size:12px;color:#64748b;margin-top:4px}'
            '.dv-box{border-left:4px solid #2563eb;background:#eff6ff;border-radius:8px;padding:12px 14px;margin:14px 0}'
            '.dv-box-t{font-weight:700;color:#1e3a8a;margin-bottom:6px}'
            '.dv-box-c{font-size:14px;line-height:1.6;color:#1f2937}'
            '.dvt{width:100%;border-collapse:collapse;font-size:13px;margin:6px 0 18px}'
            '.dvt th{background:#1e3a8a;color:#fff;padding:8px;text-align:left}'
            '.dvt td{padding:7px 8px;border-bottom:1px solid #eef2f7}'
            '.dvt tr:nth-child(even){background:#f8fafc}'
            '.tbl-wrap{overflow-x:auto}'
            '.dvb{margin:6px 0 18px}.dvb-row{display:flex;align-items:center;gap:10px;margin:4px 0}'
            '.dvb-lbl{width:230px;font-size:12px;color:#334155;text-align:right;flex-shrink:0}'
            '.dvb-bar{flex:1;background:#eef2f7;border-radius:5px;height:16px;overflow:hidden}'
            '.dvb-fill{height:100%;background:linear-gradient(90deg,#2563eb,#60a5fa)}'
            '.dvb-val{width:90px;font-size:12px;color:#0f172a;font-weight:600}'
            '.dv-ins li,.dv-rec li{margin:6px 0;line-height:1.5}'
            '.dv-casos{display:flex;flex-direction:column;gap:12px}'
            '.dv-caso{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:14px}'
            '.dv-caso-h{font-size:13px;color:#334155;margin-bottom:6px}'
            '.dv-tag{background:#eef2ff;color:#3730a3;padding:2px 8px;border-radius:12px;font-size:11px}'
            '.dv-caso-p{font-size:14px;line-height:1.6;color:#1f2937;margin:6px 0}'
            '.dv-caso-hip{font-size:12px;color:#475569;margin:6px 0}.dv-caso-hip ul{margin:4px 0 0 18px}'
            '.dv-caso-rec{font-size:13px;font-weight:600;color:#0f172a;margin-top:6px}'
            '</style>')

        # [DIVERGENCIA-XAI-2 - 237ª] blocos do aprofundamento (KPIs, classificação de derrotas, aprendizado)
        try:
            _stage_a_html = _html_stage_a(diag, _he)
        except Exception:
            _stage_a_html = ""
        # [DIVERGENCIA-XAI-3 - 239ª] auditoria avançada (KPIs extremos, precisão, faixas, árvores de decisão)
        try:
            _stage_b_html = _html_stage_b(diag, _he)
        except Exception:
            _stage_b_html = ""
        try:
            _tel_html = _html_telemetria(diag, _he)
        except Exception:
            _tel_html = ""
        try:
            _laudo_html = _html_laudo(diag, _he)
        except Exception:
            _laudo_html = ""
        try:
            _cartoes_html = _html_cartoes(diag, _he)
        except Exception:
            _cartoes_html = ""
        # [POS-DIAGNOSTICO - 256ª geração] Bloco de reconciliação no topo do relatório — mesmo texto/veredito
        # que a tela mostra após processar (o que o roteamento fresco revelou vs. o placar original).
        _recon_html = ""
        try:
            _pos_r = _resumo_pos_diagnostico_divergencias(diag)
            if _pos_r and _pos_r.get("linhas"):
                _titulo_r = ("🔄 Resultado do reprocessamento — o placar merece um ajuste fino"
                             if _pos_r.get("houve_ajuste")
                             else "🔄 Resultado do reprocessamento — o placar do topo se confirma")
                _linhas_r = ""
                import re as _re_pos
                for _lp in _pos_r.get("linhas", []):
                    _lp_html = _re_pos.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", _lp)
                    _linhas_r += f"<p style='margin:0 0 8px'>{_lp_html}</p>"
                _recon_html = (f'<div class="dv-box" style="border-left:4px solid #1e3a8a">'
                               f'<div class="dv-box-t">{_he.escape(_titulo_r)}</div>'
                               f'<div class="dv-box-c">{_linhas_r}</div></div>')
        except Exception:
            _recon_html = ""
        return (f'<section id="diag-divergencias">{_css}'
                f'<h2>🔬 Diagnóstico Inteligente das Divergências</h2>'
                f'{_recon_html}'
                f'{_kpis}{_box_resumo}'
                f'{_cartoes_html}'
                f'{_ins_html}'
                f'{_bar_app}{_bar_ref}{_tab_rank}'
                f'{_dist_html}'
                f'{_tab_opp}{_rec_html}'
                f'{_stage_a_html}'
                f'{_stage_b_html}'
                f'{_tel_html}'
                f'{_laudo_html}'
                f'{_pareceres_html}'
                f'</section>')
    except Exception:
        return ""


# ==============================================================================
# [DIVERGENCIA-XAI - 236ª] SAÍDA 2/2 — ABAS EXCEL do "Diagnóstico das Divergências"
# ==============================================================================
def _abas_diagnostico_divergencias(writer, diag):
    """[DIVERGENCIA-XAI - 236ª] Escreve as abas analíticas do diagnóstico de divergências na planilha do
    Comparador, espelhando a seção HTML: Resumo, Divergências (tabela rica), Pareceres & Hipóteses, Ranking
    das Causas (c/ gráfico), Oportunidades, Análise dos Motores, Análise Territorial (c/ gráfico) e Análise
    Operacional. Cada aba tem explicação didática abaixo das tabelas. DEFENSIVO: diag vazio → no-op; cada aba
    isolada em try (erro numa aba não derruba as demais nem o export). Só grava se houver dados. PURO quanto
    a I/O de rede — usa apenas o dict `diag` já calculado."""
    try:
        if not diag or not diag.get("n_divergencias"):
            return
        _wb = getattr(writer, "book", None)
        if _wb is None or not hasattr(_wb, "add_format"):
            return
        _analises = diag.get("analises") or []
        _res = diag.get("resumo", {}) or {}
        _ins = diag.get("insights", []) or []
        _rank = diag.get("ranking_causas", []) or []
        _dist = diag.get("distribuicoes", {}) or {}
        _opp = diag.get("oportunidades", []) or []
        _recs = diag.get("recomendacoes", []) or []

        # ---- formatos reutilizáveis (mesmo padrão de _abas_cientificas_alocacao) ----
        _f_tit = _wb.add_format({"bold": True, "font_size": 16, "font_color": "#1e3a8a"})
        _f_sub = _wb.add_format({"bold": True, "font_size": 11, "font_color": "#334155"})
        _f_lbl = _wb.add_format({"font_size": 10, "font_color": "#475569"})
        _f_num = _wb.add_format({"font_size": 10, "num_format": "#,##0.0", "align": "right"})
        _f_int = _wb.add_format({"font_size": 10, "num_format": "#,##0", "align": "right"})
        _f_pct = _wb.add_format({"font_size": 10, "num_format": "#,##0.0", "align": "right"})
        _f_hdr = _wb.add_format({"bold": True, "font_size": 10, "font_color": "#ffffff",
                                 "bg_color": "#1e3a8a", "border": 1, "border_color": "#cbd5e1", "align": "center",
                                 "text_wrap": True, "valign": "vcenter"})
        _f_exp = _wb.add_format({"font_size": 10, "font_color": "#334155", "italic": True,
                                 "text_wrap": True, "valign": "top"})
        _f_txt = _wb.add_format({"font_size": 10, "font_color": "#334155", "text_wrap": True, "valign": "top"})
        _f_kpi = _wb.add_format({"bold": True, "font_size": 20, "font_color": "#0f172a", "align": "left"})
        _f_kpr = _wb.add_format({"font_size": 9, "font_color": "#64748b"})

        def _escrever_tabela(_ws, _r0, colunas, linhas, larguras=None):
            """Escreve cabeçalho + linhas de dicts. Retorna a última linha usada."""
            for _c, _nome in enumerate(colunas):
                _ws.write(_r0, _c, _nome, _f_hdr)
                if larguras and _c < len(larguras):
                    _ws.set_column(_c, _c, larguras[_c])
            _rr = _r0
            for _l in linhas:
                _rr += 1
                for _c, _nome in enumerate(colunas):
                    _v = _l.get(_nome, "—")
                    if isinstance(_v, bool):
                        _ws.write(_rr, _c, "Sim" if _v else "Não", _f_lbl)
                    elif isinstance(_v, (int,)) and not isinstance(_v, bool):
                        _ws.write_number(_rr, _c, _v, _f_int)
                    elif isinstance(_v, float):
                        _ws.write_number(_rr, _c, _v, _f_num)
                    elif _v is None:
                        _ws.write(_rr, _c, "—", _f_lbl)
                    else:
                        _ws.write(_rr, _c, str(_v), _f_lbl)
            return _rr

        def _explicacao(_ws, _r, _ncols, _texto, _altura=64):
            _ws.merge_range(_r, 0, _r, max(1, _ncols - 1), _texto, _f_exp)
            _ws.set_row(_r, _altura)

        # ============ ABA 1: RESUMO ============
        try:
            _ws = _wb.add_worksheet("Diag - Resumo")
            _ws.set_column("A:A", 34); _ws.set_column("B:F", 16)
            _ws.write("A1", "Diagnóstico Inteligente das Divergências", _f_tit)
            _ws.write("A2", "Por que a aplicação e o estudo de referência divergiram — e o que fazer a respeito.", _f_lbl)
            _kpis = [("Municípios com destino diferente", diag.get("n_divergencias", 0), _f_int),
                     ("Candidatos impactados", int(_res.get("inscritos_impactados", 0)), _f_int),
                     ("Vitórias da aplicação (qualidade)", int(_res.get("app_superior", 0)), _f_int),
                     ("Vitórias da referência (qualidade)", int(_res.get("ref_superior", 0)), _f_int),
                     ("Empates técnicos", int(_res.get("empates", 0)), _f_int),
                     ("% de casos favoráveis à aplicação", float(_res.get("pct_app_superior", 0.0)), _f_pct),
                     ("% de casos favoráveis à referência", float(_res.get("pct_ref_superior", 0.0)), _f_pct)]
            _r = 4
            for _lbl, _v, _fmt in _kpis:
                _ws.write(_r, 0, _lbl, _f_lbl)
                _ws.write_number(_r, 1, _v, _fmt)
                _r += 1
            _r += 1
            _ws.write(_r, 0, "Insights automáticos (baseados nos dados)", _f_sub); _r += 1
            for _x in (_ins or ["—"]):
                _ws.merge_range(_r, 0, _r, 5, "• " + str(_x).replace("**", ""), _f_txt)
                _ws.set_row(_r, 30); _r += 1
            _r += 1
            _ws.write(_r, 0, "Recomendações automáticas", _f_sub); _r += 1
            for _x in (_recs or ["—"]):
                _ws.merge_range(_r, 0, _r, 5, "• " + str(_x).replace("**", ""), _f_txt)
                _ws.set_row(_r, 30); _r += 1
        except Exception:
            pass

        # ============ ABA 2: DIVERGÊNCIAS (tabela rica) ============
        try:
            if _analises:
                _ws = _wb.add_worksheet("Diag - Divergencias")
                _cols = ["Município", "UF", "Inscritos", "Destino Aplicação", "Destino Referência",
                         "Distância Aplicação (km)", "Distância Referência (km)", "Diferença (km)", "Diferença (%)",
                         "Diferença Tempo (min)", "Balsa Aplicação", "Balsa Referência", "Acesso Aplicação",
                         "Acesso Referência", "Sinuosidade Aplicação (V/R)", "Sinuosidade Referência (V/R)",
                         "Motor Aplicação", "Motor Referência", "Divergência Motores (%)", "Categoria",
                         "Índice Qualidade Aplicação", "Índice Qualidade Referência", "Vencedor (Qualidade)"]
                _larg = [22, 5, 9, 20, 20, 14, 14, 11, 11, 12, 10, 10, 16, 16, 14, 14, 12, 12, 14, 24, 12, 12, 16]
                _ordi = sorted(_analises, key=lambda a: abs((a.get("Diferença (km)") or 0.0)
                               * (int(a.get("Inscritos") or 0) or 1)), reverse=True)
                _last = _escrever_tabela(_ws, 0, _cols, _ordi, _larg)
                _ws.freeze_panes(1, 1)
                _ws.autofilter(0, 0, _last, len(_cols) - 1)
                _explicacao(_ws, _last + 2, len(_cols),
                            "Como ler: cada linha é um município onde os dois estudos escolheram locais de prova "
                            "diferentes, ordenado por IMPACTO (diferença de km × candidatos). 'Diferença (km)' > 0 "
                            "significa que a aplicação ficou mais distante; < 0, que ficou mais curta. 'Índice de "
                            "Qualidade' (0–100) pondera distância, tempo, acessibilidade, robustez, confiabilidade e "
                            "risco operacional — por isso o 'Vencedor (Qualidade)' pode diferir de quem tem a menor "
                            "distância pura (ex.: uma rota 5 km maior, mas sem balsa, pode ser preferível). 'V/R' é a "
                            "razão viário/linha-reta (quanto maior, mais sinuoso/indireto). 'Divergência Motores (%)' "
                            "alta sugere malhas cartográficas distintas entre os motores — candidata a auditoria.", 150)
        except Exception:
            pass

        # ============ ABA 3: PARECERES & HIPÓTESES ============
        try:
            if _analises:
                _ws = _wb.add_worksheet("Diag - Pareceres")
                _ws.set_column("A:A", 22); _ws.set_column("B:B", 6); _ws.set_column("C:C", 26)
                _ws.set_column("D:D", 16); _ws.set_column("E:E", 70); _ws.set_column("F:F", 60); _ws.set_column("G:G", 55)
                _cols = ["Município", "UF", "Categoria", "Vencedor (Qualidade)", "Parecer Técnico",
                         "Hipóteses", "Recomendação"]
                for _c, _nome in enumerate(_cols):
                    _ws.write(0, _c, _nome, _f_hdr)
                _ordi = sorted(_analises, key=lambda a: abs((a.get("Diferença (km)") or 0.0)
                               * (int(a.get("Inscritos") or 0) or 1)), reverse=True)
                _rr = 0
                for a in _ordi:
                    _rr += 1
                    _ws.write(_rr, 0, str(a.get("Município", "—")), _f_lbl)
                    _ws.write(_rr, 1, str(a.get("UF", "—")), _f_lbl)
                    _ws.write(_rr, 2, str(a.get("Categoria", "—")), _f_lbl)
                    _ws.write(_rr, 3, str(a.get("Vencedor (Qualidade)", "—")), _f_lbl)
                    _ws.write(_rr, 4, str(a.get("Parecer Técnico", "—")).replace("**", ""), _f_txt)
                    _hip = a.get("Hipóteses") or []
                    _ws.write(_rr, 5, ("• " + "\n• ".join(_hip)) if _hip else "—", _f_txt)
                    _ws.write(_rr, 6, str(a.get("Recomendação", "—")).replace("**", ""), _f_txt)
                    _ws.set_row(_rr, 90)
                _ws.freeze_panes(1, 1)
                _explicacao(_ws, _rr + 2, len(_cols),
                            "Esta aba é a AUDITORIA das decisões: para cada divergência, um parecer técnico explica em "
                            "linguagem clara por que aquela escolha é melhor ou pior para o candidato e para a operação; "
                            "as 'Hipóteses' listam as causas técnicas prováveis (malha viária, cartografia, balsa, "
                            "penalização multicritério, geocodificação); e a 'Recomendação' indica a ação concreta "
                            "(manter, revisar manualmente, auditar a rota, recalibrar critério).", 90)
        except Exception:
            pass

        # ============ ABA 4: RANKING DAS CAUSAS (com gráfico) ============
        try:
            if _rank:
                _ws = _wb.add_worksheet("Diag - Ranking Causas")
                _ws.set_column("A:A", 40); _ws.set_column("B:C", 14)
                _ws.write("A1", "Ranking dos fatores determinantes", _f_tit)
                _r0 = 3
                _last = _escrever_tabela(_ws, _r0, ["Causa", "Casos", "Inscritos"], _rank, [40, 12, 14])
                _n_itens = len(_rank)
                _ch = _wb.add_chart({"type": "bar"})
                _ch.add_series({"name": "Candidatos impactados",
                                "categories": ["Diag - Ranking Causas", _r0 + 1, 0, _last, 0],
                                "values": ["Diag - Ranking Causas", _r0 + 1, 2, _last, 2],
                                "fill": {"color": "#2563eb"}})
                _ch.set_title({"name": "Causas das divergências (por candidatos impactados)"})
                _ch.set_legend({"none": True})
                _ch.set_size({"width": 720, "height": max(240, 40 + 26 * _n_itens)})
                _ws.insert_chart(_last + 3, 0, _ch)
                _explicacao(_ws, _last + 3 + max(14, _n_itens + 2), 3,
                            "Como ler: o ranking mostra QUAIS naturezas de divergência concentram mais candidatos. "
                            "Priorize as causas do topo — são onde a revisão rende mais. 'Casos' é a contagem de "
                            "municípios; 'Inscritos' pondera pelo tamanho da demanda afetada.", 60)
        except Exception:
            pass

        # ============ ABA 5: OPORTUNIDADES ============
        try:
            if _opp:
                _ws = _wb.add_worksheet("Diag - Oportunidades")
                _cols = ["Município", "UF", "Inscritos", "Ganho potencial (km)",
                         "Impacto (km × inscritos)", "Causa", "Ação"]
                _larg = [24, 6, 10, 16, 18, 26, 60]
                for _c, _nome in enumerate(_cols):
                    _ws.write(0, _c, _nome, _f_hdr); _ws.set_column(_c, _c, _larg[_c])
                _rr = 0
                for _l in _opp:
                    _rr += 1
                    _ws.write(_rr, 0, str(_l.get("Município", "—")), _f_lbl)
                    _ws.write(_rr, 1, str(_l.get("UF", "—")), _f_lbl)
                    _ws.write_number(_rr, 2, int(_l.get("Inscritos") or 0), _f_int)
                    _ws.write_number(_rr, 3, float(_l.get("Ganho potencial (km)") or 0.0), _f_num)
                    _ws.write_number(_rr, 4, float(_l.get("Impacto (km × inscritos)") or 0.0), _f_num)
                    _ws.write(_rr, 5, str(_l.get("Causa", "—")), _f_lbl)
                    _ws.write(_rr, 6, str(_l.get("Ação", "—")).replace("**", ""), _f_txt)
                    _ws.set_row(_rr, 44)
                _ws.freeze_panes(1, 1)
                _ws.autofilter(0, 0, _rr, len(_cols) - 1)
                _explicacao(_ws, _rr + 2, len(_cols),
                            "Oportunidades de melhoria = divergências desfavoráveis à aplicação, ordenadas pelo GANHO "
                            "POTENCIAL ponderado (km economizáveis × candidatos). São os casos onde revisar o polo ou "
                            "recalibrar critérios traz o maior retorno. 'Ação' sugere o próximo passo concreto para "
                            "cada município.", 64)
        except Exception:
            pass

        # ============ ABA 6: ANÁLISE DOS MOTORES ============
        try:
            _dm = _dist.get("por_motor_ref", [])
            if _dm:
                _ws = _wb.add_worksheet("Diag - Motores")
                _ws.set_column("A:A", 28); _ws.set_column("B:C", 14)
                _ws.write("A1", "Análise dos motores de roteamento", _f_tit)
                _last = _escrever_tabela(_ws, 3, ["Categoria", "Casos", "Inscritos"], _dm, [28, 12, 14])
                _explicacao(_ws, _last + 2, 3,
                            "Distribuição das divergências pelo MOTOR que produziu a rota do estudo de referência "
                            "(Google, OSRM, Valhalla, GraphHopper, linha reta). Concentração num motor pode indicar "
                            "diferença sistemática de malha/cartografia frente ao motor da aplicação — nesses casos, "
                            "conferir qual malha reflete a via real é a auditoria recomendada.", 64)
        except Exception:
            pass

        # ============ ABA 7: ANÁLISE TERRITORIAL (UF + Região, com gráfico) ============
        try:
            _du = _dist.get("por_uf", [])
            _dr = _dist.get("por_regiao", [])
            if _du or _dr:
                _ws = _wb.add_worksheet("Diag - Territorial")
                _ws.set_column("A:A", 22); _ws.set_column("B:C", 14)
                _ws.write("A1", "Análise territorial das divergências", _f_tit)
                _r0 = 3
                _last_u = _r0
                if _du:
                    _ws.write(_r0 - 1, 0, "Por UF", _f_sub)
                    _last_u = _escrever_tabela(_ws, _r0, ["Categoria", "Casos", "Inscritos"], _du, [22, 12, 14])
                    _ch = _wb.add_chart({"type": "bar"})
                    _ch.add_series({"name": "Candidatos por UF",
                                    "categories": ["Diag - Territorial", _r0 + 1, 0, _last_u, 0],
                                    "values": ["Diag - Territorial", _r0 + 1, 2, _last_u, 2],
                                    "fill": {"color": "#16a34a"}})
                    _ch.set_title({"name": "Divergências por UF (candidatos)"})
                    _ch.set_legend({"none": True})
                    _ch.set_size({"width": 640, "height": max(240, 40 + 24 * len(_du))})
                    _ws.insert_chart(_r0, 5, _ch)
                if _dr:
                    _r1 = _last_u + 3
                    _ws.write(_r1 - 1, 0, "Por região", _f_sub)
                    _last_r = _escrever_tabela(_ws, _r1, ["Categoria", "Casos", "Inscritos"], _dr, [22, 12, 14])
                    _explicacao(_ws, _last_r + 2, 3,
                                "Onde as divergências se concentram no território. Concentração regional costuma "
                                "revelar padrões físicos (ex.: acesso fluvial e balsas na região Norte, malha densa no "
                                "Sudeste). Cruze com as abas Operacional e Motores para entender a causa dominante em "
                                "cada recorte.", 56)
        except Exception:
            pass

        # ============ ABA 8: ANÁLISE OPERACIONAL (acesso + balsa + vencedor) ============
        try:
            _da = _dist.get("por_acesso_app", [])
            _db = _dist.get("por_balsa", [])
            _dv = _dist.get("por_vencedor", [])
            if _da or _db or _dv:
                _ws = _wb.add_worksheet("Diag - Operacional")
                _ws.set_column("A:A", 30); _ws.set_column("B:C", 14)
                _ws.write("A1", "Análise operacional das divergências", _f_tit)
                _r = 3
                for _titulo, _bloco in [("Por tipo de acesso da aplicação", _da),
                                        ("Por presença de balsa", _db),
                                        ("Por vencedor (qualidade)", _dv)]:
                    if _bloco:
                        _ws.write(_r - 1, 0, _titulo, _f_sub)
                        _r = _escrever_tabela(_ws, _r, ["Categoria", "Casos", "Inscritos"], _bloco, [30, 12, 14]) + 3
                _explicacao(_ws, _r, 3,
                            "Leitura operacional: 'tipo de acesso' e 'balsa' mostram quanto das divergências envolve "
                            "modo rodoviário puro versus travessias/transporte fluvial — fatores de risco e de tempo "
                            "que o Índice de Qualidade penaliza. 'Por vencedor' resume, em candidatos, o saldo entre "
                            "as escolhas da aplicação e da referência. Divergências ligadas a balsa/fluvial são as de "
                            "maior sensibilidade operacional e merecem conferência caso a caso.", 72)
        except Exception:
            pass
        # [DIVERGENCIA-XAI-2 - 237ª] abas do aprofundamento (KPIs, derrotas, confiança, aprendizado)
        try:
            _abas_stage_a(writer, diag)
        except Exception:
            pass
        # [DIVERGENCIA-XAI-3 - 239ª] abas da auditoria avançada (KPIs extremos, motores, precisão, faixas, árvore)
        try:
            _abas_stage_b(writer, diag)
        except Exception:
            pass
        try:
            _abas_telemetria(writer, diag)
        except Exception:
            pass
        try:
            _abas_laudo(writer, diag)
        except Exception:
            pass
    except Exception:
        return


# ==============================================================================
# [DIVERGENCIA-XAI - 236ª] ORQUESTRADOR DE REDE — reprocessa as rotas divergentes
# ==============================================================================
def _rp_para_dict(rp):
    """[DIVERGENCIA-XAI - 236ª] Converte um RotaPipeline (resultado do roteamento fresco do lado da
    REFERÊNCIA) no dict `campos` que _fatos_rota_divergencia consome. Lê SEMPRE por NOME (getattr), nunca
    por índice — robusto à evolução do NamedTuple. Defensivo a None."""
    if rp is None:
        return {}
    def _g(nome, padrao=None):
        try:
            return getattr(rp, nome)
        except Exception:
            return padrao
    return {
        "destino": _g("municipio_destino") or "",
        "distancia_km": _g("distancia"),
        "linha_reta_km": _g("dist_linha_reta"),
        "balsa": _g("balsas", ""),
        "fonte_rota": _g("fonte_rota", ""),
        "tempo": _g("tempo", ""),
        "score": _g("score_rota"),
        "lat_origem": _g("lat_origem"), "lon_origem": _g("lon_origem"),
        "lat_destino": _g("lat_destino"), "lon_destino": _g("lon_destino"),
    }


def _fatos_from_linha_app(linha):
    """[DIVERGENCIA-XAI - 236ª] Extrai os FATOS do lado da APLICAÇÃO a partir da linha de conciliação, usando
    os valores JÁ ARMAZENADOS no estudo (a decisão real que a aplicação tomou — não re-roteia). Mapeia as
    chaves ricas 'APP · …' que _conciliar_comparativo anexa. PURO."""
    _campos = {
        "destino": linha.get("Destino Aplicacao"),
        "uf_destino": linha.get("APP · UF do Polo"),
        "cod_ibge_destino": linha.get("APP · Cód IBGE do Polo"),
        "distancia_km": linha.get("Distancia Aplicacao"),
        "linha_reta_km": linha.get("APP · Linha Reta (km)"),
        "balsa": linha.get("Balsa Aplicacao", ""),
        "fonte_rota": linha.get("APP · Fonte da Rota", ""),
        "tempo": linha.get("Tempo Aplicacao", ""),
        "score": linha.get("APP · Score"),
        "modo_acesso": linha.get("Modo Aplicacao", ""),
        "razao_vr": linha.get("Sinuosidade Aplicacao"),
        "coord_origem": linha.get("APP · Coordenadas da Origem"),
        "coord_destino": linha.get("APP · Coordenadas do Polo"),
    }
    return _fatos_rota_divergencia(_campos)


def _montar_destino_ref(linha):
    """Monta a string de destino da REFERÊNCIA para o roteamento, com melhor esforço de desambiguação de UF.
    Retorna (destino_str, uf_assumida_bool). Limitação honesta: o estudo de referência nem sempre informa a
    UF do polo — quando não informa, herda-se a UF da ORIGEM (exames são majoritariamente intraestaduais),
    sinalizando a suposição. Homônimos entre UFs distintas continuam sendo um risco a auditar."""
    _dest = str(linha.get("Destino Referencia") or "").strip()
    if not _dest:
        return "", False
    if "," in _dest or "-" in _dest:  # já parece conter UF/qualificador
        return _dest, False
    # tenta uma coluna REF · … que contenha a UF do polo da referência
    for _k, _v in linha.items():
        if isinstance(_k, str) and _k.startswith("REF · ") and "uf" in _k.lower() and str(_v).strip():
            _uf = str(_v).strip().upper()[:2]
            if len(_uf) == 2 and _uf.isalpha():
                return f"{_dest}, {_uf}", False
    _uf_orig = str(linha.get("UF") or "").strip().upper()[:2]
    if len(_uf_orig) == 2 and _uf_orig.isalpha():
        return f"{_dest}, {_uf_orig}", True  # UF assumida = a da origem
    return _dest, False


def _reprocessar_rotas_divergentes(linhas, limiar_empate_km=1.0, cb_progresso=None,
                                   router=None, uf_para_regiao=None):
    """[DIVERGENCIA-XAI - 236ª] ORQUESTRADOR. Para cada município cujo destino difere entre a aplicação e a
    referência, ROTEIA origem→destino_ref pelos MESMOS motores (via calcular_pipeline_logistico, com cache
    L1/L2), caracterizando a escolha da referência com os mesmos sinais ricos que a aplicação já possui;
    então analisa a divergência e agrega tudo em INTELIGÊNCIA (resumo, insights, ranking, distribuições,
    oportunidades, recomendações) + a lista de análises por município.

    Parâmetros:
      linhas             : as linhas de conciliação (saída de _conciliar_comparativo/_comparar_alocacoes).
      limiar_empate_km   : abaixo desse |Δkm| a divergência é 'empate técnico' (ruído entre fontes).
      cb_progresso       : callback opcional cb(i, total, rotulo) para barra de progresso na UI.
      router             : SEAM de teste — injeta um roteador; em produção usa calcular_pipeline_logistico.
      uf_para_regiao     : injetável; default _UF_PARA_REGIAO.

    Retorna o dict `diag` pronto para _diagnostico_divergencias_html / _abas_diagnostico_divergencias /
    _painel_divergencias_ui: agregado + {'analises': [...], 'uf_ref_assumida': N, 'falhas_roteamento': N}.
    DEFENSIVO: cada rota isolada em try; falha de uma não derruba o lote. Rede só aqui, na borda."""
    _router = router if router is not None else globals().get("calcular_pipeline_logistico")
    # [TELEMETRIA-API - 241ª] zera a telemetria para refletir SÓ o roteamento deste diagnóstico (latência por run).
    try:
        _TELEMETRIA.reset()
    except Exception:
        # [OBS-R2 275ª] antes: 'pass' silencioso. Se o reset falha, a latência do diagnóstico sai
        # poluída com dados de uma execução anterior — sem ninguém saber. Fluxo inalterado; só rastreável.
        logger.debug("[OBS] Falha ao resetar _TELEMETRIA no diagnostico de divergencias (isolada).", exc_info=True)
    _divergentes = [l for l in (linhas or []) if l.get("Mesmo Destino") == "Não"
                    and str(l.get("Destino Referencia") or "").strip()
                    and str(l.get("Destino Aplicacao") or "").strip()]
    _total = len(_divergentes)
    _analises, _uf_assumida, _falhas = [], 0, 0

    for _i, _l in enumerate(_divergentes):
        _origem = str(_l.get("Origem") or "").strip()
        _uf = str(_l.get("UF") or "").strip()
        _origem_q = f"{_origem}, {_uf}" if (_uf and "," not in _origem) else _origem
        _destino_ref, _assumida = _montar_destino_ref(_l)
        if _assumida:
            _uf_assumida += 1
        if cb_progresso:
            try:
                cb_progresso(_i + 1, _total, f"{_origem} → {_l.get('Destino Referencia')}")
            except Exception:
                pass
        # ---- lado REF: roteia fresco (a única operação de rede) ----
        _fatos_ref = None
        try:
            if _router and _origem_q and _destino_ref:
                # [TELEMETRIA-API - 240ª] mede a latência do roteamento da referência (núcleo de rota intacto).
                _t0_rt = time.perf_counter()
                _rp = _router(_origem_q, _destino_ref)
                try:
                    _TELEMETRIA.registrar(getattr(_rp, "fonte_rota", ""), time.perf_counter() - _t0_rt,
                                          sucesso=(getattr(_rp, "distancia", None) is not None))
                except Exception:
                    # [OBS-R2 275ª] antes: 'pass'. Falha aqui = latência da rota some do painel sem aviso.
                    logger.debug("[OBS] Falha ao registrar latencia de rota em _TELEMETRIA (isolada).", exc_info=True)
                _campos_ref = _rp_para_dict(_rp)
                # o nome do destino da referência prevalece sobre o resolvido pelo geocoder
                _campos_ref["destino"] = str(_l.get("Destino Referencia") or _campos_ref.get("destino") or "")
                _fatos_ref = _fatos_rota_divergencia(_campos_ref)
        except Exception:
            _fatos_ref = None
        if _fatos_ref is None:
            # fallback honesto: usa a distância da referência já presente na linha (sem sinais ricos)
            _falhas += 1
            _fatos_ref = _fatos_rota_divergencia({
                "destino": _l.get("Destino Referencia"),
                "distancia_km": _l.get("Distancia Referencia"),
                "tempo": _l.get("Tempo Referencia"),
                "fonte_rota": "", "balsa": "",
            })
        # ---- lado APP: valores já armazenados (decisão real) ----
        try:
            _fatos_app = _fatos_from_linha_app(_l)
        except Exception:
            _fatos_app = _fatos_rota_divergencia({"destino": _l.get("Destino Aplicacao"),
                                                  "distancia_km": _l.get("Distancia Aplicacao")})
        # ---- análise da divergência ----
        try:
            _analises.append(_analisar_divergencia_par(_l, _fatos_app, _fatos_ref, limiar_empate_km))
        except Exception:
            continue

    _ag = _agregar_diagnostico_divergencias(_analises, uf_para_regiao=uf_para_regiao)
    _diag = dict(_ag)
    _diag["analises"] = _analises
    _diag["uf_ref_assumida"] = _uf_assumida
    _diag["falhas_roteamento"] = _falhas
    _diag["total_divergentes"] = _total
    # [DIVERGENCIA-XAI-2 - 237ª] enriquece com confiança, classificação de derrotas, aprendizado e KPIs.
    try:
        _montar_stage_a(_diag, uf_para_regiao=uf_para_regiao)
    except Exception:
        pass
    # [DIVERGENCIA-XAI-3 - 239ª] enriquece com auditoria avançada (KPIs extremos, recortes, motivo, árvore).
    try:
        _montar_stage_b(_diag)
    except Exception:
        pass
    # [TELEMETRIA-API - 240ª] enriquece com telemetria por motor (precisão real + latência acumulada).
    try:
        _montar_telemetria(_diag)
    except Exception:
        pass
    try:
        _montar_laudo(_diag)
    except Exception:
        pass
    return _diag


def _resumo_pos_diagnostico_divergencias(diag):
    """[POS-DIAGNOSTICO - 256ª geração] Depois que o usuário PROCESSA as rotas divergentes, o diagnóstico
    roteia de novo (fresco) a escolha da referência e sabe coisas que o placar do topo (calculado sobre os
    dados ORIGINAIS) não reflete. Esta função consolida o que o reprocessamento REVELOU num resumo curto e
    acionável — a ponte entre "o que a tela mostrava" e "o que agora sabemos".

    Lê apenas o dict `diag` já produzido por _reprocessar_rotas_divergentes (não roteia nada, não faz rede).
    Retorna um dict com:
      - linhas: lista de frases (strings, podem conter markdown/negrito) resumindo o veredito pós-rota
      - kpis: lista de (rotulo, valor, ajuda) para st.metric
      - houve_ajuste: bool — se o roteamento fresco mudou algum vencedor vs. a distância original do estudo
    PURA e defensiva: diag inválido/vazio → dict com listas vazias e houve_ajuste=False.
    """
    vazio = {"linhas": [], "kpis": [], "houve_ajuste": False}
    try:
        if not diag or not isinstance(diag, dict):
            return vazio
        _n_div = int(diag.get("n_divergencias", 0) or 0)
        if _n_div <= 0:
            return vazio
        _res = diag.get("resumo", {}) or {}
        _analises = diag.get("analises", []) or []
        _falhas = int(diag.get("falhas_roteamento", 0) or 0)
        _roteadas = max(0, _n_div - _falhas)

        _app = int(_res.get("app_superior", 0) or 0)
        _ref = int(_res.get("ref_superior", 0) or 0)
        _emp = int(_res.get("empates", 0) or 0)
        _ins_perda = int(_res.get("inscritos_em_perda", 0) or 0)
        _ins_benef = int(_res.get("inscritos_beneficiados_app", 0) or 0)

        def _br(x, casas=0):
            try:
                s = f"{float(x):,.{casas}f}"
                return s.replace(",", "§").replace(".", ",").replace("§", ".")
            except Exception:
                return "—"

        # Soma da diferença de km fresca (referência − aplicação) ponderada e simples, a partir das análises.
        _sum_dif = 0.0        # km: positivo = a referência roda MAIS que a aplicação (aplicação melhor)
        _sum_impacto = 0.0    # km × inscritos
        _n_ref_vence_rota = 0  # em quantas a referência é mais curta na rota fresca
        for _a in _analises:
            if not isinstance(_a, dict):
                continue
            try:
                _dif = _a.get("Diferença (km)", None)
                if _dif is not None:
                    _sum_dif += float(_dif)
            except (TypeError, ValueError):
                pass
            try:
                _imp = _a.get("Impacto (km × inscritos)", None)
                if _imp is not None:
                    _sum_impacto += float(_imp)
            except (TypeError, ValueError):
                pass
            try:
                _da = _a.get("Distância Aplicação (km)", None)
                _dr = _a.get("Distância Referência (km)", None)
                if _da is not None and _dr is not None and float(_dr) < float(_da):
                    _n_ref_vence_rota += 1
            except (TypeError, ValueError):
                pass

        houve_ajuste = _ref > 0 or _n_ref_vence_rota > 0

        # ---- KPIs de reconciliação ----
        kpis = []
        kpis.append(("Divergências roteadas de novo",
                     f"{_br(_roteadas)}" + (f" de {_br(_n_div)}" if _falhas else ""),
                     "Municípios divergentes cuja rota da referência foi recalculada agora, com os mesmos motores."))
        kpis.append(("Confirmadas a favor da aplicação", f"{_br(_app)}",
                     "Após rotear de novo, o Índice de Qualidade multicritério ainda favorece a aplicação."))
        kpis.append(("Onde a referência é melhor", f"{_br(_ref)}",
                     "Casos que o reprocessamento mostrou serem genuinamente melhores na referência — candidatos a adotar."))
        if _ins_perda > 0:
            kpis.append(("Candidatos em rota pior", f"{_br(_ins_perda)}",
                         "Inscritos nos municípios onde a referência oferece deslocamento menor."))

        # ---- narrativa curta ----
        linhas = []
        if _roteadas > 0:
            _txt = (f"Reroteei **{_br(_roteadas)}** das **{_br(_n_div)}** divergências com os mesmos motores. ")
            if _ref == 0:
                _txt += ("Nenhuma se sustentou como vantagem real da referência — **o placar do topo se "
                         "confirma** e a aplicação segue melhor ou empatada em todos os casos divergentes.")
            else:
                _txt += (f"Destas, **{_br(_ref)}** se confirmaram como genuinamente melhores na referência "
                         f"(afetando **{_br(_ins_perda)}** candidatos), **{_br(_app)}** seguem a favor da "
                         f"aplicação e **{_br(_emp)}** empataram. **É aqui que o placar do topo merece um "
                         f"ajuste fino**: adotar essas {_br(_ref)} escolhas encurta o deslocamento desses candidatos.")
            linhas.append(_txt)

        if _sum_impacto and abs(_sum_impacto) > 0:
            if _sum_dif > 0:
                linhas.append(f"No agregado das rotas frescas, a aplicação economiza **{_br(abs(_sum_dif),1)} km** "
                              f"em relação à referência (impacto ponderado de **{_br(abs(_sum_impacto))} km×candidato**) "
                              "— ou seja, trocar tudo para a referência PIORARIA o total.")
            elif _sum_dif < 0:
                linhas.append(f"No agregado das rotas frescas, a referência seria **{_br(abs(_sum_dif),1)} km** mais "
                              f"curta na soma dos municípios divergentes (impacto de **{_br(abs(_sum_impacto))} "
                              "km×candidato**) — vale revisar o plano híbrido para capturar esse ganho onde ela vence.")

        if _falhas > 0:
            linhas.append(f"Ressalva honesta: **{_br(_falhas)}** rota(s) não obtiveram roteamento fresco "
                          "(usei a distância que já constava do estudo nesses casos), então os números acima "
                          "são um piso conservador.")

        return {"linhas": linhas, "kpis": kpis, "houve_ajuste": houve_ajuste}
    except Exception:
        return vazio



# ==============================================================================
# [DIVERGENCIA-XAI - 236ª] PAINEL STREAMLIT — Diagnóstico Inteligente das Divergências
# ==============================================================================
def _painel_divergencias_ui(diag, st):
    """[DIVERGENCIA-XAI - 236ª] Renderiza os painéis interativos do diagnóstico na aba Comparador. Recebe `st`
    EXPLICITAMENTE (sem depender de global — decisão deliberada). DEFENSIVO: diag vazio → aviso curto; tudo
    isolado em try. Usa os idiomas nativos do app (st.metric/st.bar_chart/st.dataframe/st.expander)."""
    try:
        import pandas as pd
    except Exception:
        pd = None
    try:
        if not diag or not diag.get("n_divergencias"):
            st.caption("Nenhuma divergência de destino para diagnosticar.")
            return
        _res = diag.get("resumo", {}) or {}
        _analises = diag.get("analises", []) or []
        _dist = diag.get("distribuicoes", {}) or {}
        _ins = diag.get("insights", []) or []
        _recs = diag.get("recomendacoes", []) or []
        _rank = diag.get("ranking_causas", []) or []
        _opp = diag.get("oportunidades", []) or []

        st.markdown("### 🔬 Diagnóstico Inteligente das Divergências")
        st.caption("Para cada município em que os dois estudos escolheram locais de prova diferentes, roteamos "
                   "a escolha da referência pelos mesmos motores e explicamos, por evidência, por que cada "
                   "opção é melhor ou pior para o candidato e para a operação.")

        # ---- KPIs ----
        _c = st.columns(5)
        _c[0].metric("Divergências", f"{diag.get('n_divergencias', 0):,}".replace(",", "."))
        _c[1].metric("Candidatos impactados", f"{int(_res.get('inscritos_impactados', 0)):,}".replace(",", "."))
        _c[2].metric("Vence a aplicação", f"{int(_res.get('app_superior', 0))}",
                     help="Casos em que o Índice de Qualidade multicritério favorece a aplicação.")
        _c[3].metric("Vence a referência", f"{int(_res.get('ref_superior', 0))}")
        _c[4].metric("Empates técnicos", f"{int(_res.get('empates', 0))}")

        # [CARTOES-DIVERGENCIA - 244ª] resumo visual escaneável no topo (antes do conteúdo denso)
        try:
            _painel_cartoes(diag, st)
        except Exception:
            pass

        # ---- ressalvas honestas ----
        _assum = int(diag.get("uf_ref_assumida", 0) or 0)
        _falhas = int(diag.get("falhas_roteamento", 0) or 0)
        if _assum or _falhas:
            _msgs = []
            if _assum:
                _msgs.append(f"em **{_assum}** caso(s) a UF do polo da referência não veio informada e foi "
                             f"assumida a UF da origem (exames tendem a ser intraestaduais) — homônimos entre "
                             f"UFs continuam sendo um risco a auditar")
            if _falhas:
                _msgs.append(f"em **{_falhas}** caso(s) o roteamento fresco do lado da referência falhou; "
                             f"usamos a distância que já constava do estudo (sem os sinais ricos de balsa/motor)")
            st.info("ℹ️ Transparência metodológica: " + "; ".join(_msgs) + ".")

        # ---- resumo executivo ----
        _pa = _res.get("pct_app_superior", 0.0)
        _pr = _res.get("pct_ref_superior", 0.0)
        st.markdown(
            f"**Resumo:** avaliando cada escolha por um Índice de Qualidade multicritério (distância, tempo, "
            f"acessibilidade, robustez, confiabilidade e risco operacional), a **aplicação** foi superior em "
            f"**{_pa:.0f}%** dos casos e a **referência** em **{_pr:.0f}%**.")

        # ---- insights + recomendações ----
        if _ins:
            with st.container(border=True):
                st.markdown("**🔎 Insights automáticos**")
                for _x in _ins:
                    st.markdown("- " + str(_x))
        if _recs:
            with st.container(border=True):
                st.markdown("**✅ Recomendações automáticas**")
                for _x in _recs:
                    st.markdown("- " + str(_x))

        # ---- distribuições (bar charts nativos) ----
        def _bar(_titulo, _chave, _label_col="Categoria"):
            _d = _dist.get(_chave, [])
            if not _d:
                return
            st.markdown(f"**{_titulo}**")
            if pd is not None:
                _df = pd.DataFrame(_d)
                if _label_col in _df.columns and "Inscritos" in _df.columns:
                    st.bar_chart(_df.set_index(_label_col)["Inscritos"])
                    return
            # fallback textual
            for _x in _d[:10]:
                st.write(f"- {_x.get('Categoria','—')}: {int(_x.get('Inscritos') or 0):,} candidatos "
                         f"({_x.get('Casos',0)} casos)".replace(",", "."))

        _tabs = st.tabs(["Por UF", "Por região", "Por vencedor", "Por acesso", "Por balsa", "Por motor (ref)"])
        with _tabs[0]:
            _bar("Divergências por UF (candidatos impactados)", "por_uf")
        with _tabs[1]:
            _bar("Divergências por região (candidatos impactados)", "por_regiao")
        with _tabs[2]:
            _bar("Saldo por vencedor (candidatos)", "por_vencedor")
        with _tabs[3]:
            _bar("Por tipo de acesso da aplicação (candidatos)", "por_acesso_app")
        with _tabs[4]:
            _bar("Por presença de balsa (candidatos)", "por_balsa")
        with _tabs[5]:
            _bar("Por motor de roteamento da referência (candidatos)", "por_motor_ref")

        # ---- ranking das causas ----
        if _rank and pd is not None:
            st.markdown("**🏆 Ranking dos fatores determinantes**")
            st.dataframe(pd.DataFrame(_rank)[["Causa", "Casos", "Inscritos"]],
                         use_container_width=True, hide_index=True)

        # ---- oportunidades de melhoria ----
        if _opp and pd is not None:
            st.markdown("**🎯 Oportunidades de melhoria (maior ganho potencial ponderado)**")
            _dfo = pd.DataFrame(_opp)
            _cols = [c for c in ["Município", "UF", "Inscritos", "Ganho potencial (km)",
                                 "Impacto (km × inscritos)", "Causa"] if c in _dfo.columns]
            st.dataframe(_dfo[_cols].head(20), use_container_width=True, hide_index=True)

        # [DIVERGENCIA-XAI-2 - 237ª] seções do aprofundamento (KPIs, derrotas classificadas, aprendizado)
        try:
            _painel_stage_a(diag, st, pd)
        except Exception:
            pass
        # [DIVERGENCIA-XAI-3 - 239ª] seções da auditoria avançada (extremos, motores, precisão, faixas, árvores)
        try:
            _painel_stage_b(diag, st, pd)
        except Exception:
            pass
        try:
            _painel_telemetria(diag, st, pd)
        except Exception:
            pass
        try:
            _painel_laudo(diag, st, pd)
        except Exception:
            pass

        # ---- pareceres técnicos (expanders por caso, top impacto) ----
        st.markdown("**📝 Pareceres técnicos — casos de maior impacto**")
        _ordi = sorted(_analises, key=lambda a: abs((a.get("Diferença (km)") or 0.0)
                       * (int(a.get("Inscritos") or 0) or 1)), reverse=True)[:25]
        for a in _ordi:
            _mun = f"{a.get('Município','—')}/{a.get('UF','—')}"
            _venc = a.get("Vencedor (Qualidade)", "—")
            _dk = a.get("Diferença (km)")
            _resumo_exp = f"{_mun} · {a.get('Categoria','—')} · vantagem: {_venc}"
            with st.expander(_resumo_exp):
                _cc = st.columns(3)
                _cc[0].metric("Δ distância (km)", f"{_dk:+.1f}" if isinstance(_dk, (int, float)) else "—")
                _cc[1].metric("IQ aplicação", f"{a.get('Índice Qualidade Aplicação','—')}")
                _cc[2].metric("IQ referência", f"{a.get('Índice Qualidade Referência','—')}")
                st.markdown(a.get("Parecer Técnico", "—"))
                _hip = a.get("Hipóteses") or []
                if _hip:
                    st.markdown("**Hipóteses técnicas:**")
                    for _h in _hip:
                        st.markdown("- " + str(_h))
                if a.get("Recomendação"):
                    st.markdown(f"**Recomendação:** {a.get('Recomendação')}")
    except Exception as _e:
        try:
            st.warning(f"Não foi possível renderizar o painel de diagnóstico: {_e}")
        except Exception:
            pass
# <<< [DIVERGENCIA-XAI 236ª] FIM do bloco inserido >>>




# <<< [DIVERGENCIA-XAI-2 237ª] INÍCIO — aprofundamento (confiança, classificação de derrotas, aprendizado, KPIs) >>>
# ==============================================================================
# [DIVERGENCIA-XAI-2 - 237ª geração] APROFUNDAMENTO DA ANÁLISE DE DIVERGÊNCIAS
# ------------------------------------------------------------------------------
# Extensão PURA e testável sobre o motor da 236ª. Opera sobre os dicts `analise`
# produzidos por _analisar_divergencia_par. Fundamentado na assinatura empírica
# das derrotas reais (Divergências.xlsx, 204 casos): as derrotas EVITÁVEIS têm
# V/R (viário/linha-reta) alta na escolha da app — geometria "mente" sobre a
# estrada. As demais são ruído de geocodificação (quase-empates).
# Entrega: Índice de Confiança (11), classificação de derrotas (12), aprendizado
# com derrotas (13), decomposição honesta da diferença (1/10) e novos KPIs (15).
# ==============================================================================

# Limiares empíricos (derivados de Divergências.xlsx). Ajustáveis num único lugar.
_VR_INDIRETA = 1.40    # acima disto a rota já é sensivelmente indireta
_VR_SEVERA = 2.00      # acima disto é descasamento geometria×estrada grave (alvo do resgate)
_UF_AMAZONIA_XAI = frozenset({"AC", "AP", "AM", "MA", "MT", "PA", "RO", "RR", "TO"})


def _num2(v, padrao=None):
    try:
        if v is None or (isinstance(v, float) and v != v):
            return padrao
        return float(v)
    except (TypeError, ValueError):
        return padrao


def _indice_confianca_escolha(analise, lado="app"):
    """[DIVERGENCIA-XAI-2 - 237ª] ÍNDICE DE CONFIANÇA DA ESCOLHA (0-100) de UMA solução (lado 'app' ou 'ref').
    Distinto do Índice de QUALIDADE (que compara quem é melhor): aqui medimos QUANTO CONFIAR na medição/rota
    daquela escolha, compondo dezenas de sinais em fatores. PURO e defensivo.

    Fatores (cada um 0-100, depois ponderados):
      • coerência viário×reta (V/R): quanto menor a razão, mais confiável a medição (rota direta).
      • consenso entre motores: menor divergência entre motores → maior confiança.
      • estabilidade da rota: rota roteada (não geodésica) e não-fluvial → maior confiança.
      • ausência de balsa: travessia depende de horário/clima/capacidade → reduz confiança operacional.
      • robustez logística: reaproveita o componente de robustez do Índice de Qualidade já calculado.
    Retorna dict {valor, faixa, componentes, fatores}."""
    _suf = "Aplicação" if lado == "app" else "Referência"
    _vr = _num2(analise.get(f"Sinuosidade {_suf} (V/R)"))
    _divm = _num2(analise.get("Divergência Motores (%)"))
    _balsa = str(analise.get(f"Balsa {_suf}") or "").strip().lower() == "sim"
    _acesso = str(analise.get(f"Acesso {_suf}") or "").lower()
    _fluvial = ("fluvial" in _acesso) or ("isolado" in _acesso) or ("aquav" in _acesso)
    _iq = analise.get("_iq_app" if lado == "app" else "_iq_ref") or {}

    # fator 1: coerência V/R (1.0 → 100; 1.4 → ~78; 2.0 → ~50; 3.0 → ~25; ≥5 → ~5)
    if _vr is None or _vr <= 0:
        _f_vr = 60.0  # desconhecido → neutro-baixo
    else:
        _excesso = max(0.0, _vr - 1.0)
        _f_vr = max(5.0, 100.0 / (1.0 + 1.15 * _excesso))
    # fator 2: consenso entre motores (0% div → 100; 30% → ~55; ≥60% → ~10)
    if _divm is None:
        _f_mot = 70.0
    else:
        _f_mot = max(10.0, 100.0 - 1.5 * _divm)
    # fator 3: estabilidade (roteada e não-fluvial)
    _f_est = 100.0
    if _fluvial:
        _f_est = 30.0
    # fator 4: ausência de balsa
    _f_balsa = 55.0 if _balsa else 100.0
    # fator 5: robustez do IQ (0-100) já existente
    _f_rob = _num2((_iq or {}).get("robustez"), 70.0)

    _componentes = {
        "coerencia_vr": round(_f_vr, 1),
        "consenso_motores": round(_f_mot, 1),
        "estabilidade_rota": round(_f_est, 1),
        "ausencia_balsa": round(_f_balsa, 1),
        "robustez": round(_f_rob, 1),
    }
    _peso = {"coerencia_vr": 0.30, "consenso_motores": 0.22, "estabilidade_rota": 0.20,
             "ausencia_balsa": 0.13, "robustez": 0.15}
    _valor = round(sum(_componentes[k] * _peso[k] for k in _peso), 1)
    _faixa = ("Alta" if _valor >= 75 else "Média" if _valor >= 50 else "Baixa")
    _fatores = []
    if _vr and _vr >= _VR_SEVERA:
        _fatores.append(f"rota muito indireta (V/R {_vr:.2f}×) — geometria não reflete a estrada")
    elif _vr and _vr >= _VR_INDIRETA:
        _fatores.append(f"rota sensivelmente indireta (V/R {_vr:.2f}×)")
    if _divm and _divm >= 30:
        _fatores.append(f"alta divergência entre motores ({_divm:.0f}%)")
    if _balsa:
        _fatores.append("depende de balsa (variabilidade operacional)")
    if _fluvial:
        _fatores.append("acesso fluvial/isolado (sem rota rodoviária plena)")
    if not _fatores:
        _fatores.append("medição coerente e estável")
    return {"valor": _valor, "faixa": _faixa, "componentes": _componentes, "fatores": _fatores}


def _classificar_derrota(analise):
    """[DIVERGENCIA-XAI-2 - 237ª] Classifica UMA derrota (referência superior) por NATUREZA e diz se é
    EVITÁVEL. PURO. Só faz sentido quando Vencedor (Qualidade) == 'Referência'; caso contrário retorna classe
    'não é derrota'. Categorias: evitável (algorítmica), operacional/justificável, geocodificação/ruído,
    por motor, por topologia. Fundamentado na assinatura real: V/R alta na app = candidato direto foi cortado
    antes do roteamento (evitável)."""
    if str(analise.get("Vencedor (Qualidade)")) != "Referência":
        return {"classe": "não é derrota", "evitavel": None, "subclasse": "—", "motivo": "", "como_evitar": ""}
    _vr_app = _num2(analise.get("Sinuosidade Aplicação (V/R)"))
    _vr_ref = _num2(analise.get("Sinuosidade Referência (V/R)"))
    _dif = abs(_num2(analise.get("Diferença (km)"), 0.0) or 0.0)
    _cat = str(analise.get("Categoria") or "").lower()
    _balsa_app = str(analise.get("Balsa Aplicação") or "").lower() == "sim"
    _acesso_app = str(analise.get("Acesso Aplicação") or "").lower()
    _fluvial_app = ("fluvial" in _acesso_app) or ("isolado" in _acesso_app)
    _divm = _num2(analise.get("Divergência Motores (%)"), 0.0) or 0.0

    # 1) descasamento geometria×estrada: app escolheu destino de V/R alta e bem maior que a da ref
    if _vr_app is not None and _vr_app >= _VR_SEVERA and (_vr_ref is None or _vr_app >= _vr_ref * 1.5):
        return {"classe": "Evitável — algorítmica (descasamento geometria×estrada)",
                "subclasse": "candidato direto cortado na pré-seleção por linha reta/matriz",
                "evitavel": True,
                "motivo": (f"a aplicação escolheu um destino geometricamente próximo porém rodoviariamente "
                           f"indireto (V/R {_vr_app:.2f}×). O vencedor da referência é mais direto "
                           f"(V/R {_vr_ref:.2f}× )" if _vr_ref else
                           f"a aplicação escolheu um destino de rota muito indireta (V/R {_vr_app:.2f}×)"),
                "como_evitar": ("forçar o roteamento de candidatos mais distantes por linha reta quando o líder "
                                "tem V/R alta — a geometria está enganando a pré-seleção (Etapa C).")}
    # 2) fluvial/balsa: app presa a acesso fluvial/isolado, referência achou rota rodoviária
    if _fluvial_app or _balsa_app or "balsa" in _cat or "fluvial" in _cat:
        return {"classe": "Operacional — acesso (fluvial/balsa)",
                "subclasse": "app ancorada em acesso fluvial/balsa; referência é rodoviária",
                "evitavel": True,
                "motivo": ("a rota da aplicação depende de balsa/acesso fluvial, enquanto a referência é "
                           "rodoviária plena — melhor para o candidato."),
                "como_evitar": ("tratar municípios fluviais com roteamento próprio e preferir hub rodoviário "
                                "quando existir (conecta ao roteamento fluvial postergado).")}
    # 3) sinuosidade moderada (indireta, mas não severa)
    if _vr_app is not None and _vr_app >= _VR_INDIRETA:
        return {"classe": "Evitável — sinuosidade moderada",
                "subclasse": "rota da app indireta, alternativa mais direta não avaliada",
                "evitavel": True,
                "motivo": f"a rota da aplicação é indireta (V/R {_vr_app:.2f}×) e há alternativa mais direta.",
                "como_evitar": "ampliar o shortlist quando o líder é indireto, para o motor autoritativo decidir."}
    # 4) por motor (malhas distintas)
    if _divm >= 30 or "motor" in _cat:
        return {"classe": "Por motor (malhas cartográficas distintas)",
                "subclasse": "divergência entre motores define o resultado", "evitavel": False,
                "motivo": f"alta divergência entre motores ({_divm:.0f}%) — malhas discordam da via real.",
                "como_evitar": "auditar com um segundo motor qual malha reflete a estrada real."}
    # 5) geocodificação/ruído (quase-empate)
    return {"classe": "Geocodificação/ruído (quase-empate)",
            "subclasse": "diferença dentro do ruído entre fontes de medição", "evitavel": False,
            "motivo": (f"diferença pequena ({_dif:.0f} km) atribuível a geocodificação/medição, não a "
                       f"escolha de destino diferente em essência."),
            "como_evitar": "sem ação algorítmica: é ruído entre fontes; revisar manualmente se relevante."}


def _decompor_diferenca(analise):
    """[DIVERGENCIA-XAI-2 - 237ª] Decompõe HEURISTICAMENTE a diferença de km entre app e referência em
    componentes: balsa/detour, sinuosidade (geometria×estrada), motor (malhas), geocodificação (resíduo).
    HONESTO: é uma atribuição heurística a partir dos sinais disponíveis — uma decomposição EXATA por
    trecho de estrada exigiria as geometrias das rotas (não disponíveis sem rede). PURO."""
    _dif = _num2(analise.get("Diferença (km)"), 0.0) or 0.0
    _abs = abs(_dif)
    if _abs <= 0.5:
        return {"total_km": round(_dif, 1), "componentes": [], "texto": "diferença desprezível", "heuristica": True}
    _vr_app = _num2(analise.get("Sinuosidade Aplicação (V/R)"))
    _vr_ref = _num2(analise.get("Sinuosidade Referência (V/R)"))
    _balsa_app = str(analise.get("Balsa Aplicação") or "").lower() == "sim"
    _balsa_ref = str(analise.get("Balsa Referência") or "").lower() == "sim"
    _divm = _num2(analise.get("Divergência Motores (%)"), 0.0) or 0.0

    _pesos = {}
    # sinuosidade: proporcional ao GAP de V/R entre os lados
    if _vr_app is not None and _vr_ref is not None:
        _gap = max(0.0, _vr_app - _vr_ref)
        if _gap > 0.05:
            _pesos["sinuosidade (geometria×estrada)"] = min(0.85, 0.20 + 0.35 * _gap)
    # balsa: quando só um lado tem balsa, parte do detour vem daí
    if _balsa_app != _balsa_ref:
        _pesos["balsa/travessia"] = 0.25
    # motor: proporcional à divergência entre motores
    if _divm > 5:
        _pesos["motor (malhas distintas)"] = min(0.40, _divm / 100.0)
    # normaliza; o que sobra é geocodificação/resíduo
    _soma = sum(_pesos.values())
    if _soma >= 1.0:
        _fator = 0.95 / _soma
        _pesos = {k: v * _fator for k, v in _pesos.items()}
        _soma = sum(_pesos.values())
    _pesos["geocodificação/resíduo"] = max(0.0, 1.0 - _soma)

    _comp = []
    for _k, _p in sorted(_pesos.items(), key=lambda x: -x[1]):
        if _p >= 0.02:
            _comp.append({"fator": _k, "km": round(_abs * _p, 1), "pct": round(100 * _p, 0)})
    _txt = "; ".join(f"{c['fator']}: ~{c['km']:.0f} km ({c['pct']:.0f}%)" for c in _comp)
    return {"total_km": round(_dif, 1), "componentes": _comp, "texto": _txt, "heuristica": True}


def _aprender_com_derrotas(analises, uf_para_regiao=None):
    """[DIVERGENCIA-XAI-2 - 237ª] APRENDE com o conjunto de derrotas: detecta PADRÕES data-driven e emite
    SUGESTÕES concretas de melhoria do algoritmo. PURO. Fundamentado na assinatura real (V/R alta = evitável).
    Retorna dict {n_derrotas, padroes, sugestoes_algoritmo, limiar_vr_sugerido, resumo}."""
    _derrotas = [a for a in (analises or []) if str(a.get("Vencedor (Qualidade)")) == "Referência"]
    _n = len(_derrotas)
    if _n == 0:
        return {"n_derrotas": 0, "padroes": [], "sugestoes_algoritmo": [], "limiar_vr_sugerido": None,
                "resumo": "Sem derrotas: a aplicação não perdeu nenhuma divergência por qualidade."}
    _vrs = [(_num2(a.get("Sinuosidade Aplicação (V/R)")), a) for a in _derrotas]
    _alta = [a for (v, a) in _vrs if v is not None and v >= _VR_SEVERA]
    _indireta = [a for (v, a) in _vrs if v is not None and v >= _VR_INDIRETA]
    _amaz = [a for a in _derrotas if str(a.get("UF") or "").upper() in _UF_AMAZONIA_XAI]
    _balsa = [a for a in _derrotas if str(a.get("Balsa Aplicação") or "").lower() == "sim"
              or "fluvial" in str(a.get("Acesso Aplicação") or "").lower()
              or "isolado" in str(a.get("Acesso Aplicação") or "").lower()]
    _insc_evit = sum(int(a.get("Inscritos") or 0) for a in _indireta)
    _km_evit = sum(abs(_num2(a.get("Diferença (km)"), 0.0) or 0.0) for a in _indireta)

    # UFs recorrentes
    import collections as _col
    _por_uf = _col.Counter(str(a.get("UF") or "—").upper() for a in _derrotas)
    _ufs_rec = [uf for uf, c in _por_uf.most_common() if c >= 2]

    _padroes = []
    _pct_ind = 100 * len(_indireta) // _n
    if _indireta:
        _padroes.append(f"{_pct_ind}% das derrotas ({len(_indireta)}/{_n}) ocorrem quando a aplicação escolhe "
                        f"um destino de rota INDIRETA (V/R ≥ {_VR_INDIRETA:.1f}×) — a geometria engana a "
                        f"pré-seleção e o vencedor rodoviário direto não é avaliado.")
    if _alta:
        _padroes.append(f"{len(_alta)} derrota(s) têm V/R SEVERA (≥ {_VR_SEVERA:.0f}×): descasamento grave "
                        f"geometria×estrada (litoral/lagoa/rio).")
    if _amaz:
        _padroes.append(f"{len(_amaz)}/{_n} derrotas estão na Amazônia Legal — malha esparsa e rios ampliam o "
                        f"efeito da pré-seleção por linha reta.")
    if _balsa:
        _padroes.append(f"{len(_balsa)} derrota(s) envolvem balsa/acesso fluvial na escolha da aplicação.")
    if _ufs_rec:
        _padroes.append(f"Derrotas recorrentes (≥2) nas UFs: {', '.join(_ufs_rec)}.")
    if not _padroes:
        _padroes.append("Sem padrão dominante: as derrotas são pontuais e heterogêneas.")

    # limiar V/R sugerido: menor V/R entre as derrotas evitáveis (piso de gatilho do resgate)
    _vr_evit = sorted(v for (v, a) in _vrs if v is not None and v >= _VR_INDIRETA)
    _limiar = round(_vr_evit[0] - 0.05, 2) if _vr_evit else None

    _sugestoes = []
    if _indireta:
        _insc_fmt = f"{_insc_evit:,}".replace(",", ".")
        _sugestoes.append(f"RESGATE POR CIRCUIDADE (Etapa C): quando o candidato líder tiver V/R ≥ ~{_limiar or _VR_INDIRETA:.2f}×, "
                          f"forçar o roteamento de N candidatos adicionais mais distantes por linha reta antes de "
                          f"decidir — um hub mais distante porém direto tende a vencer na estrada real. Ganho "
                          f"potencial estimado: ~{_km_evit:.0f} km em {len(_indireta)} municípios "
                          f"({_insc_fmt} candidatos).")
    if _amaz or _balsa:
        _sugestoes.append("Para municípios fluviais/insulares, não decidir por distância rodoviária pura "
                          "(rotas de milhares de km são artefato do contorno terrestre) — usar roteamento "
                          "fluvial/geodésico rotulado e preferir hub rodoviário real quando existir.")
    _sugestoes.append("Instrumentar a árvore de decisão (Etapa B) para confirmar, caso a caso, em qual portão "
                      "(contagem por reta / margem da matriz / poda por dominância) o vencedor foi descartado.")

    _resumo = (f"Das {_n} derrotas, ~{len(_indireta)} são EVITÁVEIS (assinatura de V/R alta / geometria×estrada) "
               f"e ~{_n - len(_indireta)} são ruído/operacionais. Concentração amazônica: {len(_amaz)}.")
    return {"n_derrotas": _n, "padroes": _padroes, "sugestoes_algoritmo": _sugestoes,
            "limiar_vr_sugerido": _limiar, "n_evitaveis": len(_indireta),
            "km_potencial": round(_km_evit, 1), "inscritos_evitaveis": _insc_evit, "resumo": _resumo}


def _kpis_divergencias(analises):
    """[DIVERGENCIA-XAI-2 - 237ª] Gera KPIs compostos das divergências, cada um com helper, fórmula e
    interpretação (item 15). PURO. Retorna lista de dicts prontos para UI/HTML/Excel."""
    _tot = len(analises or [])
    if _tot == 0:
        return []
    _derrotas = [a for a in analises if str(a.get("Vencedor (Qualidade)")) == "Referência"]
    _vitorias = [a for a in analises if str(a.get("Vencedor (Qualidade)")) == "Aplicação"]
    _empates = [a for a in analises if str(a.get("Vencedor (Qualidade)")) == "Empate"]
    _evit = [a for a in _derrotas if (_num2(a.get("Sinuosidade Aplicação (V/R)")) or 0) >= _VR_INDIRETA]
    _justif = [a for a in _derrotas if a not in _evit]
    _roteadas = [a for a in analises if "geod" not in str(a.get("Motor Aplicação") or "").lower()
                 and "reta" not in str(a.get("Motor Aplicação") or "").lower()]
    _consenso = [a for a in analises if (_num2(a.get("Divergência Motores (%)")) or 0) < 15]
    _robustas = [a for a in analises if (_num2(a.get("Sinuosidade Aplicação (V/R)")) or 1.0) < _VR_INDIRETA
                 and str(a.get("Balsa Aplicação") or "").lower() != "sim"]
    _km_evit = sum(abs(_num2(a.get("Diferença (km)"), 0.0) or 0.0) for a in _evit)
    _insc_evit = sum(int(a.get("Inscritos") or 0) for a in _evit)

    def _pct(n):
        return round(100.0 * n / _tot, 1)

    return [
        {"nome": "Escolhas ótimas (app venceu ou empatou)", "valor": _pct(len(_vitorias) + len(_empates)),
         "unidade": "%", "tabela": "Diag - Divergencias",
         "formula": "(vitórias + empates) ÷ total de divergências",
         "helper": "Fração das divergências em que a aplicação não perdeu por qualidade.",
         "interpretacao": "Quanto maior, mais frequentemente a escolha da app é ao menos tão boa quanto a da referência."},
        {"nome": "Taxa de derrotas evitáveis", "valor": (round(100.0 * len(_evit) / max(1, len(_derrotas)), 1) if _derrotas else 0.0),
         "unidade": "% das derrotas", "tabela": "Diag - Derrotas",
         "formula": "derrotas com V/R alta ÷ total de derrotas",
         "helper": "Derrotas com assinatura de geometria×estrada (candidato direto cortado na pré-seleção).",
         "interpretacao": "Alta = há ganho real acessível ajustando o algoritmo de escolha (Etapa C)."},
        {"nome": "Taxa de derrotas justificáveis", "valor": (round(100.0 * len(_justif) / max(1, len(_derrotas)), 1) if _derrotas else 0.0),
         "unidade": "% das derrotas", "tabela": "Diag - Derrotas",
         "formula": "derrotas por ruído/operacional ÷ total de derrotas",
         "helper": "Derrotas por geocodificação/quase-empate ou trade-off operacional legítimo.",
         "interpretacao": "Alta = a maioria das perdas não é defeito, e sim ruído entre fontes."},
        {"nome": "Ganho potencial (km)", "valor": round(_km_evit, 0), "unidade": "km",
         "tabela": "Diag - Oportunidades", "formula": "Σ |Δkm| das derrotas evitáveis",
         "helper": "Km economizáveis se as derrotas evitáveis fossem corrigidas.",
         "interpretacao": "Piso do ganho ao implementar o resgate por circuidade."},
        {"nome": "Ganho potencial ponderado", "valor": round(_insc_evit, 0), "unidade": "candidatos",
         "tabela": "Diag - Oportunidades", "formula": "Σ inscritos das derrotas evitáveis",
         "helper": "Candidatos beneficiados pela correção das derrotas evitáveis.",
         "interpretacao": "Prioriza os ajustes pelo impacto humano real."},
        {"nome": "Consenso entre motores", "valor": _pct(len(_consenso)), "unidade": "%",
         "tabela": "Diag - Motores", "formula": "divergências com |div. motores| < 15% ÷ total",
         "helper": "Fração em que os motores concordam sobre a rota.",
         "interpretacao": "Baixo = muitas rotas dependem de qual malha se usa (auditar)."},
        {"nome": "Escolhas robustas", "valor": _pct(len(_robustas)), "unidade": "%",
         "tabela": "Diag - Divergencias", "formula": "V/R < 1,4× e sem balsa ÷ total",
         "helper": "Escolhas diretas e sem dependência de travessia.",
         "interpretacao": "Alta = decisões estáveis e de baixo risco operacional."},
        {"nome": "Rotas roteadas (não geodésicas)", "valor": _pct(len(_roteadas)), "unidade": "%",
         "tabela": "Diag - Divergencias", "formula": "rotas com motor real ÷ total",
         "helper": "Fração medida por estrada real (não linha reta por ausência de rota).",
         "interpretacao": "Baixo = muitos municípios sem rota rodoviária (fluviais/insulares)."},
    ]


# ==============================================================================
# [DIVERGENCIA-XAI-2 - 237ª] ORQUESTRAÇÃO + RENDERIZAÇÃO (HTML / Excel / Painel)
# ==============================================================================
def _montar_stage_a(diag, uf_para_regiao=None):
    """[DIVERGENCIA-XAI-2 - 237ª] Enriquece o diagnóstico com a análise aprofundada: por caso adiciona Índice
    de Confiança (app/ref), classe de derrota e decomposição; no todo adiciona KPIs e aprendizado. IDEMPOTENTE
    (não reprocessa se já feito). PURO. Retorna o próprio diag enriquecido."""
    if not diag or diag.get("_stage_a"):
        return diag
    _analises = diag.get("analises") or []
    for a in _analises:
        try:
            _ca = _indice_confianca_escolha(a, "app"); _cr = _indice_confianca_escolha(a, "ref")
            a["Índice de Confiança (App)"] = _ca["valor"]; a["Índice de Confiança (Ref)"] = _cr["valor"]
            a["_conf_app"] = _ca; a["_conf_ref"] = _cr
            _cd = _classificar_derrota(a)
            a["Classe da Derrota"] = _cd["classe"]; a["Derrota Evitável"] = _cd["evitavel"]; a["_derrota"] = _cd
            a["_decomposicao"] = _decompor_diferenca(a)
        except Exception:
            continue
    try:
        diag["kpis"] = _kpis_divergencias(_analises)
    except Exception:
        diag["kpis"] = []
    try:
        diag["aprendizado"] = _aprender_com_derrotas(_analises, uf_para_regiao)
    except Exception:
        diag["aprendizado"] = {}
    diag["_stage_a"] = True
    return diag


# ---------------------------- HTML ----------------------------
def _secao_kpis_html(kpis, _he):
    if not kpis:
        return ""
    _cards = ""
    for k in kpis:
        _v = k.get("valor"); _u = k.get("unidade", "")
        _vt = (f"{_v:,.0f}".replace(",", ".") if isinstance(_v, (int, float)) and _v == int(_v)
               else f"{_v}") if _v is not None else "—"
        _cards += (f'<div class="dv-kpi2"><div class="dv-kpi2-v">{_he.escape(_vt)}<span class="dv-kpi2-u">'
                   f'{_he.escape(str(_u))}</span></div><div class="dv-kpi2-n">{_he.escape(str(k.get("nome","")))}</div>'
                   f'<div class="dv-kpi2-h">{_he.escape(str(k.get("helper","")))}</div>'
                   f'<div class="dv-kpi2-f"><b>Fórmula:</b> {_he.escape(str(k.get("formula","")))} · '
                   f'<b>Leitura:</b> {_he.escape(str(k.get("interpretacao","")))}</div></div>')
    return (f'<h3>📊 Indicadores (KPIs) do diagnóstico</h3>'
            f'<div class="dv-kpis2">{_cards}</div>')


def _secao_derrotas_html(analises, _he):
    _derr = [a for a in (analises or []) if str(a.get("Vencedor (Qualidade)")) == "Referência"]
    if not _derr:
        return '<h3>🎯 Classificação das derrotas</h3><p>A aplicação não perdeu nenhuma divergência por qualidade.</p>'
    _evit = [a for a in _derr if a.get("Derrota Evitável") is True]
    _linhas = ""
    for a in sorted(_derr, key=lambda x: abs(_num2(x.get("Diferença (km)"), 0.0) or 0.0), reverse=True):
        _cd = a.get("_derrota") or {}
        _evb = a.get("Derrota Evitável")
        _cor = "#dc2626" if _evb is True else "#64748b"
        _tag = "EVITÁVEL" if _evb is True else ("—" if _evb is None else "justificável")
        _linhas += (f'<tr><td>{_he.escape(str(a.get("Município","")))}/{_he.escape(str(a.get("UF","")))}</td>'
                    f'<td style="color:{_cor};font-weight:600">{_he.escape(_tag)}</td>'
                    f'<td>{_he.escape(str(a.get("Classe da Derrota","—")))}</td>'
                    f'<td>{_he.escape(str(_cd.get("como_evitar","—")))}</td></tr>')
    return (f'<h3>🎯 Classificação das derrotas ({len(_derr)} — evitáveis: {len(_evit)})</h3>'
            f'<div class="tbl-wrap"><table class="dvt"><thead><tr><th>Município</th><th>Tipo</th>'
            f'<th>Classe</th><th>Como a aplicação passaria a vencer</th></tr></thead>'
            f'<tbody>{_linhas}</tbody></table></div>')


def _secao_aprendizado_html(aprend, _he):
    if not aprend or not aprend.get("n_derrotas"):
        return ""
    _pad = "".join(f"<li>{_he.escape(p)}</li>" for p in aprend.get("padroes", []))
    _sug = "".join(f"<li>{_he.escape(s)}</li>" for s in aprend.get("sugestoes_algoritmo", []))
    _res = _he.escape(aprend.get("resumo", ""))
    return (f'<h3>🧠 Aprendizado com as derrotas</h3>'
            f'<div class="dv-box"><div class="dv-box-t">Padrões detectados</div>'
            f'<div class="dv-box-c">{_res}<ul>{_pad}</ul></div></div>'
            f'<div class="dv-box" style="border-left-color:#16a34a;background:#f0fdf4">'
            f'<div class="dv-box-t" style="color:#166534">Sugestões automáticas de melhoria do algoritmo</div>'
            f'<div class="dv-box-c"><ul>{_sug}</ul></div></div>')


def _css_stage_a():
    return ('<style>'
            '.dv-kpis2{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:12px 0}'
            '.dv-kpi2{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px}'
            '.dv-kpi2-v{font-size:24px;font-weight:800;color:#0f172a}.dv-kpi2-u{font-size:12px;color:#64748b;margin-left:4px}'
            '.dv-kpi2-n{font-size:13px;font-weight:600;color:#1e3a8a;margin:4px 0}'
            '.dv-kpi2-h{font-size:12px;color:#475569;margin:2px 0}'
            '.dv-kpi2-f{font-size:11px;color:#64748b;margin-top:6px;border-top:1px solid #eef2f7;padding-top:6px}'
            '</style>')


def _html_stage_a(diag, _he):
    """[DIVERGENCIA-XAI-2 - 237ª] Blocos HTML da análise aprofundada, para injeção na seção de divergências.
    Idempotente. PURO."""
    try:
        _montar_stage_a(diag)
        _analises = diag.get("analises") or []
        return (_css_stage_a()
                + _secao_kpis_html(diag.get("kpis") or [], _he)
                + _secao_derrotas_html(_analises, _he)
                + _secao_aprendizado_html(diag.get("aprendizado") or {}, _he))
    except Exception:
        return ""


# ---------------------------- EXCEL ----------------------------
def _abas_stage_a(writer, diag):
    """[DIVERGENCIA-XAI-2 - 237ª] Abas Excel da análise aprofundada: KPIs, Derrotas (classificadas), Confiança
    das Escolhas, Aprendizado. Cada aba isolada em try, com explicação didática. DEFENSIVO."""
    try:
        if not diag:
            return
        _wb = getattr(writer, "book", None)
        if _wb is None or not hasattr(_wb, "add_format"):
            return
        _montar_stage_a(diag)
        _analises = diag.get("analises") or []
        _f_tit = _wb.add_format({"bold": True, "font_size": 16, "font_color": "#1e3a8a"})
        _f_lbl = _wb.add_format({"font_size": 10, "font_color": "#475569"})
        _f_num = _wb.add_format({"font_size": 10, "num_format": "#,##0.0", "align": "right"})
        _f_hdr = _wb.add_format({"bold": True, "font_size": 10, "font_color": "#fff", "bg_color": "#1e3a8a",
                                 "border": 1, "border_color": "#cbd5e1", "align": "center", "text_wrap": True})
        _f_exp = _wb.add_format({"font_size": 10, "font_color": "#334155", "italic": True, "text_wrap": True, "valign": "top"})
        _f_txt = _wb.add_format({"font_size": 10, "font_color": "#334155", "text_wrap": True, "valign": "top"})

        # ---- KPIs ----
        try:
            _kpis = diag.get("kpis") or []
            if _kpis:
                _ws = _wb.add_worksheet("Diag - KPIs")
                _ws.set_column("A:A", 34); _ws.set_column("B:C", 16); _ws.set_column("D:F", 40)
                _ws.write("A1", "Indicadores (KPIs) do diagnóstico", _f_tit)
                for _c, _h in enumerate(["KPI", "Valor", "Unidade", "Fórmula", "O que significa", "Como interpretar"]):
                    _ws.write(2, _c, _h, _f_hdr)
                for _i, k in enumerate(_kpis):
                    _r = 3 + _i
                    _ws.write(_r, 0, str(k.get("nome", "")), _f_lbl)
                    _ws.write_number(_r, 1, float(_num2(k.get("valor"), 0.0) or 0.0), _f_num)
                    _ws.write(_r, 2, str(k.get("unidade", "")), _f_lbl)
                    _ws.write(_r, 3, str(k.get("formula", "")), _f_txt)
                    _ws.write(_r, 4, str(k.get("helper", "")), _f_txt)
                    _ws.write(_r, 5, str(k.get("interpretacao", "")), _f_txt)
                    _ws.set_row(_r, 44)
        except Exception:
            pass

        # ---- Derrotas classificadas ----
        try:
            _derr = [a for a in _analises if str(a.get("Vencedor (Qualidade)")) == "Referência"]
            if _derr:
                _ws = _wb.add_worksheet("Diag - Derrotas")
                _ws.set_column("A:A", 24); _ws.set_column("B:B", 8); _ws.set_column("C:C", 10)
                _ws.set_column("D:D", 44); _ws.set_column("E:E", 12); _ws.set_column("F:F", 55)
                for _c, _h in enumerate(["Município", "UF", "Evitável?", "Classe da derrota", "Δkm", "Como passaria a vencer"]):
                    _ws.write(0, _c, _h, _f_hdr)
                for _i, a in enumerate(sorted(_derr, key=lambda x: abs(_num2(x.get("Diferença (km)"), 0.0) or 0.0), reverse=True)):
                    _r = 1 + _i; _cd = a.get("_derrota") or {}
                    _ev = a.get("Derrota Evitável")
                    _ws.write(_r, 0, str(a.get("Município", "")), _f_lbl)
                    _ws.write(_r, 1, str(a.get("UF", "")), _f_lbl)
                    _ws.write(_r, 2, ("Sim" if _ev is True else ("—" if _ev is None else "Não")), _f_lbl)
                    _ws.write(_r, 3, str(a.get("Classe da Derrota", "")), _f_txt)
                    _ws.write_number(_r, 4, abs(_num2(a.get("Diferença (km)"), 0.0) or 0.0), _f_num)
                    _ws.write(_r, 5, str(_cd.get("como_evitar", "")), _f_txt)
                    _ws.set_row(_r, 44)
                _ws.freeze_panes(1, 0)
                _re = len(_derr) + 2
                _ws.merge_range(_re, 0, _re, 5,
                                "Derrotas classificadas por NATUREZA. 'Evitável = Sim' marca a assinatura de "
                                "geometria×estrada (V/R alta): a aplicação escolheu um destino geometricamente "
                                "próximo porém rodoviariamente indireto e o vencedor direto foi cortado na "
                                "pré-seleção. São o alvo do resgate por circuidade (Etapa C). 'Não/—' = ruído de "
                                "geocodificação ou trade-off operacional legítimo.", _f_exp)
                _ws.set_row(_re, 90)
        except Exception:
            pass

        # ---- Confiança das escolhas ----
        try:
            if _analises:
                _ws = _wb.add_worksheet("Diag - Confianca")
                _ws.set_column("A:A", 24); _ws.set_column("B:B", 8); _ws.set_column("C:D", 16); _ws.set_column("E:E", 55)
                for _c, _h in enumerate(["Município", "UF", "Confiança (App)", "Confiança (Ref)", "Fatores (App)"]):
                    _ws.write(0, _c, _h, _f_hdr)
                for _i, a in enumerate(_analises):
                    _r = 1 + _i; _ca = a.get("_conf_app") or {}
                    _ws.write(_r, 0, str(a.get("Município", "")), _f_lbl)
                    _ws.write(_r, 1, str(a.get("UF", "")), _f_lbl)
                    _ws.write_number(_r, 2, float(_num2(a.get("Índice de Confiança (App)"), 0.0) or 0.0), _f_num)
                    _ws.write_number(_r, 3, float(_num2(a.get("Índice de Confiança (Ref)"), 0.0) or 0.0), _f_num)
                    _ws.write(_r, 4, "; ".join(_ca.get("fatores", []) or []), _f_txt)
                    _ws.set_row(_r, 30)
                _ws.freeze_panes(1, 0)
                _re = len(_analises) + 2
                _ws.merge_range(_re, 0, _re, 4,
                                "Índice de Confiança da Escolha (0-100): quanto confiar na medição/rota daquela "
                                "opção, compondo coerência viário×reta, consenso entre motores, estabilidade da "
                                "rota, ausência de balsa e robustez. Confiança BAIXA na app + ALTA na referência é "
                                "um forte indício de que a app escolheu por um sinal enganoso (geometria).", _f_exp)
                _ws.set_row(_re, 74)
        except Exception:
            pass

        # ---- Aprendizado ----
        try:
            _ap = diag.get("aprendizado") or {}
            if _ap.get("n_derrotas"):
                _ws = _wb.add_worksheet("Diag - Aprendizado")
                _ws.set_column("A:A", 100)
                _ws.write("A1", "Aprendizado com as derrotas", _f_tit)
                _r = 3
                _ws.write(_r, 0, "Resumo", _f_hdr); _r += 1
                _ws.write(_r, 0, str(_ap.get("resumo", "")), _f_txt); _ws.set_row(_r, 44); _r += 2
                _ws.write(_r, 0, "Padrões detectados", _f_hdr); _r += 1
                for p in _ap.get("padroes", []):
                    _ws.write(_r, 0, "• " + str(p), _f_txt); _ws.set_row(_r, 44); _r += 1
                _r += 1
                _ws.write(_r, 0, "Sugestões automáticas de melhoria do algoritmo", _f_hdr); _r += 1
                for s in _ap.get("sugestoes_algoritmo", []):
                    _ws.write(_r, 0, "• " + str(s), _f_txt); _ws.set_row(_r, 58); _r += 1
        except Exception:
            pass
    except Exception:
        return


# ---------------------------- PAINEL STREAMLIT ----------------------------
def _painel_stage_a(diag, st, pd=None):
    """[DIVERGENCIA-XAI-2 - 237ª] Seções do painel: KPIs, classificação das derrotas e aprendizado.
    Recebe st (e pd) explicitamente. DEFENSIVO."""
    try:
        _montar_stage_a(diag)
        _analises = diag.get("analises") or []
        _kpis = diag.get("kpis") or []
        _ap = diag.get("aprendizado") or {}

        if _kpis:
            st.markdown("#### 📊 Indicadores (KPIs)")
            _cols = st.columns(4)
            for _i, k in enumerate(_kpis):
                _v = k.get("valor"); _u = k.get("unidade", "")
                _vt = (f"{_v:,.0f}".replace(",", ".") if isinstance(_v, (int, float)) and _v == int(_v) else f"{_v}") if _v is not None else "—"
                _cols[_i % 4].metric(k.get("nome", ""), f"{_vt} {_u}".strip(),
                                     help=f"{k.get('helper','')} · Fórmula: {k.get('formula','')}")

        _derr = [a for a in _analises if str(a.get("Vencedor (Qualidade)")) == "Referência"]
        if _derr:
            _evit = [a for a in _derr if a.get("Derrota Evitável") is True]
            st.markdown(f"#### 🎯 Classificação das derrotas — {len(_derr)} total, **{len(_evit)} evitáveis**")
            if pd is not None:
                _rows = [{"Município": a.get("Município"), "UF": a.get("UF"),
                          "Evitável?": ("Sim" if a.get("Derrota Evitável") is True else ("—" if a.get("Derrota Evitável") is None else "Não")),
                          "Classe": a.get("Classe da Derrota"),
                          "Δkm": round(abs(_num2(a.get("Diferença (km)"), 0.0) or 0.0), 0),
                          "Como passaria a vencer": (a.get("_derrota") or {}).get("como_evitar", "")}
                         for a in sorted(_derr, key=lambda x: abs(_num2(x.get("Diferença (km)"), 0.0) or 0.0), reverse=True)]
                st.dataframe(pd.DataFrame(_rows), use_container_width=True, hide_index=True)

        if _ap.get("n_derrotas"):
            with st.container(border=True):
                st.markdown("#### 🧠 Aprendizado com as derrotas")
                st.caption(_ap.get("resumo", ""))
                if _ap.get("padroes"):
                    st.markdown("**Padrões detectados:**")
                    for p in _ap["padroes"]:
                        st.markdown("- " + str(p))
                if _ap.get("sugestoes_algoritmo"):
                    st.markdown("**Sugestões automáticas de melhoria do algoritmo:**")
                    for s in _ap["sugestoes_algoritmo"]:
                        st.markdown("- " + str(s))
    except Exception as _e:
        try:
            st.caption(f"(análise aprofundada indisponível: {_e})")
        except Exception:
            pass
# <<< [DIVERGENCIA-XAI-2 237ª] FIM >>>




# <<< [RESGATE-CIRCUIDADE 238ª] INÍCIO — evolução da escolha do destino (resgate por circuidade) >>>
# ==============================================================================
# [RESGATE-CIRCUIDADE - 238ª geração / Etapa C] EVOLUÇÃO DA ESCOLHA DO DESTINO
# ------------------------------------------------------------------------------
# Fundamento (Etapas A+B, dados reais de Divergências.xlsx): as derrotas EVITÁVEIS
# têm a assinatura de V/R alta — a app escolheu um destino geometricamente próximo
# porém rodoviariamente indireto, e o vencedor direto foi cortado ANTES do
# roteamento (Portão 1: além do N por reta; Portão 2: OSRM falhou/inflou). Este
# módulo adiciona um REFINAMENTO PÓS-ESCOLHA: quando o destino escolhido exibe a
# assinatura de risco, roteia um conjunto LIMITADO de candidatos mais diretos pelo
# motor AUTORITATIVO (contornando a pré-seleção) e adota o melhor PARA O CANDIDATO.
#
# GARANTIAS (mesma filosofia dos guardas já existentes):
#   • MONOTÔNICO: só troca se a alternativa for comprovadamente melhor para o
#     candidato (menor rota real; ou quase-igual eliminando balsa/circuidade).
#     Nunca piora o resultado — na dúvida, mantém a escolha original.
#   • LIMITADO: só dispara na assinatura de risco (raro → custo desprezível).
#   • EXPLICÁVEL: devolve um registro com evidências (km/tempo salvos, nº de
#     candidatos beneficiados, motivo) para painel/HTML/planilha.
#   • REVERSÍVEL: a integração fica atrás de uma flag; desligá-la restaura o
#     comportamento anterior EXATO.
# 100% PURO (a rede entra por fn_rota injetada). Testável isoladamente.
# ==============================================================================
_UF_AMAZONIA_RESC = frozenset({"AC", "AP", "AM", "MA", "MT", "PA", "RO", "RR", "TO"})

# Parâmetros (num único lugar; calibrados pela assinatura empírica das derrotas).
_VR_GATILHO = 1.45        # V/R do escolhido acima da qual vale investigar. Com o TETO PRIORIZADO POR IMPACTO
                          # (244ª), 1,45 captura mais derrotas evitáveis (ex.: Pauini/Ipixuna) sem estourar o
                          # orçamento de rede: o teto gasta os roteamentos nos casos de maior km×candidatos.
_VR_SEVERO = 2.00         # descasamento grave geometria×estrada
_K_EXTRA_BASE = 6         # candidatos diretos extras a rotear no resgate (limitado!)
_K_EXTRA_AMAZONIA = 10    # amplia onde a malha é esparsa
_MARGEM_TROCA = 0.005     # só troca se a alternativa for ao menos 0,5% menor (evita ruído)
# [V308 · FATIA 2a] GATILHO ADMISSÍVEL (branch-and-bound) — reforço do resgate por circuidade.
# Fundamento (teorema, não heurística): viária >= linha reta SEMPRE. Logo, se um polo NÃO roteado tem
# LINHA RETA menor que a viária do polo atualmente escolhido, ele PODE ter rota viária menor e PRECISA ser
# avaliado. Só quando NENHUM polo não-roteado tem reta < viária-atual é que a escolha é PROVADAMENTE ótima.
# Foi exatamente o que faltou em Guajará-Mirim/Nova Mamoré: Porto Velho é mais longe em reta que o polo
# escolhido, porém MAIS CURTO por estrada — e nunca era roteado (fora do top-10 e sem assinatura de risco).
# MONOTÔNICO (só troca por viária estritamente menor via _avaliar_troca), LIMITADO e REVERSÍVEL.
_RESGATE_ADMISSIVEL_ATIVO = True   # False → comportamento idêntico ao v307 (só resgate por assinatura de risco)
_MARGEM_ADMISSIVEL_KM = 0.5        # candidato só é "promissor" se a reta for ao menos isto menor que a viária atual
_MAX_ADMISSIVEL_ROTEAR = 40        # teto de polos extras roteados por origem no gatilho admissível (custo de rede)
# [V309 · FATIA 2b] MODO VIÁRIA ESTRITA — filosofia "balsa é rede, não penalidade".
# No modo "🛣️ Menor rota viária", o resgate decide pela MENOR VIÁRIA GENUÍNA (a travessia de balsa conta a
# VALOR DE FACE, sem penalidade: travessia curta vence desvio rodoviário enorme; desvio rodoviário curto
# vence balsa longa). Guarda anti-fantasma: uma alternativa só compete se for viária GENUÍNA — motor de rota
# real E viária >= linha reta (lei física). Rota-fantasma (snap para o outro lado do rio, sem travessia real)
# e fallback geodésico NÃO são coroados. Reversível: False → decisão por custo efetivo (comportamento v308).
_VIARIA_ESTRITA_ATIVA = True
# [V316 · Melhoria 3] EVITAR BALSA A TODO CUSTO — regra de negócio prioritária: a rota vencedora deve ser
# sempre TERRESTRE (sem balsa) quando existir uma válida; uma rota com balsa, mesmo mais curta, NÃO vence —
# vira ALTERNATIVA sinalizada. Só se não houver rota terrestre válida a balsa é usada, como exceção marcada.
# Inverte, de propósito, a filosofia "balsa é rede" da v309/2b (a regra de negócio mudou). Reversível:
# False → volta a decidir só por menor viária genuína (comportamento v309).
_EVITAR_BALSA_ATIVO = True
# penalidades operacionais em "km equivalentes" (para o custo efetivo do trade-off):
_PEN_BALSA_KM = 25.0      # balsa: horário/clima/capacidade/risco
_PEN_FLUVIAL_KM = 60.0    # acesso fluvial/isolado (sem rota rodoviária plena)
_LAMBDA_VR = 0.15         # peso da circuidade excedente no custo efetivo


def _num(v, d=None):
    try:
        if v is None or (isinstance(v, float) and v != v):
            return d
        return float(v)
    except (TypeError, ValueError):
        return d


def _hav(la1, lo1, la2, lo2):
    try:
        import math as _mr
        p = _mr.pi / 180.0
        a = (_mr.sin((la2 - la1) * p / 2) ** 2
             + _mr.cos(la1 * p) * _mr.cos(la2 * p) * _mr.sin((lo2 - lo1) * p / 2) ** 2)
        return 6371.0088 * 2 * _mr.asin(_mr.sqrt(min(1.0, a)))
    except Exception:
        return float("inf")


def _classificar_contexto(uf, reta_km, tem_balsa, fluvial):
    """Classifica o contexto do município para comportamento ADAPTATIVO (item: inteligência adaptativa)."""
    _uf = str(uf or "").upper()[:2]
    if fluvial:
        return "fluvial/isolado"
    if _uf in _UF_AMAZONIA_RESC:
        return "amazônico"
    if tem_balsa:
        return "com balsa/travessia"
    return "rodoviário padrão"


def _custo_efetivo(dist_km, vr, tem_balsa, fluvial):
    """Custo EFETIVO para o candidato: distância real + penalidades operacionais em km-equivalentes. É o
    coração do 'algoritmo que pensa' — não escolhe só o menor km, e sim o menor CUSTO ao candidato."""
    _d = _num(dist_km)
    if _d is None:
        return float("inf")
    _v = _num(vr, 1.0) or 1.0
    _c = _d * (1.0 + _LAMBDA_VR * max(0.0, _v - 1.0))
    if tem_balsa:
        _c += _PEN_BALSA_KM
    if fluvial:
        _c += _PEN_FLUVIAL_KM
    return _c


def _precisa_resgate(vr_escolhido, tem_balsa, fluvial):
    """Dispara o resgate SÓ na assinatura de risco (raro). Retorna (bool, motivo)."""
    _vr = _num(vr_escolhido)
    if fluvial:
        return True, "destino escolhido é de acesso fluvial/isolado (rota rodoviária pode existir e ser melhor)"
    if tem_balsa:
        return True, "destino escolhido depende de balsa (alternativa rodoviária pode ser melhor)"
    if _vr is not None and _vr >= _VR_GATILHO:
        return True, f"rota escolhida é indireta (V/R {_vr:.2f}×) — a geometria pode ter enganado a pré-seleção"
    return False, ""


def _avaliar_troca(atual, alternativa):
    """Trade-off INTELIGENTE entre a escolha atual e uma alternativa (ambas com rota real medida). Decide pelo
    menor CUSTO EFETIVO, mas exige margem mínima para trocar (estabilidade). Retorna dict com decisão + motivo
    + evidências. `atual`/`alternativa` = dict {nome, dist_km, vr, tem_balsa, fluvial, tempo_min}."""
    _ca = _custo_efetivo(atual.get("dist_km"), atual.get("vr"), atual.get("tem_balsa"), atual.get("fluvial"))
    _cb = _custo_efetivo(alternativa.get("dist_km"), alternativa.get("vr"), alternativa.get("tem_balsa"), alternativa.get("fluvial"))
    _da = _num(atual.get("dist_km")); _db = _num(alternativa.get("dist_km"))
    _res = {"trocar": False, "motivo": "", "km_salvo": None, "tempo_salvo_min": None,
            "custo_atual": round(_ca, 1) if _ca != float("inf") else None,
            "custo_alt": round(_cb, 1) if _cb != float("inf") else None}
    if _cb == float("inf") or _db is None:
        _res["motivo"] = "alternativa sem rota válida"
        return _res
    # troca só se a alternativa tem custo efetivo menor com margem mínima
    if _ca == float("inf") or _cb <= _ca * (1.0 - _MARGEM_TROCA):
        _res["trocar"] = True
        _res["km_salvo"] = round((_da - _db), 1) if (_da is not None and _db is not None) else None
        _ta, _tb = _num(atual.get("tempo_min")), _num(alternativa.get("tempo_min"))
        _res["tempo_salvo_min"] = round(_ta - _tb, 0) if (_ta is not None and _tb is not None) else None
        # motivo baseado em EVIDÊNCIAS (o que mudou de fato)
        _mots = []
        if _da is not None and _db is not None and _db < _da:
            _mots.append(f"reduz {round(_da - _db,1)} km de deslocamento real")
        if atual.get("tem_balsa") and not alternativa.get("tem_balsa"):
            _mots.append("elimina a dependência de balsa")
        if atual.get("fluvial") and not alternativa.get("fluvial"):
            _mots.append("substitui acesso fluvial/isolado por rota rodoviária plena")
        _va, _vb = _num(atual.get("vr")), _num(alternativa.get("vr"))
        if _va is not None and _vb is not None and _vb < _va - 0.1:
            _mots.append(f"rota mais direta (V/R {_vb:.2f}× vs {_va:.2f}×)")
        _res["motivo"] = "; ".join(_mots) or "menor custo efetivo para o candidato"
    else:
        # alternativa NÃO é melhor → a escolha atual se justifica; explica por quê (item: quando a app está certa)
        _just = []
        if _db is not None and _da is not None and _db < _da:
            _dif = round(_da - _db, 1)
            if alternativa.get("tem_balsa") and not atual.get("tem_balsa"):
                _just.append(f"a alternativa economizaria {_dif} km, mas introduz travessia por balsa "
                             f"(horário/clima/capacidade) e maior risco operacional")
            elif alternativa.get("fluvial") and not atual.get("fluvial"):
                _just.append(f"a alternativa economizaria {_dif} km, mas depende de acesso fluvial/isolado")
            else:
                _just.append(f"o ganho de {_dif} km não compensa a perda de robustez operacional")
        _res["motivo"] = "; ".join(_just) or "a escolha atual tem menor custo efetivo para o candidato"
    return _res


_V309C_NOME_IDX = None  # cache do índice inverso {nome_norm: frozenset(codigos)} para a guarda fluvial REGIC


def _v309c_indice_nome_para_codigos():
    """[V310 · FATIA 2c] Índice inverso {nome_normalizado (unidecode/UPPER/strip): frozenset(codigos_ibge)},
    construído UMA vez a partir de _indice_ibge_por_codigo(). Permite consultar o status REGIC-fluvial de um
    município pelo NOME quando não há Código IBGE em mãos (é o caso do resgate, cujos candidatos vêm do
    topk_map só com o nome do polo). Defensivo: qualquer falha devolve dict vazio (→ guarda fica inerte)."""
    global _V309C_NOME_IDX
    if _V309C_NOME_IDX is not None:
        return _V309C_NOME_IDX
    _idx = {}
    try:
        for _cod, _info in (_indice_ibge_por_codigo() or {}).items():
            _nome = unidecode(str(_info.get("municipio", ""))).upper().strip()
            if not _nome:
                continue
            _idx.setdefault(_nome, set()).add(str(_cod))
        _idx = {_k: frozenset(_v) for _k, _v in _idx.items()}
    except Exception:
        _idx = {}
    _V309C_NOME_IDX = _idx
    return _idx


def _v309c_destino_fluvial_sem_balsa(municipio_destino, tem_balsa, conjunto=None, indice_nome=None):
    """[V310 · FATIA 2c] GUARDA FLUVIAL REGIC. Devolve True SOMENTE quando há CONFIANÇA de que a rota é
    fantasma: o município de destino consta na lista oficial REGIC de acesso fluvial/isolado E a rota NÃO
    tem balsa real (não há estrada de carro até a ilha; a 'viária curta' é um snap para o outro lado do rio).
    FAIL-OPEN por segurança: balsa real, nome que não resolve, ou nome AMBÍGUO (homônimo entre um município
    fluvial e um não-fluvial) → False (NÃO bloqueia; preserva a decisão da Fatia 2b). Nunca coroa nada — só
    pode ACRESCENTAR uma recusa quando confiante. PURA (conjunto e índice injetáveis para teste)."""
    try:
        if tem_balsa:  # travessia real declarada → é rede legítima, jamais fantasma
            return False
        if conjunto is None:
            if not FLUVIAL_LISTA_ATIVA:
                return False
            conjunto = _MUNICIPIOS_ACESSO_FLUVIAL
        _nome = unidecode(str(municipio_destino or "")).upper().strip()
        if not _nome:
            return False
        _idx = indice_nome if indice_nome is not None else _v309c_indice_nome_para_codigos()
        _codigos = _idx.get(_nome)
        if not _codigos:
            return False  # nome não resolve → fail-open
        # NÃO-ambiguidade obrigatória: todos os códigos daquele nome precisam ser REGIC-fluvial. Se algum não
        # for, o nome é ambíguo (homônimo) e podemos estar diante do município NÃO-fluvial → fail-open.
        return all(str(_c) in (conjunto or frozenset()) for _c in _codigos)
    except Exception:
        return False


_V316_MOTORES = ("google", "osrm", "graphhopper", "ors", "valhalla", "tomtom")
_V316_FLUVIAL_MARCAS = ("fluvial", "hidrov", "ferry", "marít", "marit", "sem conexão terrestre",
                        "sem rota", "sem malha", "balsa-only", "aquavi")


def _v316_classificar_rota(tem_balsa, fonte="", status="", vr=None, dist=None, tempo=None, reta=None):
    """[V316 · Melhoria 3] Classifica a rota em 5 categorias: 🟢 terrestre · 🟡 terrestre com possível
    travessia · 🔴 balsa · 🔵 fluvial/hidroviária · ⚪ indeterminada. 'terrestre'/'vencivel' dizem se a rota
    pode ser VENCEDORA na política 'evitar balsa' (balsa/fluvial nunca são). Guarda anti-fantasma: uma
    'terrestre' com viária < reta vira indeterminada. NUNCA lança exceção."""
    try:
        _f = str(fonte or "").lower()
        _s = str(status or "").lower()
        _blob = _f + " " + _s
        _balsa = tem_balsa if isinstance(tem_balsa, bool) else str(tem_balsa).strip().lower() in ("sim", "true", "1", "s", "yes")
        _motor = any(m in _f for m in _V316_MOTORES)
        _fluvial = any(m in _blob for m in _V316_FLUVIAL_MARCAS) and not _balsa
        _vr = _num(vr)
        if _balsa:
            _cat, _cor, _rot, _terr = "balsa", "🔴", "Com balsa", False
        elif _fluvial:
            _cat, _cor, _rot, _terr = "fluvial", "🔵", "Fluvial/hidroviária", False
        elif not _motor:
            _cat, _cor, _rot, _terr = "indeterminada", "⚪", "Não determinada", False
        elif (_num(dist) is not None and _num(reta) is not None and _num(dist) < _num(reta) - 0.5):
            _cat, _cor, _rot, _terr = "indeterminada", "⚪", "Não determinada (viária < reta)", False
        elif _vr is not None and _vr >= 2.2:
            _cat, _cor, _rot, _terr = "terrestre_travessia", "🟡", "Terrestre com possível travessia", True
        else:
            _cat, _cor, _rot, _terr = "terrestre", "🟢", "Terrestre — sem balsa", True
        return {"categoria": _cat, "cor": _cor, "rotulo": f"{_cor} {_rot}", "terrestre": _terr, "vencivel": _terr}
    except Exception:
        return {"categoria": "indeterminada", "cor": "⚪", "rotulo": "⚪ Não determinada",
                "terrestre": False, "vencivel": False}


def _v316_decidir_terrestre_primeiro(atual, alt, margem_km=0.5):
    """[V316 · Melhoria 3] Decisão sob a política EVITAR BALSA. terrestre SEMPRE vence balsa/fluvial (mesmo
    mais longa); entre terrestres vence a menor; sem nenhuma terrestre, vence a menor (exceção sinalizada).
    Quando uma balsa é mais curta que a terrestre mantida, devolve 'alternativa_balsa' (oportunidade), nunca
    como vitória. Retorna {trocar, motivo, km_salvo, alternativa_balsa|None, excecao_sem_terrestre}."""
    _res = {"trocar": False, "motivo": "", "km_salvo": None, "alternativa_balsa": None,
            "excecao_sem_terrestre": False}
    try:
        _da = _num(atual.get("dist_km")); _db = _num(alt.get("dist_km"))
        _ca = _v316_classificar_rota(atual.get("tem_balsa"), atual.get("fonte", ""), atual.get("status", ""),
                                     vr=atual.get("vr"), dist=_da, tempo=atual.get("tempo"), reta=atual.get("reta_km"))
        _cb = _v316_classificar_rota(alt.get("tem_balsa"), alt.get("fonte", ""), alt.get("status", ""),
                                     vr=alt.get("vr"), dist=_db, tempo=alt.get("tempo"), reta=alt.get("reta_km"))
        _ta, _tb = _ca["terrestre"], _cb["terrestre"]

        def _alt_balsa(dic, _cl):
            return {"nome": dic.get("nome"), "dist_km": _num(dic.get("dist_km")), "tempo": dic.get("tempo"),
                    "fonte": dic.get("fonte"), "categoria": _cl["categoria"], "rotulo": _cl["rotulo"]}

        if _ta and not _tb:
            if _db is not None and _da is not None and _db < _da:
                _res["alternativa_balsa"] = _alt_balsa(alt, _cb)
                _res["motivo"] = (f"alternativa {_cb['rotulo']} seria {_da - _db:.1f} km mais curta, mas a "
                                  f"política prioriza rota terrestre — mantida a terrestre")
            else:
                _res["motivo"] = "alternativa não-terrestre e não mais curta — ignorada"
            return _res
        if _tb and not _ta:
            _res["trocar"] = True
            _res["km_salvo"] = (round(_da - _db, 1) if (_da is not None and _db is not None) else None)
            if _da is not None and _db is not None and _da < _db:
                _res["alternativa_balsa"] = _alt_balsa(atual, _ca)
                _res["motivo"] = (f"adota rota terrestre {_cb['rotulo']} ({_db:.1f} km) no lugar de "
                                  f"{_ca['rotulo']} ({_da:.1f} km); a balsa era {_db - _da:.1f} km mais curta, "
                                  f"registrada como alternativa")
            else:
                _res["motivo"] = f"adota rota terrestre {_cb['rotulo']} no lugar de {_ca['rotulo']}"
            return _res
        if _ta and _tb:
            if _da is None or (_db is not None and _db < _da - float(margem_km)):
                _res["trocar"] = True
                _res["km_salvo"] = (round(_da - _db, 1) if (_da is not None and _db is not None) else None)
                _res["motivo"] = (f"menor rota terrestre: {_db:.1f} km vs {_da:.1f} km"
                                  if _da is not None else "rota terrestre")
            else:
                _res["motivo"] = "rota terrestre atual já é a menor"
            return _res
        _res["excecao_sem_terrestre"] = True
        if _da is None or (_db is not None and _db < _da - float(margem_km)):
            _res["trocar"] = True
            _res["km_salvo"] = (round(_da - _db, 1) if (_da is not None and _db is not None) else None)
            _res["motivo"] = f"EXCEÇÃO: sem rota terrestre válida; adotada a menor não-terrestre ({_cb['rotulo']})"
        else:
            _res["motivo"] = f"EXCEÇÃO: sem rota terrestre; mantida a menor não-terrestre ({_ca['rotulo']})"
        return _res
    except Exception:
        return {"trocar": False, "motivo": "decisão abortada com segurança", "km_salvo": None,
                "alternativa_balsa": None, "excecao_sem_terrestre": False}


def _v317_memoria_geografica(df, vr_alto=1.9, div_alta_pct=25.0):
    """[Melhoria 4/§8 · forma SEGURA] MEMÓRIA GEOGRÁFICA DIAGNÓSTICA — read-only. Varre o resultado de um
    estudo e destaca municípios 'problemáticos' pelos sinais JÁ calculados (V/R alto, rota impossível, sem
    rota, balsa, divergência entre motores). NÃO persiste nada e NÃO afeta decisão — é diagnóstico/auditoria
    (§8 sem substituir a validação atual). Persistência entre execuções fica como decisão de arquitetura à
    parte (rotulada 'Avaliar' no parecer). Retorna {n_problematicos,total,municipios,por_motivo}. PURA."""
    try:
        if df is None or not len(df):
            return {"n_problematicos": 0, "total": 0}
        _cm = {str(c).strip().lower(): c for c in df.columns}
        _c_org = _cm.get("origem"); _c_uf = _cm.get("uf") or _cm.get("uf origem")
        _c_dist = _cm.get("distancia"); _c_reta = _cm.get("linha reta")
        _c_balsa = _cm.get("balsas"); _c_fonte = _cm.get("fonte da rota")
        _c_status = _cm.get("status da rota")
        _c_div = _cm.get("divergencia motores (%)") or _cm.get("divergência motores (%)")
        _por_motivo = {}; _muns = []
        for _r in df.to_dict("records"):
            _mot = []
            _d = _num(_r.get(_c_dist)) if _c_dist else None
            _rt = _num(_r.get(_c_reta)) if _c_reta else None
            if _d is not None and _rt is not None and _rt > 0:
                _vr = _d / _rt
                if _d < _rt - 0.5:
                    _mot.append("rota impossível (viária < reta)")
                elif _vr >= vr_alto:
                    _mot.append(f"rota muito indireta (V/R {_vr:.1f})")
            _st = str(_r.get(_c_status, "")).lower() if _c_status else ""
            _fo = str(_r.get(_c_fonte, "")).lower() if _c_fonte else ""
            if "sem rota" in _st or "sem rota" in _fo or "linha reta" in _fo:
                _mot.append("sem rota viária (fallback geodésico)")
            if _c_balsa and str(_r.get(_c_balsa, "")).strip().lower() == "sim":
                _mot.append("depende de balsa")
            _dv = _num(_r.get(_c_div)) if _c_div else None
            if _dv is not None and _dv >= div_alta_pct:
                _mot.append(f"divergência alta entre motores ({_dv:.0f}%)")
            if _mot:
                for _m in _mot:
                    _k = _m.split(" (")[0]
                    _por_motivo[_k] = _por_motivo.get(_k, 0) + 1
                _muns.append({"origem": str(_r.get(_c_org, "")) if _c_org else "",
                              "uf": str(_r.get(_c_uf, "")) if _c_uf else "",
                              "motivos": _mot, "severidade": len(_mot)})
        _muns.sort(key=lambda x: x["severidade"], reverse=True)
        return {"n_problematicos": len(_muns), "total": len(df), "municipios": _muns,
                "por_motivo": dict(sorted(_por_motivo.items(), key=lambda kv: kv[1], reverse=True))}
    except Exception:
        return {"n_problematicos": 0, "total": 0}


def _v316_comparador_balsa(dist_app, dist_ref, balsa_app, balsa_ref):
    """[V316 · Melhoria 3, fatia 5] QUANTIFICA o trade-off de balsa no Comparador (app × referência) a partir
    de dados já presentes. NÃO substitui o veredito (que já dá vantagem operacional ao lado sem balsa —
    23074/23112) — complementa com uma frase explícita e exportável (a quantificação em km que faltava).
    PURA/defensiva."""
    try:
        _ba = str(balsa_app).strip().lower() in ("sim", "true", "1", "s")
        _br = str(balsa_ref).strip().lower() in ("sim", "true", "1", "s")
        _da, _dr = _num(dist_app), _num(dist_ref)
        if not _ba and not _br:
            return "Ambas terrestres — sem dependência de balsa dos dois lados"
        if _ba and _br:
            return "Ambas dependem de balsa"
        if _ba and not _br:
            if _da is not None and _dr is not None and _da < _dr:
                return (f"App usou balsa e ficou {_dr - _da:.1f} km mais curta; a referência evitou balsa "
                        f"(rota terrestre). Pela política atual (evitar balsa), a referência é operacionalmente preferível.")
            return "App usou balsa; a referência evitou balsa (rota terrestre) — preferível pela política atual."
        if _dr is not None and _da is not None and _dr < _da:
            return (f"App evitou balsa (rota terrestre, +{_da - _dr:.1f} km); a referência dependeu de uma balsa "
                    f"mais curta. A app está alinhada à política de evitar balsa.")
        return "App evitou balsa (rota terrestre); a referência dependeu de balsa. App alinhada à política atual."
    except Exception:
        return "Não identificada"


def _v316_resolver_coord_alt(nome, uf_hint="", idx_nome=None, idx_cod=None):
    """[V316 · Melhoria 3, fatia 4] Resolve a coordenada REAL do destino alternativo por balsa (nome → IBGE →
    lat/lon/uf), reusando os índices já existentes (§19). Homônimo → prefere a UF da origem; se ainda ambíguo
    ou sem coordenada, marca incerto=True (§15). FAIL-SAFE: sem resolução → lat/lon None."""
    _r = {"lat": None, "lon": None, "uf": "", "ibge": "", "incerto": False}
    try:
        _nm = unidecode(str(nome or "")).upper().strip()
        if not _nm:
            return _r
        _in = idx_nome if idx_nome is not None else _v309c_indice_nome_para_codigos()
        _ic = idx_cod if idx_cod is not None else _indice_ibge_por_codigo()
        _cods = (_in or {}).get(_nm)
        if not _cods:
            return _r
        _cods = list(_cods)
        _uf_hint = str(uf_hint or "").strip().upper()
        if len(_cods) == 1:
            _escolhido = _cods[0]
        else:
            _match = [c for c in _cods if str((_ic.get(c) or {}).get("uf", "")).upper() == _uf_hint]
            if len(_match) == 1:
                _escolhido = _match[0]
            elif _match:
                _escolhido = _match[0]; _r["incerto"] = True
            else:
                _escolhido = _cods[0]; _r["incerto"] = True
        _info = _ic.get(_escolhido) or {}
        _lat = _num(_info.get("lat")); _lon = _num(_info.get("lon"))
        _r.update({"lat": _lat, "lon": _lon, "uf": str(_info.get("uf", "") or ""), "ibge": str(_escolhido)})
        if _lat in (None, 0.0) or _lon in (None, 0.0):
            _r["incerto"] = True
        return _r
    except Exception:
        return _r


def _v316_agregar_balsa(df):
    """[V316 · Melhoria 3, fatia 3] Agrega as métricas da alternativa por balsa a partir das colunas da
    fatia 2. Retorna {n, total_rotas, pct, economia_total_km, economia_media_km, economia_max_km, kmc_total,
    por_uf, top}. Sem alternativas → {'n': 0}. PURA/defensiva."""
    try:
        if df is None or not len(df):
            return {"n": 0}
        _cm = {str(c).strip().lower(): c for c in df.columns}
        _c_al = _cm.get("alerta balsa")
        if not _c_al:
            return {"n": 0}
        _c_ec = _cm.get("economia potencial balsa (km)")
        _c_kc = _cm.get("economia potencial balsa (km-candidato)")
        _c_org = _cm.get("origem"); _c_uf = _cm.get("uf") or _cm.get("uf origem")
        _c_dst = _cm.get("destino alternativo balsa"); _c_dbk = _cm.get("distância balsa (km)")
        _c_ter = _cm.get("municipio destino") or _cm.get("destino")
        _total = len(df); _casos = []
        for _i in df.index:
            if not str(df.at[_i, _c_al]).strip().lower().startswith("sim"):
                continue
            _casos.append({
                "origem": str(df.at[_i, _c_org]) if _c_org else "",
                "uf": str(df.at[_i, _c_uf]) if _c_uf else "",
                "terrestre": str(df.at[_i, _c_ter]) if _c_ter else "",
                "balsa": str(df.at[_i, _c_dst]) if _c_dst else "",
                "dist_balsa": _num(df.at[_i, _c_dbk]) if _c_dbk else None,
                "economia_km": _num(df.at[_i, _c_ec]) if _c_ec else None,
                "km_candidato": _num(df.at[_i, _c_kc]) if _c_kc else None})
        _n = len(_casos)
        if _n == 0:
            return {"n": 0, "total_rotas": _total}
        _ecs = [c["economia_km"] for c in _casos if c["economia_km"] is not None]
        _kcs = [c["km_candidato"] for c in _casos if c["km_candidato"] is not None]
        _por_uf = {}
        for _c in _casos:
            _u = _c["uf"] or "—"
            _d = _por_uf.setdefault(_u, {"uf": _u, "n": 0, "economia_km": 0.0, "km_candidato": 0.0})
            _d["n"] += 1; _d["economia_km"] += (_c["economia_km"] or 0.0)
            _d["km_candidato"] += (_c["km_candidato"] or 0.0)
        return {"n": _n, "total_rotas": _total,
                "pct": round(100.0 * _n / _total, 1) if _total else 0.0,
                "economia_total_km": round(sum(_ecs), 1) if _ecs else 0.0,
                "economia_media_km": round(sum(_ecs) / len(_ecs), 1) if _ecs else 0.0,
                "economia_max_km": round(max(_ecs), 1) if _ecs else 0.0,
                "kmc_total": round(sum(_kcs), 0) if _kcs else 0.0,
                "por_uf": sorted(_por_uf.values(), key=lambda x: x["economia_km"], reverse=True),
                "top": sorted(_casos, key=lambda x: (x["km_candidato"] or x["economia_km"] or 0), reverse=True)}
    except Exception:
        return {"n": 0}


def _v316_html_balsa(df):
    """[V316 · Melhoria 3, fatia 3] Corpo HTML da seção '⚠️ Alternativas com balsa não selecionadas' para os
    relatórios. Vazio se não houver alternativa. Reusa _he (html.escape) e as classes .kpis/.kpi já do CSS."""
    try:
        _a = _v316_agregar_balsa(df)
        if not _a.get("n"):
            return ""
        import html as _he
        def _e(x):
            return _he.escape(str(x))
        _kpis = (
            f'<div class="kpis">'
            f'<div class="kpi"><b>{_a["n"]}</b><span>municípios com balsa mais curta</span></div>'
            f'<div class="kpi"><b>{_a["economia_total_km"]:.0f} km</b><span>economia potencial (não usada)</span></div>'
            f'<div class="kpi"><b>{_a["economia_media_km"]:.1f} km</b><span>economia média</span></div>'
            f'<div class="kpi"><b>{_a["economia_max_km"]:.0f} km</b><span>maior economia</span></div>'
            f'<div class="kpi"><b>{_a["kmc_total"]:.0f}</b><span>km-candidato potenciais</span></div>'
            f'<div class="kpi"><b>{_a["pct"]:.1f}%</b><span>das rotas</span></div></div>')
        _rows_uf = "".join(
            f"<tr><td>{_e(u['uf'])}</td><td class='r'>{u['n']}</td>"
            f"<td class='r'>{u['economia_km']:.1f}</td><td class='r'>{u['km_candidato']:.0f}</td></tr>"
            for u in _a["por_uf"])
        _tab_uf = (f"<h3>Por UF</h3><table><thead><tr><th>UF</th><th class='r'>Casos</th>"
                   f"<th class='r'>Economia (km)</th><th class='r'>km-candidato</th></tr></thead>"
                   f"<tbody>{_rows_uf}</tbody></table>")
        _rows_top = "".join(
            f"<tr><td>{_e(c['origem'])}</td><td>{_e(c['terrestre'])}</td><td>{_e(c['balsa'])}</td>"
            f"<td class='r'>{(c['dist_balsa'] or 0):.1f}</td><td class='r'>{(c['economia_km'] or 0):.1f}</td>"
            f"<td class='r'>{(c['km_candidato'] or 0):.0f}</td></tr>"
            for c in _a["top"][:100])
        _tab_top = (f"<h3>Maiores diferenças (top 100)</h3><table><thead><tr><th>Origem</th>"
                    f"<th>🏆 Terrestre (escolhida)</th><th>🛳️ Alternativa balsa</th><th class='r'>km balsa</th>"
                    f"<th class='r'>Economia (km)</th><th class='r'>km-candidato</th></tr></thead>"
                    f"<tbody>{_rows_top}</tbody></table>")
        _nota = ("<p>A metodologia prioriza rotas <b>terrestres sem balsa</b>: em todos os casos abaixo a rota "
                 "terrestre foi mantida como vencedora. A alternativa por balsa é apresentada apenas como "
                 "<b>oportunidade/alerta</b> — mostra quanto se economizaria caso a política de balsa fosse "
                 "permitida. Não é erro nem derrota da aplicação.</p>")
        return _nota + _kpis + _tab_uf + _tab_top
    except Exception:
        return ""


def _v316_aplicar_colunas_balsa(df, regs):
    """[V316 · Melhoria 3, fatia 2] Faz AFLORAR na planilha de Alocação a ALTERNATIVA POR BALSA mais curta
    que o resgate capturou (sem reprocessar rota — §13/§19). Cria colunas dedicadas, preenche 'Não
    identificada'/'Não aplicável' onde não há (nunca célula vazia), calcula economia potencial e impacto por
    candidato. Só marca alerta quando a balsa é REALMENTE mais curta que a terrestre final. Retorna
    (df, resumo) — resumo alimenta o alerta visual. Defensivo: qualquer erro devolve o df intacto."""
    _cols = ["Alerta Balsa", "Destino Alternativo Balsa", "UF Destino Alternativo",
             "Código IBGE Destino Alternativo", "Distância Balsa (km)", "Tempo Balsa",
             "Motor Balsa", "Tipo de Medição Balsa", "Economia Potencial Balsa (km)",
             "Economia Potencial Balsa (km-candidato)", "Justificativa Não-Escolha Balsa"]
    try:
        if df is None or not len(df):
            return df, {"n": 0}
        _mapa = {}
        for _r in (regs or []):
            _ab = (_r or {}).get("alternativa_balsa")
            if _ab and _num(_ab.get("dist_km")) is not None:
                _o = str(_r.get("origem", "")).strip().lower()
                if _o and (_o not in _mapa or _num(_ab["dist_km"]) < _num(_mapa[_o].get("dist_km"))):
                    _mapa[_o] = _ab
        _colmap = {str(c).strip().lower(): c for c in df.columns}
        _c_org = _colmap.get("origem"); _c_dist = _colmap.get("distancia")
        _c_insc = _colmap.get("inscritos")
        _c_venc = _colmap.get("municipio destino") or _colmap.get("destino")
        if not _c_org:
            return df, {"n": 0}
        for _c in _cols:
            if _c not in df.columns:
                df[_c] = pd.Series(["Não identificada"] * len(df), index=df.index, dtype=object)
        _n = 0; _km_total = 0.0; _kmc_total = 0.0; _linhas = []
        for _idx in df.index:
            _o = str(df.at[_idx, _c_org]).strip().lower()
            _ab = _mapa.get(_o)
            if not _ab:
                continue
            _dbalsa = _num(_ab.get("dist_km"))
            _dterr = _num(df.at[_idx, _c_dist]) if _c_dist else None
            _econ = (round(_dterr - _dbalsa, 1) if (_dterr is not None and _dbalsa is not None) else None)
            if _econ is None or _econ <= 0:
                continue  # a terrestre final não é mais longa que a balsa → não é 'oportunidade'
            _insc = _num(df.at[_idx, _c_insc]) if _c_insc else None
            _kmc = round(_econ * _insc, 0) if _insc else None
            _fonte = str(_ab.get("fonte", "") or "")
            _geo = ("geod" in _fonte.lower() or "linha reta" in _fonte.lower() or not _fonte)
            _dbalsa_nome = str(_ab.get("nome", "") or "Não identificada")
            _uf_org = ""
            _c_uf = _colmap.get("uf") or _colmap.get("uf origem")
            if _c_uf:
                _uf_org = str(df.at[_idx, _c_uf] or "")
            _coord = _v316_resolver_coord_alt(_dbalsa_nome, uf_hint=_uf_org)
            df.at[_idx, "Alerta Balsa"] = "Sim — havia rota por balsa mais curta"
            df.at[_idx, "Destino Alternativo Balsa"] = _dbalsa_nome
            df.at[_idx, "UF Destino Alternativo"] = _coord.get("uf") or "Não identificada"
            df.at[_idx, "Código IBGE Destino Alternativo"] = _coord.get("ibge") or "Não identificada"
            df.at[_idx, "Distância Balsa (km)"] = round(_dbalsa, 1) if _dbalsa is not None else "Não identificada"
            df.at[_idx, "Tempo Balsa"] = _ab.get("tempo") or "Não identificada"
            df.at[_idx, "Motor Balsa"] = _fonte or "Não identificada"
            df.at[_idx, "Tipo de Medição Balsa"] = "Geodésica/estimada" if _geo else "Viária (motor real)"
            df.at[_idx, "Economia Potencial Balsa (km)"] = _econ
            df.at[_idx, "Economia Potencial Balsa (km-candidato)"] = (_kmc if _kmc is not None else "Não aplicável")
            df.at[_idx, "Justificativa Não-Escolha Balsa"] = (
                f"Rota por balsa até {_dbalsa_nome} seria {_econ:.1f} km mais curta, mas a metodologia prioriza "
                f"rota terrestre sem balsa; a terrestre foi mantida como vencedora e a balsa registrada como alternativa.")
            _n += 1; _km_total += _econ; _kmc_total += (_kmc or 0.0)
            _linhas.append({"origem": str(df.at[_idx, _c_org]),
                            "destino_terrestre": (str(df.at[_idx, _c_venc]) if _c_venc else ""),
                            "destino_balsa": _dbalsa_nome, "dist_terrestre": _dterr, "dist_balsa": _dbalsa,
                            "economia_km": _econ, "km_candidato": _kmc, "medicao": ("Estimada" if _geo else "Viária"),
                            "lat_balsa": _coord.get("lat"), "lon_balsa": _coord.get("lon"),
                            "coord_incerta": _coord.get("incerto", False), "tempo_balsa": _ab.get("tempo")})
        _linhas.sort(key=lambda x: (x.get("km_candidato") or x.get("economia_km") or 0), reverse=True)
        return df, {"n": _n, "km_total": round(_km_total, 1), "kmc_total": round(_kmc_total, 0), "linhas": _linhas}
    except Exception:
        return df, {"n": 0}


def _v308b_decidir_viaria(atual, alt, margem_km=0.5):
    """[V309 · FATIA 2b] Decisão de troca no modo "🛣️ Menor rota viária". Regra do usuário: a BALSA NÃO é
    penalidade — a travessia é um trecho da rede. Vence a MENOR VIÁRIA GENUÍNA (a balsa conta a valor de
    face). Guarda ANTI-FANTASMA: a alternativa só compete se for viária genuína (motor real E viária >= reta);
    rota-fantasma/fallback geodésico não são coroados. Se o ATUAL for artefato e a alternativa for genuína,
    troca (corrige artefato). PURA/defensiva; mesmo formato de retorno de _avaliar_troca.

      atual/alt = dict {nome, dist_km, reta_km, vr, tem_balsa, fluvial, fonte, tempo_min}
    """
    _res = {"trocar": False, "motivo": "", "km_salvo": None, "tempo_salvo_min": None,
            "custo_atual": None, "custo_alt": None}
    try:
        _da = _num(atual.get("dist_km")); _db = _num(alt.get("dist_km"))
        if _db is None:
            _res["motivo"] = "alternativa sem rota válida"
            return _res
        # proveniência (genuinidade) da ALTERNATIVA — reusa o classificador da Fatia 1
        _pb = _v307_classificar_proveniencia_distancia(
            _db, alt.get("fonte", ""), alt.get("status", ""),
            tem_balsa=alt.get("tem_balsa"), vr=alt.get("vr"), fluvial=alt.get("fluvial"))
        _rb = _num(alt.get("reta_km"))
        # genuína = comparável como viária E fisicamente sã (viária >= reta, tolerância 0,5 km)
        _fisicamente_sa = (_rb is None or _db >= _rb - 0.5)
        _comparavel_b = bool(_pb.get("comparavel_como_viaria"))
        # [V310 · FATIA 2c] guarda fluvial REGIC (fail-open): destino oficialmente fluvial/isolado SEM balsa
        # real → não há estrada até a ilha; a 'viária curta' é rota-fantasma. Recusa como 'menor viária'.
        _fluvial_regic = _v309c_destino_fluvial_sem_balsa(alt.get("nome"), alt.get("tem_balsa"))
        _genuina_b = _comparavel_b and _fisicamente_sa and not _fluvial_regic
        if not _genuina_b:
            if _fluvial_regic:
                _res["motivo"] = ("destino consta na lista REGIC de acesso fluvial/isolado e a rota não tem "
                                  "balsa real — 'viária' curta é rota-fantasma (recusada)")
            elif not _fisicamente_sa:
                _res["motivo"] = ("alternativa fisicamente impossível (viária " + ("%.1f" % _db) +
                                  " km < linha reta " + ("%.1f" % _rb) + " km) — rota-fantasma recusada")
            else:
                _res["motivo"] = ("alternativa não é viária genuína (" + str(_pb.get("tipo_humano", "?")) +
                                  ") — ignorada como 'menor viária' (guarda anti-fantasma)")
            return _res
        # proveniência do ATUAL
        _pa = _v307_classificar_proveniencia_distancia(
            _da, atual.get("fonte", ""), atual.get("status", ""),
            tem_balsa=atual.get("tem_balsa"), vr=atual.get("vr"), fluvial=atual.get("fluvial"))
        _atual_genuina = bool(_pa.get("comparavel_como_viaria"))
        _ta, _tb = _num(atual.get("tempo_min")), _num(alt.get("tempo_min"))
        # Caso 1: o ATUAL não é genuíno (fantasma/fallback) e a alternativa é real → corrige o artefato.
        if not _atual_genuina and _da is not None:
            _res["trocar"] = True
            _res["km_salvo"] = round(_da - _db, 1)
            _res["tempo_salvo_min"] = round(_ta - _tb, 0) if (_ta is not None and _tb is not None) else None
            _res["motivo"] = ("substitui rota não-genuína (" + str(_pa.get("tipo_humano", "?")) +
                              ") por viária real de " + ("%.1f" % _db) + " km")
            return _res
        # Caso 2: ambos genuínos → MENOR VIÁRIA vence (balsa a valor de face, SEM penalidade).
        if _da is None or _db < _da - float(margem_km):
            _res["trocar"] = True
            _res["km_salvo"] = round(_da - _db, 1) if _da is not None else None
            _res["tempo_salvo_min"] = round(_ta - _tb, 0) if (_ta is not None and _tb is not None) else None
            _extra = ""
            if alt.get("tem_balsa") and not atual.get("tem_balsa"):
                _extra = " (inclui travessia de balsa — contabilizada como rede, sem penalidade)"
            elif atual.get("tem_balsa") and not alt.get("tem_balsa"):
                _extra = " (alternativa rodoviária substitui travessia mais longa)"
            _res["motivo"] = ("menor rota viária real: " + ("%.1f" % _db) + " km" +
                              (" vs " + ("%.1f" % _da) + " km" if _da is not None else "") + _extra)
        else:
            _res["motivo"] = ("rota atual já é a menor viária genuína (" +
                              (("%.1f km" % _da) if _da is not None else "n/d") + ")")
        return _res
    except Exception:
        return {"trocar": False, "motivo": "decisão viária abortada com segurança",
                "km_salvo": None, "tempo_salvo_min": None, "custo_atual": None, "custo_alt": None}


def _resgate_circuidade(origem, uf, coord_origem, candidatos, escolhido, fn_rota,
                        inscritos=0, params=None):
    """[RESGATE-CIRCUIDADE - 238ª] Refinamento pós-escolha. Se o destino `escolhido` exibe a assinatura de
    risco, roteia até K candidatos MAIS DIRETOS (por reta) pelo motor AUTORITATIVO (fn_rota) e adota o de
    menor custo efetivo para o candidato. MONOTÔNICO e LIMITADO. Devolve dict:
      {trocou, destino_final, dist_final_km, registro{...}}  — registro com evidências p/ UI/relatório.

    `escolhido` = dict {nome, dist_km, reta_km, vr, tem_balsa, fluvial, tempo_min}
    `candidatos` = lista de dicts {nome, lat, lon} (o universo de polos).
    `fn_rota(destino_nome) -> dict {dist_km, tempo_min, tem_balsa, fluvial, reta_km}` (motor autoritativo)."""
    _p = params or {}
    _kbase = _p.get("k_extra_base", _K_EXTRA_BASE)
    _kama = _p.get("k_extra_amazonia", _K_EXTRA_AMAZONIA)
    _reg = {"origem": origem, "uf": uf, "acionado": False, "contexto": None, "motivo_gatilho": "",
            "candidatos_avaliados": 0, "alternativas": [], "decisao": "manteve", "km_salvo": None,
            "tempo_salvo_min": None, "inscritos_beneficiados": 0, "explicacao": ""}
    try:
        _nome_esc = escolhido.get("nome")
        _vr = _num(escolhido.get("vr"))
        _balsa = bool(escolhido.get("tem_balsa"))
        _fluv = bool(escolhido.get("fluvial"))
        _ctx = _classificar_contexto(uf, escolhido.get("reta_km"), _balsa, _fluv)
        _reg["contexto"] = _ctx
        _precisa, _motivo = _precisa_resgate(_vr, _balsa, _fluv)
        if not _precisa:
            _reg["explicacao"] = "escolha estável (sem assinatura de risco); refinamento não acionado."
            return {"trocou": False, "destino_final": _nome_esc,
                    "dist_final_km": _num(escolhido.get("dist_km")), "registro": _reg}
        _reg["acionado"] = True
        _reg["motivo_gatilho"] = _motivo
        # candidatos mais diretos por reta (exceto o já escolhido), até K
        try:
            _la0, _lo0 = float(coord_origem[0]), float(coord_origem[1])
        except Exception:
            _reg["explicacao"] = "sem coordenada de origem para o refinamento."
            return {"trocou": False, "destino_final": _nome_esc,
                    "dist_final_km": _num(escolhido.get("dist_km")), "registro": _reg}
        _por_reta = []
        for c in (candidatos or []):
            if str(c.get("nome", "")).strip().lower() == str(_nome_esc or "").strip().lower():
                continue
            _la, _lo = _num(c.get("lat")), _num(c.get("lon"))
            if _la is None or _lo is None:
                continue
            _por_reta.append((_hav(_la0, _lo0, _la, _lo), c.get("nome")))
        _por_reta.sort(key=lambda x: x[0])
        _k = _kama if str(uf or "").upper()[:2] in _UF_AMAZONIA_RESC else _kbase
        _cands = _por_reta[:_k]

        _atual = {"nome": _nome_esc, "dist_km": _num(escolhido.get("dist_km")), "vr": _vr,
                  "tem_balsa": _balsa, "fluvial": _fluv, "tempo_min": _num(escolhido.get("tempo_min"))}
        _melhor = dict(_atual)
        _melhor_troca = None
        for (_reta, _nome) in _cands:
            try:
                _r = fn_rota(_nome)
            except Exception:
                _r = None
            if not _r or _num(_r.get("dist_km")) is None:
                continue
            _reg["candidatos_avaliados"] += 1
            _alt = {"nome": _nome, "dist_km": _num(_r.get("dist_km")), "vr": _num(_r.get("vr")),
                    "tem_balsa": bool(_r.get("tem_balsa")), "fluvial": bool(_r.get("fluvial")),
                    "tempo_min": _num(_r.get("tempo_min"))}
            _av = _avaliar_troca(_melhor, _alt)
            _reg["alternativas"].append({"nome": _nome, "dist_km": _alt["dist_km"],
                                         "tem_balsa": _alt["tem_balsa"], "trocaria": _av["trocar"],
                                         "motivo": _av["motivo"]})
            if _av["trocar"]:
                _melhor = _alt
                _melhor_troca = _av
        if _melhor_troca and str(_melhor.get("nome")) != str(_nome_esc):
            _reg["decisao"] = "trocou"
            _reg["km_salvo"] = _melhor_troca.get("km_salvo")
            _reg["tempo_salvo_min"] = _melhor_troca.get("tempo_salvo_min")
            _reg["inscritos_beneficiados"] = int(_num(inscritos, 0) or 0)
            _reg["explicacao"] = (f"Refinamento adotou {_melhor.get('nome')} no lugar de {_nome_esc}: "
                                  f"{_melhor_troca.get('motivo')}. Beneficia {int(_num(inscritos,0) or 0)} "
                                  f"candidato(s) desta origem.")
            return {"trocou": True, "destino_final": _melhor.get("nome"),
                    "dist_final_km": _melhor.get("dist_km"), "registro": _reg}
        # manteve — mas registra a justificativa (quando a escolha da app é a melhor mesmo com balsa/circuidade)
        _reg["decisao"] = "manteve"
        _just = ""
        if _reg["alternativas"]:
            _menor_alt = min((a for a in _reg["alternativas"] if a["dist_km"] is not None),
                             key=lambda a: a["dist_km"], default=None)
            if _menor_alt and _menor_alt["dist_km"] is not None and _atual["dist_km"] is not None \
               and _menor_alt["dist_km"] < _atual["dist_km"]:
                _just = _menor_alt["motivo"]
        _reg["explicacao"] = ("Escolha original mantida: nenhuma alternativa mais direta é melhor para o "
                              "candidato." + (f" {_just}." if _just else ""))
        return {"trocou": False, "destino_final": _nome_esc,
                "dist_final_km": _num(escolhido.get("dist_km")), "registro": _reg}
    except Exception as _e:
        _reg["explicacao"] = f"refinamento abortado com segurança ({_e}); escolha original preservada."
        return {"trocou": False, "destino_final": escolhido.get("nome"),
                "dist_final_km": _num(escolhido.get("dist_km")), "registro": _reg}


def _agregar_resgates(registros):
    """Agrega os registros de resgate de um processamento para painéis/relatório/KPIs. PURO."""
    _regs = [r for r in (registros or []) if r]
    _acion = [r for r in _regs if r.get("acionado")]
    _troca = [r for r in _regs if r.get("decisao") == "trocou"]
    _km = sum(abs(_num(r.get("km_salvo"), 0.0) or 0.0) for r in _troca)
    _insc = sum(int(_num(r.get("inscritos_beneficiados"), 0) or 0) for r in _troca)
    import collections as _c
    _ctx = _c.Counter(r.get("contexto") for r in _troca)
    return {"n_acionados": len(_acion), "n_trocas": len(_troca), "km_economizados": round(_km, 1),
            "inscritos_beneficiados": _insc, "por_contexto": dict(_ctx),
            "trocas": [{"origem": r.get("origem"), "uf": r.get("uf"), "destino_final": None,
                        "km_salvo": r.get("km_salvo"), "inscritos": r.get("inscritos_beneficiados"),
                        "explicacao": r.get("explicacao")} for r in _troca]}


def _tempo_min(s):
    """Extrai minutos de textos como '1h 30min', '90 min', '2 h'. Defensivo."""
    try:
        import re as _re
        _t = str(s or "").lower()
        _h = _re.search(r"(\d+)\s*h", _t)
        _m = _re.search(r"(\d+)\s*m", _t)
        _tot = (int(_h.group(1)) * 60 if _h else 0) + (int(_m.group(1)) if _m else 0)
        if _tot == 0:
            _n = _re.search(r"(\d+)", _t)
            _tot = int(_n.group(1)) if _n else None
        return _tot or None
    except Exception:
        return None


def _resgate_por_candidatos(origem, uf, escolhido, cand_names, fn_rota, inscritos=0, params=None,
                            admissivel=False, k_override=None, viaria_estrita=False):
    """[RESGATE-CIRCUIDADE - 238ª] Variante do resgate que recebe uma LISTA JÁ ORDENADA de candidatos (ex.:
    do topk_map da alocação, ordenado por proximidade) — dispensa coordenadas. Roteia cada um pelo motor
    autoritativo (fn_rota) e adota o de menor CUSTO EFETIVO para o candidato, com as MESMAS garantias
    (monotônico, limitado, explicável). Retorna o mesmo formato de _resgate_circuidade."""
    _p = params or {}
    _reg = {"origem": origem, "uf": uf, "acionado": False, "contexto": None, "motivo_gatilho": "",
            "candidatos_avaliados": 0, "alternativas": [], "decisao": "manteve", "km_salvo": None,
            "tempo_salvo_min": None, "inscritos_beneficiados": 0, "explicacao": ""}
    try:
        _nome_esc = escolhido.get("nome")
        _vr = _num(escolhido.get("vr")); _balsa = bool(escolhido.get("tem_balsa")); _fluv = bool(escolhido.get("fluvial"))
        _reg["contexto"] = _classificar_contexto(uf, escolhido.get("reta_km"), _balsa, _fluv)
        _precisa, _motivo = _precisa_resgate(_vr, _balsa, _fluv)
        if not _precisa and not admissivel:
            _reg["explicacao"] = "escolha estável (sem assinatura de risco); refinamento não acionado."
            return {"trocou": False, "destino_final": _nome_esc, "dist_final_km": _num(escolhido.get("dist_km")),
                    "registro": _reg}
        if not _precisa and admissivel:
            _motivo = ("gatilho admissível (branch-and-bound): há candidato mais próximo em linha reta que "
                       "a viária atual — pode existir rota viária menor não avaliada")
        _reg["acionado"] = True; _reg["motivo_gatilho"] = _motivo
        if k_override is not None and int(k_override) > 0:
            _k = int(k_override)
        else:
            _k = _p.get("k_extra_amazonia", _K_EXTRA_AMAZONIA) if str(uf or "").upper()[:2] in _UF_AMAZONIA_RESC \
                else _p.get("k_extra_base", _K_EXTRA_BASE)
        _atual = {"nome": _nome_esc, "dist_km": _num(escolhido.get("dist_km")), "vr": _vr,
                  "tem_balsa": _balsa, "fluvial": _fluv, "tempo_min": _num(escolhido.get("tempo_min")),
                  "reta_km": _num(escolhido.get("reta_km")), "fonte": escolhido.get("fonte", ""),
                  "status": escolhido.get("status", "")}
        _melhor = dict(_atual); _melhor_troca = None
        _usar_viaria = bool(viaria_estrita) and _VIARIA_ESTRITA_ATIVA
        for _nome in (cand_names or [])[:_k]:
            if str(_nome or "").strip().lower() == str(_nome_esc or "").strip().lower():
                continue
            try:
                _r = fn_rota(_nome)
            except Exception:
                _r = None
            if not _r or _num(_r.get("dist_km")) is None:
                continue
            _reg["candidatos_avaliados"] += 1
            _alt = {"nome": _nome, "dist_km": _num(_r.get("dist_km")), "vr": _num(_r.get("vr")),
                    "tem_balsa": bool(_r.get("tem_balsa")), "fluvial": bool(_r.get("fluvial")),
                    "tempo_min": _num(_r.get("tempo_min")), "reta_km": _num(_r.get("reta_km")),
                    "fonte": _r.get("fonte", ""), "status": _r.get("status", "")}
            if _usar_viaria and _EVITAR_BALSA_ATIVO:
                _av = _v316_decidir_terrestre_primeiro(_melhor, _alt)
                # captura da alternativa por balsa mais curta (a menor ao longo do loop) para alerta/colunas.
                _altb = _av.get("alternativa_balsa") if isinstance(_av, dict) else None
                if _altb and _num(_altb.get("dist_km")) is not None:
                    _prev = _reg.get("alternativa_balsa")
                    if (not _prev) or (_num(_prev.get("dist_km")) is None
                                       or _num(_altb["dist_km"]) < _num(_prev["dist_km"])):
                        _reg["alternativa_balsa"] = _altb
                if _av.get("excecao_sem_terrestre"):
                    _reg["excecao_sem_terrestre"] = True
            elif _usar_viaria:
                _av = _v308b_decidir_viaria(_melhor, _alt)
            else:
                _av = _avaliar_troca(_melhor, _alt)
            _reg["alternativas"].append({"nome": _nome, "dist_km": _alt["dist_km"], "tem_balsa": _alt["tem_balsa"],
                                         "trocaria": _av["trocar"], "motivo": _av["motivo"]})
            if _av["trocar"]:
                _melhor = _alt; _melhor_troca = _av
        if _melhor_troca and str(_melhor.get("nome")) != str(_nome_esc):
            _reg["decisao"] = "trocou"; _reg["km_salvo"] = _melhor_troca.get("km_salvo")
            _reg["tempo_salvo_min"] = _melhor_troca.get("tempo_salvo_min")
            _reg["inscritos_beneficiados"] = int(_num(inscritos, 0) or 0)
            _reg["explicacao"] = (f"Refinamento adotou {_melhor.get('nome')} no lugar de {_nome_esc}: "
                                  f"{_melhor_troca.get('motivo')}. Beneficia {int(_num(inscritos,0) or 0)} candidato(s).")
            return {"trocou": True, "destino_final": _melhor.get("nome"),
                    "dist_final_km": _melhor.get("dist_km"), "registro": _reg,
                    "fatos_final": _melhor}
        _reg["decisao"] = "manteve"
        _reg["explicacao"] = "Escolha original mantida: nenhuma alternativa mais direta é melhor para o candidato."
        return {"trocou": False, "destino_final": _nome_esc, "dist_final_km": _num(escolhido.get("dist_km")),
                "registro": _reg}
    except Exception as _e:
        _reg["explicacao"] = f"refinamento abortado com segurança ({_e})."
        return {"trocou": False, "destino_final": escolhido.get("nome"),
                "dist_final_km": _num(escolhido.get("dist_km")), "registro": _reg}


def _refinar_por_resgate_circuidade(df, topk_map, router=None, ativo=True, params=None, topk_completo=None,
                                    viaria_estrita=False):
    """[RESGATE-CIRCUIDADE - 238ª/241ª] PASSE PÓS-ALOCAÇÃO. Percorre o df_final_alo; para cada origem cujo
    destino escolhido exibe a assinatura de risco (V/R alta, balsa ou fluvial), roteia os candidatos mais
    diretos do topk_map pelo motor autoritativo e, se houver alternativa melhor PARA O CANDIDATO, atualiza a
    linha de forma COMPLETA E COERENTE (destino + TODOS os campos dependentes do destino: distância, reta,
    tempo, balsa, fonte, score, coords, município, link da rota e link do mapa) — MONOTÔNICO, LIMITADO, com
    fallback total (qualquer erro preserva a linha original). Retorna (df, registros). Rede via `router`
    (calcular_pipeline_logistico em produção; mock nos testes).
    [241ª] CORRIGE inconsistência: antes só distância/reta/balsa/coords eram atualizados, deixando tempo,
    fonte, score, município e o LINK apontando para o destino ANTIGO. Agora a linha reflete integralmente o
    novo destino. Também: lookup do topk normalizado (casing/espaços) e link do mapa OSRM recomputado."""
    _regs = []
    try:
        if not ativo or df is None or getattr(df, "empty", True):
            return df, _regs
        _router = router if router is not None else globals().get("calcular_pipeline_logistico")
        if _router is None:
            return df, _regs
        _col = {str(c).strip().lower(): c for c in df.columns}
        _c_o, _c_d = _col.get("origem"), _col.get("destino")
        _c_dist, _c_reta = _col.get("distancia"), _col.get("linha reta")
        _c_balsa, _c_fonte = _col.get("balsas"), _col.get("fonte da rota")
        _c_tempo = _col.get("tempo")
        _c_uf = _col.get("uf") or _col.get("uf origem") or _col.get("estado")
        _c_insc = next((_col[k] for k in ("inscritos", "inscritos origem", "qtd inscritos", "candidatos",
                                          "total inscritos", "n inscritos") if k in _col), None)
        if not (_c_o and _c_d and _c_dist and _c_reta):
            return df, _regs  # sem colunas mínimas → no-op seguro
        # índice normalizado do topk (robusto a casing/espaços entre df['Origem'] e as chaves do topk)
        _topk_norm = {}
        try:
            for _k, _v in (topk_map or {}).items():
                _topk_norm[str(_k).strip().lower()] = _v
        except Exception:
            _topk_norm = {}
        # [V308 · FATIA 2a] índice normalizado da lista COMPLETA (todos os polos por reta) para o gatilho
        # admissível. Se topk_completo não vier, cai no topk_map (comportamento v307 preservado).
        _topkc = topk_completo if topk_completo else topk_map
        _topkc_norm = {}
        try:
            for _k, _v in (_topkc or {}).items():
                _topkc_norm[str(_k).strip().lower()] = _v
        except Exception:
            _topkc_norm = {}
        # mapa coluna(df) -> atributo(RotaPipeline) para atualização COMPLETA e coerente
        _MAP_RP = {
            "distancia": "distancia", "tempo": "tempo", "link da rota": "link_rota", "balsas": "balsas",
            "linha reta": "dist_linha_reta", "fonte da rota": "fonte_rota", "score da rota": "score_rota",
            "confianca destino": "confianca_destino", "distrito destino": "distrito_destino",
            "municipio destino": "municipio_destino", "fonte geocoding destino": "fonte_geo_destino",
            "endereco oficial destino": "endereco_oficial_destino", "score num destino": "score_num_destino",
            "lat destino": "lat_destino", "lon destino": "lon_destino", "link embed": "link_embed",
        }
        _link_osrm = globals().get("_link_osrm_publico")
        _max_resgates = int((params or {}).get("max_resgates", 500) or 500)  # teto do pior caso (rede)

        # FASE 1 [244ª]: coleta as linhas com assinatura de risco e PRIORIZA por impacto (excesso de
        # circuidade em km × candidatos). Assim o teto gasta o orçamento de rede nos casos mais valiosos —
        # o que torna seguro baixar o gatilho de V/R para 1,45 sem penalizar runs nacionais.
        _candidatas = []
        for _idx in list(df.index):
            try:
                _origem = str(df.at[_idx, _c_o] or "").strip()
                _destino = str(df.at[_idx, _c_d] or "").strip()
                _dist = _num(df.at[_idx, _c_dist]); _reta = _num(df.at[_idx, _c_reta])
                if not _origem or not _destino or _dist is None or not _reta or _reta <= 0:
                    continue
                _vr = _dist / _reta
                _balsa = (str(df.at[_idx, _c_balsa]).strip().lower() == "sim") if _c_balsa else False
                _fonte = (str(df.at[_idx, _c_fonte]).lower()) if _c_fonte else ""
                _fluvial = ("fluvial" in _fonte) or ("isolado" in _fonte) or ("sem rota" in _fonte)
                _precisa, _ = _precisa_resgate(_vr, _balsa, _fluvial)
                # [V308 · FATIA 2a] GATILHO ADMISSÍVEL: mesmo SEM assinatura de risco, se existe candidato
                # NÃO roteado cuja LINHA RETA < viária atual, ele PODE ter rota viária menor (viária >= reta)
                # e DEVE ser avaliado. Foi o que faltou em Guajará-Mirim/Nova Mamoré.
                _admissivel = False
                _cands_c = (_topkc_norm.get(_origem.strip().lower()) or _topk_norm.get(_origem.strip().lower()) or [])
                if not _precisa and _RESGATE_ADMISSIVEL_ATIVO:
                    try:
                        for (_dd, _h) in _cands_c:
                            if str(_h).strip().lower() == _destino.lower():
                                continue
                            _rr = _num(_dd)
                            if _rr is not None and _rr < _dist - _MARGEM_ADMISSIVEL_KM:
                                _admissivel = True
                                break
                    except Exception:
                        _admissivel = False
                if not _precisa and not _admissivel:
                    continue
                _insc = _num(df.at[_idx, _c_insc], 0) if _c_insc else 0
                _exc = max(_dist - _reta, 0.0)  # excesso de circuidade em km
                if _admissivel and not _precisa:
                    # prioridade admissível: ganho POTENCIAL máximo = (viária atual - melhor reta candidata)
                    # x inscritos. É um limite superior do que se pode economizar — dirige o orçamento de rede.
                    try:
                        _best_reta = min((_num(_dd) for (_dd, _h) in _cands_c
                                          if str(_h).strip().lower() != _destino.lower()
                                          and _num(_dd) is not None), default=_reta)
                    except Exception:
                        _best_reta = _reta
                    _prio = max(_dist - (_best_reta if _best_reta is not None else _reta), 0.0) * max(_num(_insc, 0) or 0.0, 1.0)
                else:
                    _prio = (max(_exc, 15.0) if (_balsa or _fluvial) else _exc) * max(_num(_insc, 0) or 0.0, 1.0)
                _candidatas.append((_prio, _idx, _origem, _destino, _dist, _reta, _vr, _balsa, _fluvial, _insc, _admissivel))
            except Exception:
                continue
        _candidatas.sort(key=lambda x: x[0], reverse=True)  # maior impacto primeiro

        # FASE 2 [244ª]: roteia e atualiza as linhas de maior impacto, respeitando o teto.
        for (_prio, _idx, _origem, _destino, _dist, _reta, _vr, _balsa, _fluvial, _insc, _admissivel) in _candidatas[:_max_resgates]:
            try:
                _uf = (str(df.at[_idx, _c_uf]).strip() if _c_uf else "")
                if _admissivel:
                    # [V308 · FATIA 2a] lista COMPLETA e branch-and-bound: só os polos cuja reta < viária
                    # atual podem vencer (prefixo ordenado por reta), com teto de rede.
                    _cands = (_topkc_norm.get(_origem.strip().lower()) or _topk_norm.get(_origem.strip().lower()) or [])
                    _nomes = [h for (_dd, h) in _cands
                              if str(h).strip().lower() != _destino.lower()
                              and _num(_dd) is not None and _num(_dd) < _dist][:_MAX_ADMISSIVEL_ROTEAR]
                else:
                    _cands = (topk_map.get(_origem) or _topk_norm.get(_origem.strip().lower()) or [])
                    _nomes = [h for (_dd, h) in _cands if str(h).strip().lower() != _destino.lower()]
                if not _nomes:
                    continue
                _origem_q = f"{_origem}, {_uf}" if _uf else _origem
                _cache = {}
                _cache_rp = {}  # guarda a RotaPipeline crua p/ atualização completa da linha

                def _fn_rota(_hub):
                    if _hub in _cache:
                        return _cache[_hub]
                    try:
                        _rp = _router(_origem_q, _hub)
                        _cache_rp[_hub] = _rp
                        _d = _num(getattr(_rp, "distancia", None)); _rr = _num(getattr(_rp, "dist_linha_reta", None))
                        _fonte_rp = str(getattr(_rp, "fonte_rota", "") or "")
                        _status_rp = str(getattr(_rp, "status_linha_reta", "") or getattr(_rp, "motivo_roteamento", "") or "")
                        _fluv_rp = any(_m in (_fonte_rp + " " + _status_rp).lower()
                                       for _m in ("fluvial", "isolado", "sem rota", "sem malha"))
                        _out = {"dist_km": _d, "reta_km": _rr,
                                "vr": (_d / _rr if (_d and _rr and _rr > 0) else None),
                                "tem_balsa": str(getattr(_rp, "balsas", "")).strip().lower() == "sim",
                                "fluvial": _fluv_rp, "tempo_min": _tempo_min(getattr(_rp, "tempo", "")),
                                "lat": _num(getattr(_rp, "lat_destino", None)),
                                "lon": _num(getattr(_rp, "lon_destino", None)),
                                "fonte": _fonte_rp, "status": _status_rp}
                    except Exception:
                        _out = None
                    _cache[_hub] = _out
                    return _out

                _esc = {"nome": _destino, "dist_km": _dist, "reta_km": _reta, "vr": _vr,
                        "tem_balsa": _balsa, "fluvial": _fluvial,
                        "tempo_min": _tempo_min(df.at[_idx, _c_tempo]) if _c_tempo else None,
                        "fonte": (str(df.at[_idx, _c_fonte]) if _c_fonte else ""),
                        "status": (str(df.at[_idx, _col.get("status da rota")]) if _col.get("status da rota") else "")}
                _res = _resgate_por_candidatos(_origem, _uf, _esc, _nomes, _fn_rota, inscritos=_insc, params=params,
                                               admissivel=_admissivel,
                                               k_override=(len(_nomes) if _admissivel else None),
                                               viaria_estrita=viaria_estrita)
                _regs.append(_res["registro"])
                if _res.get("trocou"):
                    _rp_novo = _cache_rp.get(_res["destino_final"])
                    df.at[_idx, _c_d] = _res["destino_final"]
                    if _rp_novo is not None:
                        # atualização COMPLETA de todos os campos dependentes do destino que existirem no df
                        for _low, _attr in _MAP_RP.items():
                            _cc = _col.get(_low)
                            if _cc is None:
                                continue
                            try:
                                _val = getattr(_rp_novo, _attr, None)
                            except Exception:
                                _val = None
                            if _val is not None:
                                try:
                                    df.at[_idx, _cc] = _val
                                except Exception:
                                    pass
                        # link do mapa OSRM recomputado a partir das coordenadas novas (custo zero)
                        _cc_osrm = _col.get("link mapa osrm")
                        if _cc_osrm is not None and callable(_link_osrm):
                            try:
                                _lo = _num(getattr(_rp_novo, "lat_origem", None)); _oo = _num(getattr(_rp_novo, "lon_origem", None))
                                _ld = _num(getattr(_rp_novo, "lat_destino", None)); _od = _num(getattr(_rp_novo, "lon_destino", None))
                                _lk = _link_osrm(_lo or 0.0, _oo or 0.0, _ld or 0.0, _od or 0.0)
                                if _lk:
                                    df.at[_idx, _cc_osrm] = _lk
                            except Exception:
                                pass
                    else:
                        # fallback (sem rp cru): ao menos a distância final
                        df.at[_idx, _c_dist] = _num(_res.get("dist_final_km"), _dist)
                    # marca a linha como refinada + explicação (colunas novas, aditivas)
                    df.at[_idx, "Refinado (Resgate)"] = "Sim"
                    df.at[_idx, "Motivo do Refinamento"] = _res["registro"].get("explicacao", "")
            except Exception:
                continue  # linha problemática → preservada como estava
        return df, _regs
    except Exception:
        return df, _regs
# <<< [RESGATE-CIRCUIDADE 238ª] FIM >>>




# <<< [DIVERGENCIA-XAI-3 239ª] INÍCIO — auditoria avançada (KPIs extremos, recortes, motivo granular, árvore) >>>
# ==============================================================================
# [DIVERGENCIA-XAI-3 - 239ª geração] AUDITORIA AVANÇADA DO COMPARADOR
# ------------------------------------------------------------------------------
# Incrementos NOVOS sobre o motor de divergências (236/237). Puro e testável.
# Adiciona: KPIs avançados (maior derrota/vitória/economia, municípios mais
# problemáticos, motores mais vencedores/derrotados, precisão por dimensão),
# recortes estatísticos por faixa (distância, V/R, inscritos), motivo GRANULAR
# da derrota (qual motor achou a rota menor) e ÁRVORE DE DECISÃO por divergência.
# ==============================================================================


def _n3(v, d=None):
    try:
        if v is None or (isinstance(v, float) and v != v):
            return d
        return float(v)
    except (TypeError, ValueError):
        return d


def _motivo_granular(analise):
    """[DIVERGENCIA-XAI-3 - 239ª] Motivo GRANULAR da divergência, atribuindo ao MOTOR quando aplicável
    (item 3 do doc: 'Google encontrou rota menor', 'OSRM encontrou rota menor'…). PURO."""
    _venc = str(analise.get("Vencedor (Qualidade)") or "")
    _cat = str(analise.get("Categoria") or "")
    _ma = str(analise.get("Motor Aplicação") or "").upper()
    _mr = str(analise.get("Motor Referência") or "").upper()
    _dif = _n3(analise.get("Diferença (km)"), 0.0) or 0.0
    _divm = _n3(analise.get("Divergência Motores (%)"), 0.0) or 0.0
    def _mnome(m):
        for _k in ("GOOGLE", "OSRM", "GRAPHHOPPER", "VALHALLA"):
            if _k in m:
                return _k.capitalize() if _k != "OSRM" else "OSRM"
        return "outro motor"
    # quem tem a rota menor?
    if _venc == "Referência" and _dif > 0:  # ref mais curta
        _base = f"{_mnome(_mr)} (referência) encontrou uma rota {abs(_dif):.0f} km menor"
    elif _venc == "Aplicação" and _dif < 0:
        _base = f"{_mnome(_ma)} (aplicação) encontrou uma rota {abs(_dif):.0f} km menor"
    else:
        _base = "diferença dentro do erro esperado entre fontes"
    _extra = []
    if _ma and _mr and _mnome(_ma) != _mnome(_mr):
        _extra.append(f"motores distintos ({_mnome(_ma)} × {_mnome(_mr)})")
    if _divm >= 30:
        _extra.append(f"alta divergência entre malhas ({_divm:.0f}%)")
    if "balsa" in _cat.lower():
        _extra.append("dependência de balsa em um dos lados")
    if "sinuos" in _cat.lower():
        _extra.append("trajeto mais sinuoso de um lado")
    return _base + (" — " + "; ".join(_extra) if _extra else "")


def _faixa(v, cortes, rotulos):
    for _i, _c in enumerate(cortes):
        if v < _c:
            return rotulos[_i]
    return rotulos[-1]


def _distribuicoes_avancadas(analises):
    """[DIVERGENCIA-XAI-3 - 239ª] Recortes por FAIXA (item 8 do doc): distância, razão V/R, inscritos e
    diferença de tempo. Conta casos e inscritos por faixa. PURO."""
    import collections as _c
    _out = {}
    _defs = {
        "por_faixa_distancia": (lambda a: _n3(a.get("Distância Aplicação (km)")),
                                [50, 100, 200, 400], ["até 50 km", "50–100", "100–200", "200–400", "acima de 400"]),
        "por_faixa_vr": (lambda a: _n3(a.get("Sinuosidade Aplicação (V/R)")),
                         [1.2, 1.5, 2.0, 3.0], ["≤1,2× (direta)", "1,2–1,5×", "1,5–2,0×", "2,0–3,0×", ">3,0× (severa)"]),
        "por_faixa_inscritos": (lambda a: _n3(a.get("Inscritos")),
                                [50, 200, 500, 1000], ["até 50", "50–200", "200–500", "500–1000", "acima de 1000"]),
        "por_faixa_dif_tempo": (lambda a: abs(_n3(a.get("Diferença Tempo (min)"), 0.0) or 0.0),
                                [10, 30, 60, 120], ["≤10 min", "10–30", "30–60", "60–120", ">120 min"]),
    }
    for _nome, (_fx, _cortes, _rot) in _defs.items():
        _cnt = _c.Counter(); _ins = _c.Counter()
        for a in (analises or []):
            _v = _fx(a)
            if _v is None:
                continue
            _f = _faixa(_v, _cortes, _rot)
            _cnt[_f] += 1
            _ins[_f] += int(_n3(a.get("Inscritos"), 0) or 0)
        _out[_nome] = [{"Categoria": _r, "Casos": _cnt.get(_r, 0), "Inscritos": _ins.get(_r, 0)}
                       for _r in _rot if _cnt.get(_r, 0)]
    return _out


def _kpis_avancados(analises):
    """[DIVERGENCIA-XAI-3 - 239ª] KPIs de EXTREMOS e PRECISÃO (item 9 do doc): maior derrota/vitória/economia,
    maiores diferenças, municípios mais problemáticos, motores mais vencedores/derrotados e precisão por
    dimensão. Cada KPI traz o registro (município/valor) e helper/fórmula/interpretação. PURO."""
    import collections as _c
    _tot = len(analises or [])
    if _tot == 0:
        return {"extremos": [], "ranking_motores": [], "municipios_problematicos": [], "precisao": []}
    _derr = [a for a in analises if str(a.get("Vencedor (Qualidade)")) == "Referência"]
    _vit = [a for a in analises if str(a.get("Vencedor (Qualidade)")) == "Aplicação"]

    def _rec(lista, chave, absoluto=True):
        _best = None; _bv = None
        for a in lista:
            _v = _n3(a.get(chave))
            if _v is None:
                continue
            _cmp = abs(_v) if absoluto else _v
            if _bv is None or _cmp > _bv:
                _bv = _cmp; _best = a
        return _best

    _extremos = []
    _md = _rec(_derr, "Diferença (km)")
    if _md:
        _extremos.append({"kpi": "Maior derrota (km)", "municipio": f"{_md.get('Município')}/{_md.get('UF')}",
                          "valor": round(abs(_n3(_md.get("Diferença (km)"), 0)), 1), "unidade": "km",
                          "formula": "máx |Δkm| entre as derrotas", "helper": "Derrota com maior diferença de distância.",
                          "interpretacao": "Foco prioritário de auditoria/otimização."})
    _mv = _rec(_vit, "Diferença (km)")
    if _mv:
        _extremos.append({"kpi": "Maior vitória (km)", "municipio": f"{_mv.get('Município')}/{_mv.get('UF')}",
                          "valor": round(abs(_n3(_mv.get("Diferença (km)"), 0)), 1), "unidade": "km",
                          "formula": "máx |Δkm| entre as vitórias", "helper": "Vitória com maior economia de distância.",
                          "interpretacao": "Onde a aplicação mais beneficia o candidato."})
    _mt = _rec(analises, "Diferença Tempo (min)")
    if _mt:
        _extremos.append({"kpi": "Maior diferença de tempo", "municipio": f"{_mt.get('Município')}/{_mt.get('UF')}",
                          "valor": round(abs(_n3(_mt.get("Diferença Tempo (min)"), 0)), 0), "unidade": "min",
                          "formula": "máx |Δtempo|", "helper": "Maior diferença de tempo de deslocamento.",
                          "interpretacao": "Alto impacto na experiência do candidato."})
    _ms = _rec(analises, "Sinuosidade Aplicação (V/R)", absoluto=False)
    if _ms:
        _extremos.append({"kpi": "Maior sinuosidade (V/R)", "municipio": f"{_ms.get('Município')}/{_ms.get('UF')}",
                          "valor": round(_n3(_ms.get("Sinuosidade Aplicação (V/R)"), 0), 2), "unidade": "×",
                          "formula": "máx V/R da aplicação", "helper": "Rota mais indireta escolhida pela aplicação.",
                          "interpretacao": "Candidata nº 1 ao resgate por circuidade."})
    _eco = sum(abs(_n3(a.get("Diferença (km)"), 0.0) or 0.0) for a in _vit)
    _extremos.append({"kpi": "Economia total (vitórias)", "municipio": "—", "valor": round(_eco, 0), "unidade": "km",
                      "formula": "Σ |Δkm| das vitórias", "helper": "Km que a aplicação economiza vs a referência.",
                      "interpretacao": "Benefício agregado ao conjunto de candidatos."})

    # ranking de motores (vencedores × derrotados)
    _rank = _c.Counter(); _rankd = _c.Counter()
    for a in analises:
        _venc = str(a.get("Vencedor (Qualidade)"))
        _m_venc = a.get("Motor Aplicação") if _venc == "Aplicação" else (a.get("Motor Referência") if _venc == "Referência" else None)
        _m_perd = a.get("Motor Referência") if _venc == "Aplicação" else (a.get("Motor Aplicação") if _venc == "Referência" else None)
        if _m_venc:
            _rank[str(_m_venc)] += 1
        if _m_perd:
            _rankd[str(_m_perd)] += 1
    _ranking = [{"motor": _m, "vitorias": _rank.get(_m, 0), "derrotas": _rankd.get(_m, 0)}
                for _m in sorted(set(list(_rank) + list(_rankd)), key=lambda x: -_rank.get(x, 0))]

    # municípios mais problemáticos (derrotas de maior impacto km×inscritos)
    _prob = sorted(_derr, key=lambda a: abs((_n3(a.get("Diferença (km)"), 0.0) or 0.0)
                   * (int(_n3(a.get("Inscritos"), 0) or 0) or 1)), reverse=True)[:15]
    _municipios = [{"municipio": f"{a.get('Município')}/{a.get('UF')}",
                    "impacto_km_insc": round(abs((_n3(a.get("Diferença (km)"), 0.0) or 0.0)
                                                  * (int(_n3(a.get("Inscritos"), 0) or 0) or 1)), 0),
                    "dif_km": round(abs(_n3(a.get("Diferença (km)"), 0.0) or 0.0), 1),
                    "inscritos": int(_n3(a.get("Inscritos"), 0) or 0),
                    "classe": a.get("Classe da Derrota", a.get("Categoria", "—"))} for a in _prob]

    # precisão por dimensão = % de não-derrota (vitória+empate) por UF/região/acesso
    def _precisao_por(chave):
        _por = _c.defaultdict(lambda: [0, 0])
        for a in analises:
            _k = str(a.get(chave) or "—")
            _por[_k][1] += 1
            if str(a.get("Vencedor (Qualidade)")) != "Referência":
                _por[_k][0] += 1
        return [{"grupo": _k, "precisao_pct": round(100.0 * _ok / _t, 1), "casos": _t}
                for _k, (_ok, _t) in sorted(_por.items(), key=lambda kv: -kv[1][1]) if _t]
    _precisao = {"por_uf": _precisao_por("UF"), "por_acesso": _precisao_por("Acesso Aplicação")}

    return {"extremos": _extremos, "ranking_motores": _ranking,
            "municipios_problematicos": _municipios, "precisao": _precisao}


def _arvore_divergencia(analise):
    """[DIVERGENCIA-XAI-3 - 239ª] ÁRVORE DE DECISÃO por divergência (item 4 do doc): por que a app escolheu A,
    por que a ref escolheu B, e quem beneficia mais o candidato — tudo a partir dos fatos já calculados. PURO."""
    _mun = f"{analise.get('Município','?')}/{analise.get('UF','?')}"
    _da = _n3(analise.get("Distância Aplicação (km)")); _dr = _n3(analise.get("Distância Referência (km)"))
    _va = _n3(analise.get("Sinuosidade Aplicação (V/R)")); _vr = _n3(analise.get("Sinuosidade Referência (V/R)"))
    _ba = str(analise.get("Balsa Aplicação") or "").lower() == "sim"
    _br = str(analise.get("Balsa Referência") or "").lower() == "sim"
    _venc = str(analise.get("Vencedor (Qualidade)"))

    def _porques(dist, vr, balsa, outro_dist, outro_balsa, outro_vr):
        _p = []
        if dist is not None and outro_dist is not None and dist < outro_dist:
            _p.append(f"menor distância viária ({dist:.0f} km)")
        if vr is not None and vr < 1.4:
            _p.append(f"rota direta (V/R {vr:.2f}×)")
        elif vr is not None and outro_vr is not None and vr < outro_vr - 0.2:
            _p.append(f"rota mais direta que a alternativa (V/R {vr:.2f}× vs {outro_vr:.2f}×)")
        if not balsa and outro_balsa:
            _p.append("sem dependência de balsa")
        if balsa and not outro_balsa:
            _p.append("aceita travessia por balsa")
        if vr is not None and vr >= 2.0:
            _p.append(f"apesar de rota indireta (V/R {vr:.2f}×)")
        return _p or ["critério multicritério"]

    _no_app = {"destino": analise.get("Destino Aplicação", "—"),
               "porques": _porques(_da, _va, _ba, _dr, _br, _vr)}
    _no_ref = {"destino": analise.get("Destino Referência", "—"),
               "porques": _porques(_dr, _vr, _br, _da, _ba, _va)}
    _benef = ("A aplicação" if _venc == "Aplicação" else "A referência" if _venc == "Referência" else "Empate técnico")
    _motivo = analise.get("Parecer Técnico") or _motivo_granular(analise)
    return {"municipio": _mun, "app": _no_app, "ref": _no_ref, "beneficia": _benef,
            "vencedor": _venc, "motivo": _motivo}


def _arvore_divergencia_texto(arv):
    _L = [f"ÁRVORE — {arv['municipio']}"]
    _L.append(f"  ├─ Aplicação escolheu {arv['app']['destino']}")
    for p in arv['app']['porques']:
        _L.append(f"  │    ✔ {p}")
    _L.append(f"  ├─ Referência escolheu {arv['ref']['destino']}")
    for p in arv['ref']['porques']:
        _L.append(f"  │    ✔ {p}")
    _L.append(f"  └─ Quem beneficia mais o candidato: {arv['beneficia']}")
    return "\n".join(_L)


def _arvore_divergencia_html(arv, _he):
    def _e(x):
        return _he.escape(str(x))
    _pa = "".join(f"<li>{_e(p)}</li>" for p in arv['app']['porques'])
    _pr = "".join(f"<li>{_e(p)}</li>" for p in arv['ref']['porques'])
    _cor = "#16a34a" if arv['vencedor'] == "Aplicação" else "#dc2626" if arv['vencedor'] == "Referência" else "#64748b"
    return (f'<div class="arvd"><div class="arvd-h">🌳 {_e(arv["municipio"])}</div>'
            f'<div class="arvd-cols"><div class="arvd-c"><div class="arvd-t">Aplicação → '
            f'{_e(arv["app"]["destino"])}</div><ul>{_pa}</ul></div>'
            f'<div class="arvd-c"><div class="arvd-t">Referência → {_e(arv["ref"]["destino"])}</div>'
            f'<ul>{_pr}</ul></div></div>'
            f'<div class="arvd-b" style="border-color:{_cor}">Quem beneficia mais o candidato: '
            f'<b style="color:{_cor}">{_e(arv["beneficia"])}</b></div></div>')


