                    _dc[1].metric("Linha reta", (f"{_det['linha_reta_km']:.1f} km" if isinstance(_det["linha_reta_km"], (int, float)) else "—"))
                    _dc[2].metric("Razão viária/reta", (f"{_det['razao_vr']:.2f}×" if _det.get("razao_vr") else "—"))
